


SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "public";


ALTER SCHEMA "public" OWNER TO "pg_database_owner";


COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE TYPE "public"."shift_request_status" AS ENUM (
    'pending',
    'approved',
    'rejected',
    'cancelled'
);


ALTER TYPE "public"."shift_request_status" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_auth_v2_check_area_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_code TEXT;
BEGIN
  IF NEW.area_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT legacy_role_code INTO v_code
  FROM public.positions WHERE id = NEW.position_id;
  IF v_code IS NULL OR v_code NOT IN ('area_manager','warehouse_manager','production_manager') THEN
    RAISE EXCEPTION 'area_id only allowed for area_manager / warehouse_manager / production_manager (got %)', COALESCE(v_code, '<null>')
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_auth_v2_check_area_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_auth_v2_check_branch_required"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_code TEXT;
BEGIN
  SELECT legacy_role_code INTO v_code
  FROM public.positions WHERE id = NEW.position_id;

  IF v_code IN ('cashier','waiter','chef','branch_manager','warehouse_manager','production_manager')
     AND NEW.branch_id IS NULL THEN
    RAISE EXCEPTION 'branch_required_for_operational_role: position=%', v_code
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_auth_v2_check_branch_required"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_auth_v2_is_owner"("p_user" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles pr
    JOIN public.positions po ON po.id = pr.position_id
    WHERE pr.id = p_user AND po.code = 'owner'
  );
$$;


ALTER FUNCTION "public"."_auth_v2_is_owner"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_auth_v2_position_id_from_role"("p_role" "text", "p_tenant" bigint) RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT id
  FROM public.positions
  WHERE tenant_id = p_tenant
    AND code = public._auth_v2_role_to_position(p_role)
  LIMIT 1;
$$;


ALTER FUNCTION "public"."_auth_v2_position_id_from_role"("p_role" "text", "p_tenant" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_auth_v2_role_to_position"("p_role" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT CASE p_role
    WHEN 'owner'              THEN 'owner'
    WHEN 'super_manager'      THEN 'super_manager'
    WHEN 'area_manager'       THEN 'quan_ly_vung'
    WHEN 'branch_manager'     THEN 'quan_ly_CN'
    WHEN 'warehouse_manager'  THEN 'kho_truong'
    WHEN 'production_manager' THEN 'bep_truong'
    WHEN 'cashier'            THEN 'cashier'
    WHEN 'waiter'             THEN 'waiter'
    WHEN 'chef'               THEN 'chef'
    WHEN 'office'             THEN 'office'
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."_auth_v2_role_to_position"("p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_compute_grn_price_baseline"("p_tenant_id" bigint, "p_supplier_id" bigint, "p_ingredient_id" bigint, "p_uom" "text" DEFAULT NULL::"text") RETURNS TABLE("avg_30d" numeric, "sample_n" integer, "last_seen_at" "date", "baseline_source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_pause_until DATE; v_primary RECORD; v_fallback RECORD;
BEGIN
  SELECT MAX(paused_until) INTO v_pause_until FROM public.grn_baseline_pause
    WHERE tenant_id = p_tenant_id AND supplier_id = p_supplier_id AND ingredient_id = p_ingredient_id
      AND (p_uom IS NULL OR uom = p_uom) AND paused_until >= CURRENT_DATE;
  IF v_pause_until IS NOT NULL THEN RETURN QUERY SELECT NULL::NUMERIC(15,2), 0, NULL::DATE, 'paused'::TEXT; RETURN; END IF;

  SELECT b.avg_30d, b.sample_n, b.last_seen_at INTO v_primary
  FROM public.mv_grn_price_baseline b
  WHERE b.tenant_id = p_tenant_id AND b.supplier_id = p_supplier_id AND b.ingredient_id = p_ingredient_id
    AND (p_uom IS NULL OR b.uom = p_uom);
  IF FOUND AND v_primary.sample_n >= 3 THEN
    RETURN QUERY SELECT v_primary.avg_30d, v_primary.sample_n, v_primary.last_seen_at, 'same_supplier'::TEXT; RETURN;
  END IF;

  SELECT (SUM(b.avg_30d * b.sample_n) / NULLIF(SUM(b.sample_n), 0))::NUMERIC(15,2) AS avg_30d,
         SUM(b.sample_n)::INT AS sample_n, MAX(b.last_seen_at) AS last_seen_at
    INTO v_fallback FROM public.mv_grn_price_baseline b
  WHERE b.tenant_id = p_tenant_id AND b.ingredient_id = p_ingredient_id AND (p_uom IS NULL OR b.uom = p_uom);
  IF v_fallback.sample_n IS NOT NULL AND v_fallback.sample_n >= 3 THEN
    RETURN QUERY SELECT v_fallback.avg_30d, v_fallback.sample_n, v_fallback.last_seen_at, 'any_supplier'::TEXT; RETURN;
  END IF;

  RETURN QUERY SELECT NULL::NUMERIC(15,2), 0, NULL::DATE, 'none'::TEXT;
END; $$;


ALTER FUNCTION "public"."_compute_grn_price_baseline"("p_tenant_id" bigint, "p_supplier_id" bigint, "p_ingredient_id" bigint, "p_uom" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_compute_vat_breakdown"("p_order_ids" bigint[]) RETURNS TABLE("vat_rate" numeric, "line_gross" numeric, "line_subtotal" numeric, "line_vat" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH order_items_sum AS (
    SELECT
      oi.order_id,
      SUM(oi.subtotal) AS items_sum
    FROM public.order_items oi
    WHERE oi.order_id = ANY(p_order_ids)
      AND oi.status <> 'cancelled'
    GROUP BY oi.order_id
  ),
  scaled AS (
    SELECT
      oi.vat_rate,
      (oi.subtotal * (o.total_amount / NULLIF(ois.items_sum, 0))) AS gross
    FROM public.order_items oi
    JOIN public.orders o            ON o.id = oi.order_id
    JOIN order_items_sum ois        ON ois.order_id = oi.order_id
    WHERE oi.order_id = ANY(p_order_ids)
      AND oi.status <> 'cancelled'
      AND ois.items_sum > 0
  ),
  by_rate AS (
    SELECT
      scaled.vat_rate,
      SUM(scaled.gross)::numeric(15,2) AS line_gross
    FROM scaled
    GROUP BY scaled.vat_rate
  )
  SELECT
    by_rate.vat_rate,
    by_rate.line_gross,
    (by_rate.line_gross / (1 + by_rate.vat_rate / 100))::numeric(15,2) AS line_subtotal,
    (by_rate.line_gross
       - (by_rate.line_gross / (1 + by_rate.vat_rate / 100))::numeric(15,2)
    )::numeric(15,2) AS line_vat
  FROM by_rate
  ORDER BY by_rate.vat_rate;
$$;


ALTER FUNCTION "public"."_compute_vat_breakdown"("p_order_ids" bigint[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_compute_vat_breakdown"("p_order_ids" bigint[]) IS 'Per-line VAT aggregation across input orders. Mirrors apps/web/app/finance/actions.ts:128-186. Scale absorbs order-level discount. Returns 1 row per VAT rate present.';



CREATE OR REPLACE FUNCTION "public"."acquire_zone_lock"("p_session_id" bigint, "p_zone_id" "text", "p_ttl_seconds" integer DEFAULT 1800) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_tenant BIGINT; v_branch BIGINT; v_existing RECORD; v_acquired BOOLEAN := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_ttl_seconds <= 0 OR p_ttl_seconds > 7200 THEN RAISE EXCEPTION 'ttl_seconds must be in (0, 7200]' USING ERRCODE = '22023'; END IF;
  SELECT ss.tenant_id, ss.branch_id INTO v_tenant, v_branch FROM public.stocktake_sessions ss WHERE ss.id = p_session_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_branch, 'inventory:stocktake_create') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  DELETE FROM public.stocktake_zone_locks WHERE session_id = p_session_id AND zone_id = p_zone_id AND expires_at <= now();
  INSERT INTO public.stocktake_zone_locks (tenant_id, session_id, zone_id, locked_by, acquired_at, last_heartbeat_at, expires_at)
  VALUES (v_tenant, p_session_id, p_zone_id, v_uid, now(), now(), now() + make_interval(secs => p_ttl_seconds))
  ON CONFLICT (session_id, zone_id) DO UPDATE
    SET locked_by = CASE WHEN public.stocktake_zone_locks.locked_by = v_uid THEN v_uid ELSE public.stocktake_zone_locks.locked_by END,
        acquired_at = CASE WHEN public.stocktake_zone_locks.locked_by = v_uid THEN now() ELSE public.stocktake_zone_locks.acquired_at END,
        last_heartbeat_at = CASE WHEN public.stocktake_zone_locks.locked_by = v_uid THEN now() ELSE public.stocktake_zone_locks.last_heartbeat_at END,
        expires_at = CASE WHEN public.stocktake_zone_locks.locked_by = v_uid THEN now() + make_interval(secs => p_ttl_seconds) ELSE public.stocktake_zone_locks.expires_at END
    WHERE public.stocktake_zone_locks.locked_by = v_uid;
  SELECT * INTO v_existing FROM public.stocktake_zone_locks WHERE session_id = p_session_id AND zone_id = p_zone_id;
  v_acquired := v_existing.locked_by = v_uid;
  RETURN jsonb_build_object('acquired', v_acquired, 'locked_by', v_existing.locked_by, 'expires_at', v_existing.expires_at, 'acquired_at', v_existing.acquired_at);
END; $$;


ALTER FUNCTION "public"."acquire_zone_lock"("p_session_id" bigint, "p_zone_id" "text", "p_ttl_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_profile"("p_target_id" "uuid", "p_full_name" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_role" "text" DEFAULT NULL::"text", "p_branch_id" bigint DEFAULT NULL::bigint, "p_is_active" boolean DEFAULT NULL::boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id        UUID := auth.uid();
  v_actor_tenant    BIGINT;
  v_actor_role_text TEXT;
  v_actor_branch    BIGINT;
  v_actor_area      BIGINT;
  v_target          RECORD;
  v_target_role     TEXT;
  v_final_role      TEXT;
  v_final_branch    BIGINT;
  v_final_position  BIGINT;
  v_branch_kind     TEXT;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT
    p.tenant_id,
    COALESCE(po.legacy_role_code, 'unassigned') AS role_text,
    p.branch_id,
    p.area_id
  INTO v_actor_tenant, v_actor_role_text, v_actor_branch, v_actor_area
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_actor_id
    AND COALESCE(p.is_active, true) = true;

  IF NOT FOUND OR v_actor_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('staff:manage') THEN
    RAISE EXCEPTION 'forbidden: missing staff:manage' USING ERRCODE = '42501';
  END IF;

  IF (p_role IS NOT NULL OR p_branch_id IS NOT NULL)
     AND NOT public.has_permission_any('staff:assign_position') THEN
    RAISE EXCEPTION 'forbidden: missing staff:assign_position' USING ERRCODE = '42501';
  END IF;

  IF p_role IS NOT NULL AND p_role NOT IN (
    'owner','super_manager','area_manager','branch_manager',
    'warehouse_manager','production_manager','cashier','waiter','chef','office'
  ) THEN
    RAISE EXCEPTION 'invalid_role: %', p_role USING ERRCODE = '22023';
  END IF;

  SELECT
    p.id, p.branch_id, p.full_name, p.phone, p.tenant_id, p.position_id,
    COALESCE(po.legacy_role_code, 'unassigned') AS role_text
  INTO v_target
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = p_target_id AND p.tenant_id = v_actor_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'target profile not found in tenant';
  END IF;

  v_target_role  := v_target.role_text;
  v_final_role   := COALESCE(p_role, v_target_role);
  v_final_branch := COALESCE(p_branch_id, v_target.branch_id);

  IF v_final_role IN ('cashier','waiter','chef','branch_manager','warehouse_manager','production_manager')
     AND v_final_branch IS NULL THEN
    RAISE EXCEPTION 'branch_required_for_operational_role' USING ERRCODE = 'P0001';
  END IF;

  IF v_final_branch IS NOT NULL THEN
    SELECT branch_kind INTO v_branch_kind
    FROM public.branches
    WHERE id = v_final_branch AND tenant_id = v_actor_tenant;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'branch_not_found_in_tenant' USING ERRCODE = 'P0002';
    END IF;

    IF v_final_role IN ('cashier','waiter','chef','branch_manager')
       AND v_branch_kind <> 'branch' THEN
      RAISE EXCEPTION 'operational roles must be assigned to branch site' USING ERRCODE = 'P0001';
    END IF;
    IF v_final_role = 'warehouse_manager' AND v_branch_kind <> 'central_warehouse' THEN
      RAISE EXCEPTION 'warehouse_manager must be assigned to central_warehouse branch' USING ERRCODE = 'P0001';
    END IF;
    IF v_final_role = 'production_manager' AND v_branch_kind <> 'central_kitchen' THEN
      RAISE EXCEPTION 'production_manager must be assigned to central_kitchen branch' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF v_actor_role_text = 'owner' THEN
    NULL;
  ELSIF v_actor_role_text = 'super_manager' THEN
    IF v_target_role = 'owner' OR v_final_role = 'owner' THEN
      RAISE EXCEPTION 'super_manager cannot modify owner';
    END IF;
  ELSIF v_actor_role_text = 'area_manager' THEN
    IF v_target_role IN ('owner','super_manager','area_manager') THEN
      RAISE EXCEPTION 'area_manager cannot modify owner/super_manager/peer area_manager';
    END IF;
    IF v_final_role IN ('owner','super_manager','area_manager') THEN
      RAISE EXCEPTION 'area_manager cannot set role above branch_manager';
    END IF;
    IF v_target.branch_id IS NOT NULL THEN
      PERFORM 1 FROM public.area_branches
      WHERE area_id = v_actor_area AND branch_id = v_target.branch_id AND tenant_id = v_actor_tenant;
      IF NOT FOUND THEN RAISE EXCEPTION 'area_manager: target not in your area branches'; END IF;
    END IF;
    IF v_final_branch IS NOT NULL THEN
      PERFORM 1 FROM public.area_branches
      WHERE area_id = v_actor_area AND branch_id = v_final_branch AND tenant_id = v_actor_tenant;
      IF NOT FOUND THEN RAISE EXCEPTION 'area_manager: target branch not in your area'; END IF;
    END IF;
  ELSIF v_actor_role_text = 'branch_manager' THEN
    IF v_target.branch_id IS DISTINCT FROM v_actor_branch THEN
      RAISE EXCEPTION 'branch_manager: target not in your branch';
    END IF;
    IF v_target_role = 'branch_manager' THEN
      RAISE EXCEPTION 'branch_manager cannot modify peer branch_manager';
    END IF;
    IF v_final_role NOT IN ('cashier','waiter','chef') THEN
      RAISE EXCEPTION 'branch_manager can only assign cashier/waiter/chef';
    END IF;
    IF v_final_branch IS DISTINCT FROM v_actor_branch THEN
      RAISE EXCEPTION 'branch_manager cannot reassign to other branch';
    END IF;
  ELSE
    RAISE EXCEPTION 'insufficient privileges for profile management';
  END IF;

  v_final_position := public._auth_v2_position_id_from_role(v_final_role, v_actor_tenant);

  IF v_final_position IS NULL THEN
    RAISE EXCEPTION
      'admin_update_profile: position_not_resolved for role=% tenant=% - verify positions seeded',
      v_final_role, v_actor_tenant
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.profiles SET
    full_name   = COALESCE(p_full_name, full_name),
    phone       = COALESCE(p_phone,     phone),
    position_id = v_final_position,
    branch_id   = v_final_branch,
    is_active   = COALESCE(p_is_active, is_active),
    updated_at  = now()
  WHERE id = p_target_id AND tenant_id = v_actor_tenant;

  IF p_role IS NOT NULL AND p_role <> v_target_role THEN
    UPDATE auth.users
    SET raw_app_meta_data = raw_app_meta_data || jsonb_build_object('user_role', v_final_role, 'role', v_final_role)
    WHERE id = p_target_id;
  END IF;
  IF p_branch_id IS NOT NULL AND p_branch_id IS DISTINCT FROM v_target.branch_id THEN
    UPDATE auth.users
    SET raw_app_meta_data = raw_app_meta_data || jsonb_build_object('branch_id', v_final_branch)
    WHERE id = p_target_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."admin_update_profile"("p_target_id" "uuid", "p_full_name" "text", "p_phone" "text", "p_role" "text", "p_branch_id" bigint, "p_is_active" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_update_profile"("p_target_id" "uuid", "p_full_name" "text", "p_phone" "text", "p_role" "text", "p_branch_id" bigint, "p_is_active" boolean) IS 'Staff profile update RPC. SECURITY DEFINER with staff:manage plus staff:assign_position gate before role hierarchy checks.';



CREATE OR REPLACE FUNCTION "public"."aggregate_daily_b2c_invoice"("p_branch_id" bigint, "p_summary_date" "date", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tenant_id   BIGINT;
  v_invoice_id  BIGINT;
  v_order_count INT;
  v_subtotal    NUMERIC(15,2);
  v_vat_amount  NUMERIC(15,2);
  v_total       NUMERIC(15,2);
  v_pred_rate   NUMERIC(5,2);
  v_eligible    BIGINT[];
  v_breakdown   JSONB;
  v_line_items  JSONB;
  v_is_service  BOOLEAN;
  v_actor       UUID;
BEGIN
  v_is_service := (auth.role() = 'service_role');
  v_actor := COALESCE(p_actor, auth.uid());

  -- 1. Tenant guard
  SELECT tenant_id INTO v_tenant_id FROM public.branches WHERE id = p_branch_id;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- 2. Permission gate (skip for service_role)
  IF NOT v_is_service THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
    END IF;
    IF v_tenant_id <> public.auth_tenant_id() THEN
      RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
    END IF;
    IF NOT public.has_permission_any('settings:tenant') THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- 3. Per-(branch, date) advisory xact lock.
  PERFORM pg_advisory_xact_lock(
    hashtext('hddt-b2c:' || p_branch_id::text || ':' || p_summary_date::text)::bigint
  );

  -- 4. Idempotency short-circuit
  SELECT id INTO v_invoice_id
  FROM public.tax_invoices
  WHERE branch_id = p_branch_id
    AND summary_date = p_summary_date
    AND invoice_kind = 'daily_summary'
    AND status NOT IN ('cancelled', 'replaced');
  IF FOUND THEN
    RETURN jsonb_build_object(
      'skipped', true,
      'reason', 'already_exists',
      'tax_invoice_id', v_invoice_id
    );
  END IF;

  -- 5. Eligible orders (B2C bucket). Bucket source = payments.paid_at
  -- in Asia/Ho_Chi_Minh, matching revenue reporting.
  SELECT array_agg(DISTINCT o.id ORDER BY o.id)
  INTO v_eligible
  FROM public.orders o
  JOIN public.payments p ON p.order_id = o.id
  WHERE o.tenant_id = v_tenant_id
    AND o.branch_id = p_branch_id
    AND o.payment_status = 'paid'
    AND o.status NOT IN ('cancelled', 'refunded')
    AND p.status = 'completed'
    AND p.paid_at IS NOT NULL
    AND (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = p_summary_date
    AND NOT EXISTS (
      SELECT 1 FROM public.tax_invoices ti
       WHERE ti.order_id = o.id
         AND ti.status IN ('draft', 'signing', 'submitted', 'issued')
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.tax_invoice_orders tio
      JOIN public.tax_invoices ti2 ON ti2.id = tio.tax_invoice_id
      WHERE tio.order_id = o.id
        AND ti2.status NOT IN ('cancelled', 'replaced')
    );

  IF v_eligible IS NULL OR array_length(v_eligible, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'skipped', true,
      'reason', 'no_eligible_orders',
      'order_count', 0
    );
  END IF;

  v_order_count := array_length(v_eligible, 1);

  -- 6. Compute per-rate VAT breakdown via shared SQL helper.
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'vat_rate', vat_rate,
      'line_gross', line_gross,
      'line_subtotal', line_subtotal,
      'line_vat', line_vat
    ) ORDER BY vat_rate), '[]'::jsonb),
    COALESCE(SUM(line_subtotal), 0),
    COALESCE(SUM(line_vat), 0)
  INTO v_breakdown, v_subtotal, v_vat_amount
  FROM public._compute_vat_breakdown(v_eligible);

  v_total := v_subtotal + v_vat_amount;

  SELECT vat_rate INTO v_pred_rate
  FROM public._compute_vat_breakdown(v_eligible)
  ORDER BY line_gross DESC
  LIMIT 1;

  SELECT jsonb_agg(jsonb_build_object(
    'name', CASE
      WHEN vat_rate = 8  THEN 'Đồ ăn (8%)'
      WHEN vat_rate = 10 THEN 'Đồ uống có cồn (10%)'
      WHEN vat_rate = 5  THEN 'Hàng hoá khác (5%)'
      ELSE 'Hàng hoá VAT ' || vat_rate || '%'
    END,
    'unit', 'Phần',
    'quantity', 1,
    'unit_price', line_subtotal,
    'amount', line_subtotal,
    'vat_rate', vat_rate,
    'vat_amount', line_vat
  ) ORDER BY vat_rate)
  INTO v_line_items
  FROM public._compute_vat_breakdown(v_eligible);

  -- 7. INSERT tax_invoices as Viettel S-invoice draft.
  INSERT INTO public.tax_invoices (
    tenant_id, branch_id, order_id, status,
    invoice_kind, summary_date, summary_orders_count,
    buyer_name, buyer_tax_code, buyer_address,
    subtotal, vat_rate, vat_amount, total_amount,
    provider, provider_ref, provider_data,
    created_by
  ) VALUES (
    v_tenant_id, p_branch_id, NULL, 'draft',
    'daily_summary', p_summary_date, v_order_count,
    'Khách hàng không lấy hóa đơn', NULL, NULL,
    v_subtotal, v_pred_rate, v_vat_amount, v_total,
    'viettel', NULL,
    jsonb_build_object('vat_breakdown', v_breakdown),
    v_actor
  )
  RETURNING id INTO v_invoice_id;

  -- 8. INSERT junction rows.
  INSERT INTO public.tax_invoice_orders
    (tax_invoice_id, order_id, tenant_id, branch_id, vat_rate, line_subtotal, line_vat_amount)
  SELECT
    v_invoice_id,
    per_order.order_id,
    v_tenant_id,
    p_branch_id,
    per_order.pred_rate,
    per_order.order_subtotal,
    per_order.order_vat
  FROM (
    SELECT
      o.id AS order_id,
      SUM(
        (oi.subtotal * (o.total_amount / NULLIF(items_sum.s, 0)))
        / (1 + oi.vat_rate / 100)
      )::numeric(15,2) AS order_subtotal,
      SUM(
        (oi.subtotal * (o.total_amount / NULLIF(items_sum.s, 0)))
        - (oi.subtotal * (o.total_amount / NULLIF(items_sum.s, 0)))
          / (1 + oi.vat_rate / 100)
      )::numeric(15,2) AS order_vat,
      (
        SELECT oi3.vat_rate
        FROM public.order_items oi3
        WHERE oi3.order_id = o.id
          AND oi3.status <> 'cancelled'
        GROUP BY oi3.vat_rate
        ORDER BY SUM(oi3.subtotal) DESC
        LIMIT 1
      ) AS pred_rate
    FROM public.orders o
    JOIN public.order_items oi ON oi.order_id = o.id
    JOIN LATERAL (
      SELECT COALESCE(SUM(subtotal), 0) AS s
      FROM public.order_items
      WHERE order_id = o.id AND status <> 'cancelled'
    ) items_sum ON true
    WHERE o.id = ANY(v_eligible)
      AND oi.status <> 'cancelled'
      AND items_sum.s > 0
    GROUP BY o.id, o.total_amount, items_sum.s
  ) per_order;

  -- 9. Return aggregation result for Node runtime to call Sinvoice.
  RETURN jsonb_build_object(
    'tax_invoice_id', v_invoice_id,
    'order_count', v_order_count,
    'subtotal', v_subtotal,
    'vat_amount', v_vat_amount,
    'total_amount', v_total,
    'header_vat_rate', v_pred_rate,
    'vat_breakdown', v_breakdown,
    'order_ids', v_eligible,
    'line_items_for_provider', COALESCE(v_line_items, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."aggregate_daily_b2c_invoice"("p_branch_id" bigint, "p_summary_date" "date", "p_actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."aggregate_daily_b2c_invoice"("p_branch_id" bigint, "p_summary_date" "date", "p_actor" "uuid") IS 'Daily B2C summary HĐ aggregation. Creates draft tax_invoices row with provider=viettel and returns line_items_for_provider for the Node Sinvoice caller.';



CREATE OR REPLACE FUNCTION "public"."amend_grn_line"("p_grn_id" bigint, "p_line_id" bigint, "p_received_quantity" numeric, "p_unit_cost" numeric, "p_reason" "text", "p_rejected_quantity" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             UUID   := auth.uid();
  v_tenant          BIGINT := public.auth_tenant_id();
  v_grn             RECORD;
  v_line            RECORD;
  v_old_qty         NUMERIC(15,3);
  v_old_rej         NUMERIC(15,3);
  v_old_cost        NUMERIC(15,2);
  v_old_net         NUMERIC(15,3);
  v_new_qty         NUMERIC(15,3) := p_received_quantity;
  v_new_rej         NUMERIC(15,3);
  v_new_cost        NUMERIC(15,2) := p_unit_cost;
  v_new_net         NUMERIC(15,3);
  v_delta_qty       NUMERIC(15,3);
  v_delta_value     NUMERIC(15,2);
  v_current_qty     NUMERIC(15,3);
  v_active_returns  INT;
  v_paid_invoices   INT;
  v_location_id     BIGINT;
  v_invoice_id      BIGINT;
  v_po_status       TEXT;
  v_all_fulfilled   BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'reason_required_min_5_chars' USING ERRCODE = '22023';
  END IF;

  IF p_received_quantity IS NULL OR p_received_quantity < 0
     OR p_unit_cost IS NULL OR p_unit_cost < 0 THEN
    RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
  END IF;

  SELECT g.* INTO v_grn
  FROM public.goods_received_notes g
  WHERE g.id = p_grn_id AND g.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_grn.branch_id, 'procurement:grn_amend') THEN
    RAISE EXCEPTION 'forbidden_owner_only' USING ERRCODE = '42501';
  END IF;

  IF v_grn.status <> 'confirmed' THEN
    RAISE EXCEPTION 'grn_not_confirmed_use_upsert' USING ERRCODE = '22023';
  END IF;

  SELECT gi.* INTO v_line
  FROM public.grn_items gi
  WHERE gi.id = p_line_id
    AND gi.grn_id = p_grn_id
    AND gi.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_line_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_old_qty := v_line.received_quantity;
  v_old_rej := COALESCE(v_line.rejected_quantity, 0);
  v_old_cost := v_line.unit_cost;
  v_old_net := v_old_qty - v_old_rej;

  v_new_rej := COALESCE(p_rejected_quantity, v_old_rej);

  IF v_new_rej < 0 OR v_new_rej > v_new_qty THEN
    RAISE EXCEPTION 'rejected_exceeds_received' USING ERRCODE = '22023';
  END IF;

  v_new_net := v_new_qty - v_new_rej;

  SELECT COUNT(*) INTO v_active_returns
  FROM public.supplier_return_items sri
  JOIN public.supplier_returns sr ON sr.id = sri.return_id
  WHERE sri.tenant_id = v_tenant
    AND sri.grn_item_id = p_line_id
    AND sr.status NOT IN ('cancelled');

  IF v_active_returns > 0 THEN
    RAISE EXCEPTION 'has_active_supplier_return' USING ERRCODE = '23514';
  END IF;

  SELECT COUNT(*) INTO v_paid_invoices
  FROM public.supplier_invoices si
  WHERE si.tenant_id = v_tenant
    AND si.grn_id = p_grn_id
    AND COALESCE(si.payment_status, 'unpaid') <> 'unpaid';

  IF v_paid_invoices > 0 THEN
    RAISE EXCEPTION 'has_paid_invoice' USING ERRCODE = '23514';
  END IF;

  v_delta_qty := v_new_net - v_old_net;
  v_delta_value := (v_new_net * v_new_cost) - (v_old_net * v_old_cost);

  SELECT current_quantity INTO v_current_qty
  FROM public.stock_levels
  WHERE tenant_id = v_tenant
    AND branch_id = v_grn.branch_id
    AND ingredient_id = v_line.ingredient_id;

  v_current_qty := COALESCE(v_current_qty, 0);

  IF v_current_qty + v_delta_qty < 0 THEN
    RAISE EXCEPTION 'negative_stock' USING ERRCODE = '23514';
  END IF;

  SELECT il.id INTO v_location_id
  FROM public.inventory_locations il
  WHERE il.branch_id = v_grn.branch_id
    AND il.tenant_id = v_tenant
    AND il.is_default_receive = TRUE
    AND il.is_active = TRUE
  LIMIT 1;

  IF v_delta_qty <> 0 THEN
    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, quantity_change,
      reason, created_by, grn_id, unit_cost, location_id
    ) VALUES (
      v_tenant, v_grn.branch_id, v_line.ingredient_id, 'grn_amend',
      v_delta_qty,
      'GRN ' || v_grn.grn_number || ' amend (line ' || p_line_id || '): '
        || v_old_qty || '/' || v_old_rej || ' -> ' || v_new_qty || '/' || v_new_rej
        || ' @ ' || v_old_cost || ' -> ' || v_new_cost
        || ' - ' || trim(p_reason),
      v_uid, p_grn_id, v_new_cost, v_location_id
    );
  END IF;

  UPDATE public.grn_items
  SET received_quantity = v_new_qty,
      rejected_quantity = v_new_rej,
      unit_cost = v_new_cost,
      total_cost = ROUND(v_new_qty * v_new_cost, 2)
  WHERE id = p_line_id AND tenant_id = v_tenant;

  IF v_grn.po_id IS NOT NULL THEN
    PERFORM 1 FROM public.purchase_orders
    WHERE id = v_grn.po_id AND tenant_id = v_tenant
    FOR UPDATE;

    WITH ordered AS (
      SELECT poi.ingredient_id, SUM(poi.quantity)::NUMERIC(15,3) AS qty
      FROM public.purchase_order_items poi
      WHERE poi.po_id = v_grn.po_id AND poi.tenant_id = v_tenant
      GROUP BY poi.ingredient_id
    ),
    received AS (
      SELECT gi.ingredient_id,
             SUM(gi.received_quantity - COALESCE(gi.rejected_quantity, 0))::NUMERIC(15,3) AS qty
      FROM public.grn_items gi
      JOIN public.goods_received_notes g
        ON g.id = gi.grn_id AND g.status = 'confirmed'
      WHERE g.po_id = v_grn.po_id AND gi.tenant_id = v_tenant
      GROUP BY gi.ingredient_id
    )
    SELECT bool_and(COALESCE(r.qty, 0) >= o.qty * 0.95)
    INTO v_all_fulfilled
    FROM ordered o
    LEFT JOIN received r USING (ingredient_id)
    WHERE o.qty > 0;

    UPDATE public.purchase_orders po
    SET status = CASE
          WHEN COALESCE(v_all_fulfilled, TRUE) THEN 'received'
          ELSE 'partially_received'
        END,
        updated_at = now()
    WHERE po.id = v_grn.po_id
      AND po.tenant_id = v_tenant
      AND po.status IN ('sent', 'partially_received', 'received')
    RETURNING po.status INTO v_po_status;
  END IF;

  FOR v_invoice_id IN
    SELECT id FROM public.supplier_invoices
    WHERE tenant_id = v_tenant AND grn_id = p_grn_id
  LOOP
    PERFORM public.recompute_supplier_invoice_matching(v_invoice_id);
  END LOOP;

  RETURN jsonb_build_object(
    'grn_id',      p_grn_id,
    'line_id',     p_line_id,
    'old_qty',     v_old_qty,
    'old_rejected', v_old_rej,
    'new_qty',     v_new_qty,
    'new_rejected', v_new_rej,
    'old_cost',    v_old_cost,
    'new_cost',    v_new_cost,
    'delta_qty',   v_delta_qty,
    'delta_value', v_delta_value,
    'po_id',       v_grn.po_id,
    'po_status',   v_po_status
  );
END;
$$;


ALTER FUNCTION "public"."amend_grn_line"("p_grn_id" bigint, "p_line_id" bigint, "p_received_quantity" numeric, "p_unit_cost" numeric, "p_reason" "text", "p_rejected_quantity" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."amend_grn_line"("p_grn_id" bigint, "p_line_id" bigint, "p_received_quantity" numeric, "p_unit_cost" numeric, "p_reason" "text", "p_rejected_quantity" numeric) IS 'Owner-only post-confirm GRN line amendment. Delta dùng NET (received - rejected). Compensating stock_movement (grn_amend) -> trigger trg_update_stock_on_movement upsert stock_levels.current_quantity. PO fulfillment dùng SUM(received - rejected). Permission: procurement:grn_amend.';



CREATE OR REPLACE FUNCTION "public"."append_order_items"("p_order_id" bigint, "p_items" "jsonb", "p_idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_prof_tenant     BIGINT;
  v_prof_branch     BIGINT;
  v_prof_role       TEXT;
  v_order           RECORD;
  v_item            JSONB;
  v_base_price      NUMERIC(15,2);
  v_variant_adj     NUMERIC(15,2);
  v_modifier_sum    NUMERIC(15,2);
  v_sides_sum       NUMERIC(15,2);
  v_enriched_sides  JSONB;
  v_unit_price      NUMERIC(15,2);
  v_item_subtotal   NUMERIC(15,2);
  v_menu_item_id    BIGINT;
  v_variant_id      BIGINT;
  v_quantity        INT;
  v_subtotal        NUMERIC(15,2);
  v_discount_amount NUMERIC(15,2);
  v_total_amount    NUMERIC(15,2);
  v_note_parts      TEXT[] := ARRAY[]::TEXT[];
  v_item_name       TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(po.legacy_role_code, 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  IF p_idempotency_key IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.order_items
      WHERE order_id = p_order_id
        AND request_key = p_idempotency_key
      LIMIT 1
    ) THEN
      SELECT o.subtotal, o.total_amount
      INTO v_subtotal, v_total_amount
      FROM public.orders o
      WHERE o.id = p_order_id;

      RETURN jsonb_build_object(
        'success',      TRUE,
        'order_id',     p_order_id,
        'added_count',  0,
        'subtotal',     COALESCE(v_subtotal, 0),
        'total_amount', COALESCE(v_total_amount, 0),
        'idempotent',   TRUE
      );
    END IF;
  END IF;

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status, o.service_charge,
         o.discount_type, o.discount_value
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner', 'super_manager', 'area_manager') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NOT NULL THEN
    IF v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
  END IF;

  IF v_order.status NOT IN ('new', 'confirmed', 'preparing', 'ready', 'served') THEN
    RAISE EXCEPTION 'order not appendable' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order not appendable' USING ERRCODE = '22023';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'p_items must be a non-empty JSON array' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) AS value
  LOOP
    v_menu_item_id := (v_item ->> 'menu_item_id')::BIGINT;
    v_variant_id := NULLIF(v_item ->> 'variant_id', '')::BIGINT;
    v_quantity := (v_item ->> 'quantity')::INT;

    IF v_quantity IS NULL OR v_quantity < 1 THEN
      RAISE EXCEPTION 'invalid quantity' USING ERRCODE = '22023';
    END IF;

    SELECT base_price INTO v_base_price
    FROM public.menu_items
    WHERE id = v_menu_item_id AND tenant_id = v_order.tenant_id AND is_active = TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Menu item % not found or inactive', v_menu_item_id USING ERRCODE = 'P0002';
    END IF;

    v_variant_adj := 0;
    IF v_variant_id IS NOT NULL THEN
      SELECT price_adjustment INTO v_variant_adj
      FROM public.menu_item_variants
      WHERE id = v_variant_id AND item_id = v_menu_item_id AND tenant_id = v_order.tenant_id AND is_active = TRUE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Variant % not found or inactive', v_variant_id USING ERRCODE = 'P0002';
      END IF;
    END IF;

    v_modifier_sum := public.pos_order_modifier_sum(
      v_order.tenant_id,
      v_menu_item_id,
      COALESCE(v_item -> 'modifiers', '[]'::JSONB)
    );

    SELECT sides_sum, enriched_sides
    INTO v_sides_sum, v_enriched_sides
    FROM public.pos_enrich_order_sides(
      v_order.tenant_id,
      v_menu_item_id,
      COALESCE(v_item -> 'sides', '[]'::JSONB)
    );

    v_unit_price := v_base_price + v_variant_adj + v_modifier_sum + COALESCE(v_sides_sum, 0);
    v_item_subtotal := v_unit_price * v_quantity;

    v_item_name := v_item ->> 'item_name';
    IF v_item_name IS NOT NULL AND length(trim(v_item_name)) > 0 THEN
      v_note_parts := array_append(v_note_parts, v_item_name);
    END IF;

    INSERT INTO public.order_items (
      tenant_id, order_id, menu_item_id, variant_id,
      item_name, variant_name, quantity, unit_price,
      modifiers, sides, subtotal, note, status, request_key
    )
    VALUES (
      v_order.tenant_id, p_order_id, v_menu_item_id, v_variant_id,
      COALESCE(v_item ->> 'item_name', 'Mon'),
      v_item ->> 'variant_name',
      v_quantity, v_unit_price,
      COALESCE(v_item -> 'modifiers', '[]'::JSONB),
      COALESCE(v_enriched_sides, '[]'::JSONB),
      v_item_subtotal, v_item ->> 'note', 'pending',
      p_idempotency_key
    );
  END LOOP;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal
  FROM public.order_items
  WHERE order_id = p_order_id AND status <> 'cancelled';

  v_discount_amount := public.compute_discount_amount(
    v_order.discount_type, v_order.discount_value, v_subtotal
  );

  v_total_amount := v_subtotal
                  + COALESCE(v_order.service_charge, 0)
                  - v_discount_amount;

  UPDATE public.orders o
  SET
    subtotal        = v_subtotal,
    tax_amount      = 0,
    discount_amount = v_discount_amount,
    total_amount    = v_total_amount,
    updated_at      = now()
  WHERE o.id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id,
    p_order_id,
    v_order.status,
    v_order.status,
    v_uid,
    'items_added: ' || COALESCE(array_to_string(v_note_parts, ', '), 'items')
  );

  PERFORM public.route_order_to_kds(p_order_id);

  RETURN jsonb_build_object(
    'success',      TRUE,
    'order_id',     p_order_id,
    'added_count',  jsonb_array_length(p_items),
    'subtotal',     v_subtotal,
    'total_amount', v_total_amount
  );
END;
$$;


ALTER FUNCTION "public"."append_order_items"("p_order_id" bigint, "p_items" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."append_order_items"("p_order_id" bigint, "p_items" "jsonb", "p_idempotency_key" "uuid") IS 'Atomic append of order_items to an existing appendable order. pg_advisory_xact_lock(order_id) serializes with other mutations. If p_idempotency_key matches a prior append on the same order, short-circuits returning current totals (no duplicate insert). Returns {success, order_id, added_count, subtotal, total_amount[, idempotent]}.';



CREATE OR REPLACE FUNCTION "public"."apply_credit_note_to_invoice"("p_credit_id" bigint, "p_invoice_id" bigint, "p_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid     UUID   := auth.uid();
  v_tenant  BIGINT := public.auth_tenant_id();
  v_credit  RECORD;
  v_invoice RECORD;
  v_remaining_credit  NUMERIC(15,2);
  v_remaining_invoice NUMERIC(15,2);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission(NULL, 'finance:ap_pay') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_credit
  FROM public.supplier_credit_notes
  WHERE id = p_credit_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'credit_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_credit.status NOT IN ('open') THEN
    RAISE EXCEPTION 'credit_not_open' USING ERRCODE = '22023';
  END IF;
  IF v_credit.kind <> 'credit_note' THEN
    RAISE EXCEPTION 'credit_kind_mismatch' USING ERRCODE = '22023',
      DETAIL = 'Only credit_note kind can be applied to invoices; cash_refund is closed at issuance.';
  END IF;

  SELECT * INTO v_invoice
  FROM public.supplier_invoices
  WHERE id = p_invoice_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- Same supplier guard
  IF v_invoice.supplier_id <> v_credit.supplier_id THEN
    RAISE EXCEPTION 'supplier_mismatch' USING ERRCODE = '22023';
  END IF;

  v_remaining_credit  := v_credit.amount - v_credit.applied_amount;
  v_remaining_invoice := v_invoice.total_amount
                       - COALESCE(v_invoice.paid_amount, 0)
                       - COALESCE(v_invoice.credit_applied_amount, 0);

  IF p_amount > v_remaining_credit THEN
    RAISE EXCEPTION 'amount_exceeds_credit' USING ERRCODE = '22023',
      DETAIL = format('credit_remaining=%s', v_remaining_credit);
  END IF;
  IF p_amount > v_remaining_invoice THEN
    RAISE EXCEPTION 'amount_exceeds_invoice' USING ERRCODE = '22023',
      DETAIL = format('invoice_remaining=%s', v_remaining_invoice);
  END IF;

  -- Apply
  UPDATE public.supplier_credit_notes
  SET applied_amount = applied_amount + p_amount,
      invoice_id = COALESCE(invoice_id, p_invoice_id),
      status = CASE
        WHEN applied_amount + p_amount >= amount THEN 'applied'
        ELSE 'open'
      END,
      applied_at = CASE
        WHEN applied_amount + p_amount >= amount THEN now()
        ELSE applied_at
      END
  WHERE id = p_credit_id;

  UPDATE public.supplier_invoices
  SET credit_applied_amount = COALESCE(credit_applied_amount, 0) + p_amount,
      updated_at = now()
  WHERE id = p_invoice_id;

  RETURN jsonb_build_object(
    'credit_id', p_credit_id,
    'invoice_id', p_invoice_id,
    'amount_applied', p_amount,
    'credit_remaining', v_remaining_credit - p_amount,
    'invoice_remaining', v_remaining_invoice - p_amount
  );
END;
$$;


ALTER FUNCTION "public"."apply_credit_note_to_invoice"("p_credit_id" bigint, "p_invoice_id" bigint, "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_order_discount"("p_order_id" bigint, "p_type" "text", "p_value" numeric, "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_prof_tenant     BIGINT;
  v_prof_branch     BIGINT;
  v_prof_role       TEXT;
  v_order           RECORD;
  v_clamped_value   NUMERIC(15,2);
  v_discount_amount NUMERIC(15,2);
  v_total_amount    NUMERIC(15,2);
  v_note_trim       TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(po.legacy_role_code, 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  -- Bất kỳ nhân viên POS nào (cashier/waiter/branch_manager+) đều áp được.
  -- Không gate theo % — owner đã chốt tại 4-agent debate (C1).
  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'super_manager', 'area_manager', 'branch_manager', 'cashier', 'waiter')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  -- Validate type / value / note BEFORE locking — fail fast without
  -- holding the advisory lock.
  IF p_type IS NULL OR p_type NOT IN ('pct', 'vnd') THEN
    RAISE EXCEPTION 'discount_invalid_type' USING ERRCODE = '22023';
  END IF;

  IF p_value IS NULL OR p_value < 0 THEN
    RAISE EXCEPTION 'discount_invalid_value' USING ERRCODE = '22023';
  END IF;

  v_note_trim := COALESCE(trim(p_note), '');
  IF length(v_note_trim) < 3 THEN
    RAISE EXCEPTION 'discount_note_required' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status,
         o.subtotal, o.service_charge
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  -- Branch scope (SECURITY DEFINER — RLS bypass; manual check required).
  IF v_prof_role IN ('owner', 'super_manager', 'area_manager') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  -- Block on terminal / paid orders. Discount = pre-payment cashier action;
  -- editing an already-completed order rewrites recorded revenue silently.
  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  -- Auto-clamp at the boundary (UI also clamps; this is defense-in-depth):
  -- pct beyond 100 -> 100, vnd beyond subtotal -> subtotal.
  IF p_type = 'pct' THEN
    v_clamped_value := LEAST(p_value, 100);
  ELSE
    v_clamped_value := LEAST(p_value, COALESCE(v_order.subtotal, 0));
  END IF;

  v_discount_amount := public.compute_discount_amount(
    p_type, v_clamped_value, v_order.subtotal
  );

  -- Edge: cashier types 0 — that's NOT an apply, it's a clear. Force the
  -- caller to use clear_order_discount instead (so audit history reads
  -- "discount_cleared" not "discount_applied: 0%").
  IF v_discount_amount = 0 THEN
    RAISE EXCEPTION 'discount_zero_amount' USING ERRCODE = '22023';
  END IF;

  v_total_amount := COALESCE(v_order.subtotal, 0)
                  + COALESCE(v_order.service_charge, 0)
                  - v_discount_amount;

  UPDATE public.orders
     SET discount_type   = p_type,
         discount_value  = v_clamped_value,
         discount_note   = v_note_trim,
         discount_amount = v_discount_amount,
         total_amount    = v_total_amount,
         updated_at      = now()
   WHERE id = p_order_id;

  -- Audit row in order_status_history. Re-stamps current status (no state
  -- transition) — the `note` column is the discount audit. Pattern matches
  -- append_order_items / void_order_item history entries.
  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_order.tenant_id, p_order_id, v_order.status, v_order.status, v_uid,
    'discount_applied: ' || p_type || ' ' || v_clamped_value::TEXT
      || ' (' || v_discount_amount::TEXT || 'đ) :: ' || v_note_trim
  );

  RETURN jsonb_build_object(
    'order_id',        p_order_id,
    'discount_type',   p_type,
    'discount_value',  v_clamped_value,
    'discount_amount', v_discount_amount,
    'total_amount',    v_total_amount
  );
END;
$$;


ALTER FUNCTION "public"."apply_order_discount"("p_order_id" bigint, "p_type" "text", "p_value" numeric, "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_order_discount"("p_order_id" bigint, "p_type" "text", "p_value" numeric, "p_note" "text") IS 'Set order-level discount (% or VND) with required note (>=3 chars). Auto-clamps pct to 100 and vnd to subtotal. Recomputes discount_amount + total_amount via compute_discount_amount helper. Blocks on paid/terminal orders. Inserts audit row to order_status_history.';



CREATE OR REPLACE FUNCTION "public"."apply_template_to_user"("p_target_user" "uuid", "p_branch_id" bigint, "p_template_id" bigint, "p_valid_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_valid_until" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_tenant_id     BIGINT;
  v_target_tenant BIGINT;
  v_template      RECORD;
  v_perm_key      TEXT;
  v_inserted      INTEGER := 0;
  v_rows          INTEGER;
  v_from          TIMESTAMPTZ := COALESCE(p_valid_from, now());
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'staff:assign_permission') THEN
    RAISE EXCEPTION 'forbidden: missing staff:assign_permission' USING ERRCODE = '42501';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.profiles WHERE id = auth.uid();
  SELECT tenant_id INTO v_target_tenant FROM public.profiles WHERE id = p_target_user;
  IF v_target_tenant IS NULL OR v_target_tenant <> v_tenant_id THEN
    RAISE EXCEPTION 'target_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  IF public._auth_v2_is_owner(p_target_user) THEN
    RAISE EXCEPTION 'cannot_manage_owner_permissions' USING ERRCODE = '42501';
  END IF;

  IF p_valid_until IS NOT NULL AND p_valid_until <= v_from THEN
    RAISE EXCEPTION 'invalid_validity_window' USING ERRCODE = '22023';
  END IF;

  SELECT id, tenant_id, permission_keys
  INTO v_template
  FROM public.role_templates
  WHERE id = p_template_id;

  IF v_template.id IS NULL OR v_template.tenant_id <> v_tenant_id THEN
    RAISE EXCEPTION 'template_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  FOREACH v_perm_key IN ARRAY v_template.permission_keys LOOP
    INSERT INTO public.staff_permissions (
      user_id, tenant_id, branch_id, permission_key, source_template, granted_by,
      valid_from, valid_until
    ) VALUES (
      p_target_user, v_tenant_id, p_branch_id, v_perm_key, v_template.id, auth.uid(),
      v_from, p_valid_until
    )
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows > 0 THEN
      INSERT INTO public.permission_audit_log (
        tenant_id, actor_user_id, target_user_id, branch_id,
        permission_key, action, source_template_id, metadata
      ) VALUES (
        v_tenant_id, auth.uid(), p_target_user, p_branch_id,
        v_perm_key, 'apply_template', v_template.id,
        jsonb_build_object(
          'template_id', v_template.id,
          'valid_from',  v_from,
          'valid_until', p_valid_until
        )
      );
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."apply_template_to_user"("p_target_user" "uuid", "p_branch_id" bigint, "p_template_id" bigint, "p_valid_from" timestamp with time zone, "p_valid_until" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_shift_request"("p_request_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id    BIGINT := public.auth_tenant_id();
  v_user_id      UUID   := auth.uid();
  v_request      public.shift_requests%ROWTYPE;
  v_assignment_id BIGINT;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'approve_shift_request: missing auth context' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_request FROM public.shift_requests
  WHERE id = p_request_id AND tenant_id = v_tenant_id FOR UPDATE;
  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'approve_shift_request: request not found' USING ERRCODE = 'no_data_found';
  END IF;
  IF NOT public.has_permission(v_request.branch_id, 'hr:approve_shift_request') THEN
    RAISE EXCEPTION 'approve_shift_request: missing permission for this branch' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'approve_shift_request: request is %, not pending', v_request.status USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = v_request.employee_id AND e.profile_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'approve_shift_request: cannot approve own request' USING ERRCODE = 'insufficient_privilege';
  END IF;
  INSERT INTO public.shift_assignments
    (tenant_id, branch_id, employee_id, shift_id, date)
  VALUES
    (v_request.tenant_id, v_request.branch_id, v_request.employee_id,
     v_request.shift_id, v_request.date)
  ON CONFLICT (employee_id, date, tenant_id) DO NOTHING
  RETURNING id INTO v_assignment_id;
  IF v_assignment_id IS NULL THEN
    SELECT id INTO v_assignment_id FROM public.shift_assignments
    WHERE employee_id = v_request.employee_id AND date = v_request.date AND tenant_id = v_request.tenant_id;
  END IF;
  UPDATE public.shift_requests
  SET status = 'approved', reviewed_by = v_user_id, reviewed_at = now(), assignment_id = v_assignment_id
  WHERE id = p_request_id;
  PERFORM public.log_audit(
    'approve'::TEXT, 'shift_request'::TEXT, p_request_id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'approved', 'assignment_id', v_assignment_id)
  );
  RETURN v_assignment_id;
END;
$$;


ALTER FUNCTION "public"."approve_shift_request"("p_request_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_waste"("p_issue_id" bigint, "p_decision" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_issue RECORD;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_decision NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'decision must be approved or rejected' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_issue FROM public.stock_issues WHERE id = p_issue_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'issue not found' USING ERRCODE = 'P0002'; END IF;
  IF v_issue.issue_type <> 'writeoff' THEN RAISE EXCEPTION 'issue is not a writeoff' USING ERRCODE = '22023'; END IF;
  IF NOT public.has_permission(v_issue.branch_id, 'inventory:waste_approve') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF v_issue.approval_status <> 'pending' THEN
    RAISE EXCEPTION 'issue is not pending approval (status=%)', v_issue.approval_status USING ERRCODE = '22023';
  END IF;
  -- 4-eye principle: creator cannot approve own waste (unless has admin break-glass)
  IF v_issue.created_by = v_uid AND NOT public.has_permission(NULL, 'accounting:period_reopen') THEN
    RAISE EXCEPTION 'self-approval forbidden: approver cannot be the creator' USING ERRCODE = '42501';
  END IF;
  UPDATE public.stock_issues SET approval_status = p_decision, approved_by = v_uid, approved_at = now(),
    status = CASE WHEN p_decision = 'approved' THEN 'confirmed' ELSE 'cancelled' END,
    notes = COALESCE(notes, '') || CASE WHEN p_note IS NOT NULL
      THEN E'\n[' || p_decision || ' by ' || v_uid::TEXT || '] ' || p_note ELSE '' END
  WHERE id = p_issue_id;
END; $$;


ALTER FUNCTION "public"."approve_waste"("p_issue_id" bigint, "p_decision" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_auditor"("p_session_id" bigint, "p_auditor_id" "uuid", "p_auditor_branch_id" bigint DEFAULT NULL::bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_ss RECORD;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_ss FROM public.stocktake_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_ss.branch_id, 'inventory:stocktake_recount') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  UPDATE public.stocktake_sessions SET auditor_id = p_auditor_id, auditor_branch_id = p_auditor_branch_id, is_unaudited = false
    WHERE id = p_session_id;
END; $$;


ALTER FUNCTION "public"."assign_auditor"("p_session_id" bigint, "p_auditor_id" "uuid", "p_auditor_branch_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_print_document_to_payload"("p_tenant_id" bigint, "p_branch_id" bigint, "p_kind" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_template RECORD;
  v_template_id BIGINT := 0;
  v_template_version INT := 1;
  v_paper_width_mm INT := 80;
  v_font_profile TEXT := 'thermal_vietnamese';
  v_content JSONB := public.print_template_default_content(p_kind);
  v_document JSONB;
BEGIN
  IF p_payload ? 'document' THEN RETURN p_payload; END IF;

  SELECT * INTO v_template FROM public.resolve_print_template_version(p_tenant_id, p_branch_id, p_kind);

  IF FOUND THEN
    v_template_id := v_template.template_id;
    v_template_version := v_template.template_version;
    v_paper_width_mm := v_template.paper_width_mm;
    v_font_profile := v_template.font_profile;
    v_content := v_template.content;
  END IF;

  v_document := public.materialize_print_document(
    p_kind, p_payload, v_template_id, v_template_version,
    v_paper_width_mm, v_font_profile, v_content);

  RETURN p_payload || jsonb_build_object(
    'template_version', v_template_id::TEXT || ':' || v_template_version::TEXT,
    'document', v_document);
END;
$$;


ALTER FUNCTION "public"."attach_print_document_to_payload"("p_tenant_id" bigint, "p_branch_id" bigint, "p_kind" "text", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attach_print_document_to_payload"("p_tenant_id" bigint, "p_branch_id" bigint, "p_kind" "text", "p_payload" "jsonb") IS 'Resolve active print template and materialize a schema_version=1 document AST into the print payload.';



