CREATE OR REPLACE FUNCTION "public"."auth_role"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- Now derives from positions.legacy_role_code instead of JWT user_role claim.
  -- Kept as a function (not dropped) because admin_update_profile still calls it,
  -- and dropping would cascade to all callers. Safe: returns same values.
  SELECT COALESCE(po.legacy_role_code, 'unassigned')
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = auth.uid()
  LIMIT 1;
$$;


ALTER FUNCTION "public"."auth_role"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auth_role"() IS 'Shadow helper: returns legacy_role_code for the caller. Kept to preserve admin_update_profile/handle_new_user internals after profiles.role drop. JWT user_role claim is now derived from positions by the hook.';



