CREATE OR REPLACE FUNCTION "public"."auto_close_periods"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_today DATE; v_day INT; v_prior DATE; v_year INT; v_month INT; v_count INT := 0; v_row RECORD;
BEGIN
  v_today := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::DATE;
  v_day := EXTRACT(DAY FROM v_today)::INT;
  v_prior := (date_trunc('month', v_today) - INTERVAL '1 month')::DATE;
  v_year := EXTRACT(YEAR FROM v_prior)::INT;
  v_month := EXTRACT(MONTH FROM v_prior)::INT;
  IF v_day < 5 THEN RETURN 0; END IF;
  FOR v_row IN SELECT id FROM public.tenants LOOP
    INSERT INTO public.accounting_periods (tenant_id, year, month, soft_closed_at)
    VALUES (v_row.id, v_year, v_month, now())
    ON CONFLICT (tenant_id, year, month) DO UPDATE
      SET soft_closed_at = COALESCE(public.accounting_periods.soft_closed_at, EXCLUDED.soft_closed_at);
    v_count := v_count + 1;
  END LOOP;
  IF v_day >= 15 THEN
    FOR v_row IN SELECT id FROM public.tenants LOOP
      UPDATE public.accounting_periods SET hard_closed_at = COALESCE(hard_closed_at, now())
       WHERE tenant_id = v_row.id AND year = v_year AND month = v_month;
    END LOOP;
  END IF;
  RETURN v_count;
END; $$;


ALTER FUNCTION "public"."auto_close_periods"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auto_close_periods"() IS 'Daily automation — day 5+ soft close, day 15+ hard close. Idempotent.';



CREATE OR REPLACE FUNCTION "public"."auto_enqueue_kitchen_print_from_ticket"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.kitchen_send_batch_id IS NULL THEN
    RETURN NULL;
  END IF;

  BEGIN
    PERFORM private.enqueue_kitchen_print_internal(NEW.order_id, NULL, FALSE);
  EXCEPTION
    WHEN OTHERS THEN
      RAISE LOG 'auto_enqueue_kitchen_print_from_ticket skipped order_id=%, ticket_id=%, sqlstate=%, error=%',
        NEW.order_id,
        NEW.id,
        SQLSTATE,
        SQLERRM;
      RETURN NULL;
  END;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."auto_enqueue_kitchen_print_from_ticket"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_post_journal"("p_tenant_id" bigint, "p_branch_id" bigint, "p_reference_type" "text", "p_reference_id" bigint, "p_description" "text", "p_lines" "jsonb", "p_entry_date" timestamp with time zone DEFAULT "now"(), "p_posted_by" "uuid" DEFAULT NULL::"uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_entry_id      BIGINT;
  v_entry_number  TEXT;
  v_line          JSONB;
  v_rule          RECORD;
  v_dr_account_id BIGINT;
  v_cr_account_id BIGINT;
  v_amount        NUMERIC(15,2);
  v_line_desc     TEXT;
  v_lines_count   INT := 0;
  v_total_dr      NUMERIC(15,2) := 0;
  v_total_cr      NUMERIC(15,2) := 0;
  v_actor         UUID;
  v_period_month  INT;
  v_period_year   INT;
  v_period_status TEXT;
BEGIN
  -- ═══ TENANT VALIDATION ═══
  -- Prevent cross-tenant access: caller-supplied p_tenant_id must match auth context.
  -- Only skip check when called from service-role context (auth.uid() IS NULL).
  IF auth.uid() IS NOT NULL AND p_tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  -- Resolve actor
  v_actor := COALESCE(p_posted_by, auth.uid());

  -- ═══ FISCAL PERIOD CHECK (with row lock to prevent TOCTOU race) ═══
  v_period_month := EXTRACT(MONTH FROM p_entry_date)::INT;
  v_period_year  := EXTRACT(YEAR FROM p_entry_date)::INT;

  SELECT fp.status INTO v_period_status
  FROM public.fiscal_periods fp
  WHERE fp.tenant_id = p_tenant_id
    AND fp.period_month = v_period_month
    AND fp.period_year = v_period_year
  FOR SHARE;

  IF FOUND THEN
    IF v_period_status = 'closed' THEN
      RAISE EXCEPTION 'fiscal_period_closed: %-% is closed, cannot post journal',
        v_period_year, lpad(v_period_month::text, 2, '0')
        USING ERRCODE = '23514';
    END IF;
    -- 'open' or 'closing' → allow (closing permits adjusting entries)
  ELSE
    -- Auto-create open period if it doesn't exist
    INSERT INTO public.fiscal_periods (tenant_id, period_month, period_year, status)
    VALUES (p_tenant_id, v_period_month, v_period_year, 'open')
    ON CONFLICT (period_month, period_year, tenant_id) DO NOTHING;
  END IF;

  -- Generate auto entry number: AUTO-YYYYMMDD-NNNNNN
  v_entry_number := 'AUTO-' || to_char(p_entry_date, 'YYYYMMDD') || '-'
                    || lpad(nextval('public.auto_journal_seq')::TEXT, 6, '0');

  -- Create journal header (status = posted, skips draft)
  INSERT INTO public.journal_entries (
    tenant_id, branch_id, entry_number, entry_date, description,
    reference_type, reference_id, status,
    posted_by, posted_at, created_by
  ) VALUES (
    p_tenant_id, p_branch_id, v_entry_number, p_entry_date, p_description,
    p_reference_type, p_reference_id, 'posted',
    v_actor, now(), v_actor
  )
  RETURNING id INTO v_entry_id;

  -- Process each line from p_lines JSONB array
  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    -- Lookup posting rule
    SELECT pr.*
    INTO v_rule
    FROM public.posting_rules pr
    WHERE pr.tenant_id = p_tenant_id
      AND pr.rule_code = (v_line ->> 'rule_code')
      AND pr.is_active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'posting_rule_not_found: % for tenant %', (v_line ->> 'rule_code'), p_tenant_id
        USING ERRCODE = 'P0002';
    END IF;

    v_amount := (v_line ->> 'amount')::NUMERIC(15,2);
    v_line_desc := v_line ->> 'line_description';

    -- Skip zero-amount lines (legitimate: e.g. COGS=0 when no stock consumed)
    IF v_amount IS NULL OR v_amount <= 0 THEN
      CONTINUE;
    END IF;

    -- Resolve debit account_id
    SELECT id INTO v_dr_account_id
    FROM public.chart_of_accounts
    WHERE tenant_id = p_tenant_id AND account_code = v_rule.debit_account_code AND is_active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'gl_account_not_found: debit % for rule %', v_rule.debit_account_code, v_rule.rule_code
        USING ERRCODE = 'P0002';
    END IF;

    -- Resolve credit account_id
    SELECT id INTO v_cr_account_id
    FROM public.chart_of_accounts
    WHERE tenant_id = p_tenant_id AND account_code = v_rule.credit_account_code AND is_active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'gl_account_not_found: credit % for rule %', v_rule.credit_account_code, v_rule.rule_code
        USING ERRCODE = 'P0002';
    END IF;

    -- Insert debit line
    INSERT INTO public.journal_entry_lines (
      tenant_id, journal_entry_id, account_id, debit_amount, credit_amount, description
    ) VALUES (
      p_tenant_id, v_entry_id, v_dr_account_id, v_amount, 0,
      COALESCE(v_line_desc, v_rule.description)
    );

    -- Insert credit line
    INSERT INTO public.journal_entry_lines (
      tenant_id, journal_entry_id, account_id, debit_amount, credit_amount, description
    ) VALUES (
      p_tenant_id, v_entry_id, v_cr_account_id, 0, v_amount,
      COALESCE(v_line_desc, v_rule.description)
    );

    v_total_dr := v_total_dr + v_amount;
    v_total_cr := v_total_cr + v_amount;
    v_lines_count := v_lines_count + 1;
  END LOOP;

  -- If no valid lines, delete empty header and return NULL
  IF v_lines_count = 0 THEN
    DELETE FROM public.journal_entries WHERE id = v_entry_id;
    RETURN NULL;
  END IF;

  -- Safety: validate balance
  IF NOT public.validate_journal_balance(v_entry_id) THEN
    RAISE EXCEPTION 'auto_post_journal: balance validation failed for entry %', v_entry_id
      USING ERRCODE = '23514';
  END IF;

  RETURN v_entry_id;
END;
$$;


ALTER FUNCTION "public"."auto_post_journal"("p_tenant_id" bigint, "p_branch_id" bigint, "p_reference_type" "text", "p_reference_id" bigint, "p_description" "text", "p_lines" "jsonb", "p_entry_date" timestamp with time zone, "p_posted_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_mark_feedback_suspect"("p_feedback_ids" bigint[], "p_is_suspect" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT;
  v_updated   INT;
BEGIN
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::BIGINT;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'missing tenant context' USING ERRCODE = 'P0001';
  END IF;

  IF NOT public.has_permission_any('feedback:moderate') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = 'P0001';
  END IF;

  UPDATE feedbacks
  SET    is_suspect = p_is_suspect
  WHERE  id        = ANY(p_feedback_ids)
    AND  tenant_id = v_tenant_id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."bulk_mark_feedback_suspect"("p_feedback_ids" bigint[], "p_is_suspect" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bump_kds_ticket"("p_ticket_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ticket    RECORD;
  v_new_status TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('kds:mark_ready') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT id, tenant_id, branch_id, station_id, order_id, status
  INTO v_ticket
  FROM public.kds_tickets
  WHERE id = p_ticket_id
    AND tenant_id = public.auth_tenant_id()
    AND public.can_access_branch(branch_id)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_ticket.status = 'pending' THEN
    v_new_status := 'preparing';
  ELSIF v_ticket.status = 'preparing' THEN
    v_new_status := 'ready';
  ELSE
    RAISE EXCEPTION 'Ticket cannot be bumped from status %', v_ticket.status
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.kds_tickets
  SET status    = v_new_status,
      bumped_at = now(),
      bumped_by = auth.uid()
  WHERE id = p_ticket_id;

  IF v_new_status = 'ready' THEN
    PERFORM public.check_order_ready(v_ticket.order_id);
  END IF;

  RETURN v_new_status;
END;
$$;


ALTER FUNCTION "public"."bump_kds_ticket"("p_ticket_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_access_branch"("p_branch_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN public.auth_role() IN ('owner', 'super_manager', 'office') THEN true
    WHEN public.auth_role() = 'area_manager' THEN
      public.auth_area_id() IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.area_branches ab
        WHERE ab.tenant_id = public.auth_tenant_id()
          AND ab.area_id = public.auth_area_id()
          AND ab.branch_id = p_branch_id
      )
    ELSE p_branch_id = public.auth_branch_id()
  END;
$$;


ALTER FUNCTION "public"."can_access_branch"("p_branch_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_order"("p_order_id" bigint, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid              UUID;
  v_prof_tenant      BIGINT;
  v_prof_branch      BIGINT;
  v_prof_role        TEXT;
  v_order            RECORD;
  v_item_id          BIGINT;
  v_print_res        JSONB;
  v_tickets_enqueued INT := 0;
  v_tickets_skipped  INT := 0;
  v_skip_reasons     TEXT[] := ARRAY[]::TEXT[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(po.legacy_role_code, 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'waiter') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT id, tenant_id, branch_id, status, table_id, order_type,
         service_charge, discount_type, discount_value
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
  SET status = 'cancelled',
      cancel_reason = p_reason,
      updated_at = now()
  WHERE order_id = p_order_id AND status <> 'cancelled';

  UPDATE public.kds_tickets
  SET status = 'cancelled', updated_at = now()
  WHERE order_id = p_order_id AND tenant_id = v_order.tenant_id;

  UPDATE public.orders
  SET
    status          = 'cancelled',
    subtotal        = 0,
    discount_type   = NULL,
    discount_value  = NULL,
    discount_note   = NULL,
    discount_amount = 0,
    total_amount    = 0 + COALESCE(service_charge, 0),
    updated_at      = now()
  WHERE id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id, p_order_id, v_order.status, 'cancelled', v_uid, p_reason
  );

  FOR v_item_id IN
    SELECT id FROM public.order_items
    WHERE order_id = p_order_id
      AND sent_to_kitchen_at IS NOT NULL
    ORDER BY id
  LOOP
    BEGIN
      v_print_res := public.enqueue_cancel_ticket_print(v_item_id, p_reason);
      IF (v_print_res ? 'skipped') AND (v_print_res->>'skipped')::boolean THEN
        v_tickets_skipped := v_tickets_skipped + 1;
        v_skip_reasons := v_skip_reasons || COALESCE(v_print_res->>'reason', 'unknown');
      ELSE
        v_tickets_enqueued := v_tickets_enqueued + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_tickets_skipped := v_tickets_skipped + 1;
      v_skip_reasons := v_skip_reasons || ('error:' || SQLERRM);
      RAISE NOTICE '[cancel_order] cancel-ticket enqueue raised for item %: %',
        v_item_id, SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'order_id',         p_order_id,
    'status',           'cancelled',
    'cancel_tickets',   v_tickets_enqueued,
    'cancel_skipped',   v_tickets_skipped,
    'skip_reasons',     to_jsonb(v_skip_reasons)
  );
END;
$$;


ALTER FUNCTION "public"."cancel_order"("p_order_id" bigint, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_pending_payment"("p_payment_id" bigint, "p_tenant_id" bigint, "p_branch_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_payment RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT id, order_id, status
  INTO v_payment
  FROM public.payments
  WHERE id        = p_payment_id
    AND tenant_id = p_tenant_id
    AND branch_id = p_branch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0001';
  END IF;

  IF v_payment.status <> 'pending' THEN
    RAISE EXCEPTION 'payment_not_pending' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.payments
  SET status     = 'failed',
      updated_at = now()
  WHERE id = p_payment_id;

  UPDATE public.orders
  SET payment_status = 'unpaid',
      payment_method = NULL,
      updated_at     = now()
  WHERE id             = v_payment.order_id
    AND payment_status <> 'paid';
END;
$$;


ALTER FUNCTION "public"."cancel_pending_payment"("p_payment_id" bigint, "p_tenant_id" bigint, "p_branch_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_pending_payment"("p_payment_id" bigint, "p_tenant_id" bigint, "p_branch_id" bigint) IS 'Cancels a pending MoMo payment and resets order payment fields. Tenant/branch params guard against IDOR.';



CREATE OR REPLACE FUNCTION "public"."cancel_production_order"("p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tenant BIGINT := public.auth_tenant_id();
  v_order  RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_inventory_production_operator() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission_any('inventory:production_confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_order FROM public.production_orders
  WHERE id = p_order_id AND tenant_id = v_tenant FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_order.branch_id, 'inventory:production_confirm') THEN
    RAISE EXCEPTION 'branch_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF v_order.status <> 'draft' THEN
    RAISE EXCEPTION 'production_order_not_draft' USING ERRCODE = '22023';
  END IF;

  UPDATE public.production_orders
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_order_id AND tenant_id = v_tenant;

  RETURN jsonb_build_object('production_order_id', p_order_id, 'status', 'cancelled');
END;
$$;


ALTER FUNCTION "public"."cancel_production_order"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_shift_request"("p_request_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_user_id   UUID   := auth.uid();
  v_request   public.shift_requests%ROWTYPE;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'cancel_shift_request: missing auth context' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_request FROM public.shift_requests
  WHERE id = p_request_id AND tenant_id = v_tenant_id FOR UPDATE;
  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'cancel_shift_request: request not found' USING ERRCODE = 'no_data_found';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = v_request.employee_id AND e.profile_id = v_user_id AND e.tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'cancel_shift_request: not the request owner' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'cancel_shift_request: request is %, not pending', v_request.status USING ERRCODE = 'check_violation';
  END IF;
  UPDATE public.shift_requests
  SET status = 'cancelled', reviewed_by = v_user_id, reviewed_at = now()
  WHERE id = p_request_id;
  PERFORM public.log_audit(
    'cancel'::TEXT, 'shift_request'::TEXT, p_request_id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'cancelled')
  );
END;
$$;


ALTER FUNCTION "public"."cancel_shift_request"("p_request_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_menu_item_tenant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.menu_categories
    WHERE id = NEW.category_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'category does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_menu_item_tenant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_order_ready"("p_order_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pending_count INT;
  v_current_status TEXT;
BEGIN
  SELECT status INTO v_current_status
  FROM public.orders
  WHERE id = p_order_id
    AND tenant_id = public.auth_tenant_id()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_current_status IN ('ready', 'served', 'completed', 'cancelled') THEN
    RETURN;
  END IF;

  SELECT COUNT(*) INTO v_pending_count
  FROM public.kds_tickets
  WHERE order_id = p_order_id
    AND tenant_id = public.auth_tenant_id()
    AND status NOT IN ('ready', 'served', 'cancelled');

  IF v_pending_count = 0 THEN
    UPDATE public.orders
    SET status = 'ready',
        updated_at = now()
    WHERE id = p_order_id
      AND tenant_id = public.auth_tenant_id();

    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by
    )
    SELECT tenant_id, id, v_current_status, 'ready', auth.uid()
    FROM public.orders
    WHERE id = p_order_id
      AND tenant_id = public.auth_tenant_id();
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_order_ready"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_sides_tenant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.menu_items
    WHERE id = NEW.main_item_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'main item does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.menu_items
    WHERE id = NEW.side_item_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'side item does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_sides_tenant"() OWNER TO "postgres";


