CREATE OR REPLACE FUNCTION "public"."claim_print_job"("p_job_id" bigint, "p_agent_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated INT;
  v_is_service BOOLEAN := (auth.role() = 'service_role');
  v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  UPDATE public.print_jobs
    SET status = 'processing',
        claimed_by_agent = p_agent_id,
        claimed_at = now(),
        attempts = attempts + 1
    WHERE id = p_job_id
      AND status = 'pending'
      AND (v_is_service OR tenant_id = v_tenant);
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated = 1;
END;
$$;


ALTER FUNCTION "public"."claim_print_job"("p_job_id" bigint, "p_agent_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_abandoned_payments"("p_threshold" interval DEFAULT '24:00:00'::interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  UPDATE public.payments
  SET
    status = 'failed',
    provider_data = COALESCE(provider_data, '{}'::jsonb) || jsonb_build_object(
      'cleanup_reason', 'abandoned',
      'cleanup_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'cleanup_threshold', extract(epoch FROM p_threshold)::int
    ),
    updated_at = now()
  WHERE status = 'pending'
    AND created_at < now() - p_threshold;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_abandoned_payments"("p_threshold" interval) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_abandoned_payments"("p_threshold" interval) IS 'POS payment janitor: marks pending rows older than p_threshold (default 24h) as failed and stamps cleanup metadata into provider_data. Cron-scheduled hourly; safe to call manually for ad-hoc cleanup.';



CREATE OR REPLACE FUNCTION "public"."cleanup_kds_tickets_as_system"("p_older_than" timestamp with time zone, "p_reset_before_local_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted_total INT := 0;
  v_by_status JSONB := '{}'::jsonb;
  v_by_branch JSONB := '[]'::jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  IF p_older_than IS NULL AND p_reset_before_local_date IS NULL THEN
    RAISE EXCEPTION 'cleanup_cutoff_required' USING ERRCODE = '22023';
  END IF;

  WITH candidates AS (
    SELECT
      kt.id,
      kt.tenant_id,
      kt.branch_id,
      kt.status
    FROM public.kds_tickets kt
    JOIN public.branches b
      ON b.id = kt.branch_id
     AND b.tenant_id = kt.tenant_id
    LEFT JOIN public.kitchen_send_batches ksb
      ON ksb.id = kt.kitchen_send_batch_id
     AND ksb.tenant_id = kt.tenant_id
    WHERE kt.status IN ('pending', 'preparing', 'ready')
      AND b.branch_kind = 'branch'
      AND (
        (
          p_older_than IS NOT NULL
          AND COALESCE(ksb.created_at, kt.created_at) < p_older_than
        )
        OR (
          p_reset_before_local_date IS NOT NULL
          AND (
            COALESCE(ksb.created_at, kt.created_at)
              AT TIME ZONE 'Asia/Ho_Chi_Minh'
          )::date < p_reset_before_local_date
        )
      )
  ),
  deleted AS (
    DELETE FROM public.kds_tickets kt
    USING candidates c
    WHERE kt.id = c.id
    RETURNING kt.tenant_id, kt.branch_id, kt.status
  ),
  status_counts AS (
    SELECT status, count(*)::int AS deleted_count
    FROM deleted
    GROUP BY status
  ),
  branch_counts AS (
    SELECT tenant_id, branch_id, count(*)::int AS deleted_count
    FROM deleted
    GROUP BY tenant_id, branch_id
  )
  SELECT
    COALESCE((SELECT count(*)::int FROM deleted), 0),
    COALESCE(
      (SELECT jsonb_object_agg(status, deleted_count) FROM status_counts),
      '{}'::jsonb
    ),
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'tenant_id', tenant_id,
            'branch_id', branch_id,
            'deleted_count', deleted_count
          )
          ORDER BY tenant_id, branch_id
        )
        FROM branch_counts
      ),
      '[]'::jsonb
    )
  INTO v_deleted_total, v_by_status, v_by_branch;

  RETURN jsonb_build_object(
    'deleted_total', v_deleted_total,
    'by_status', v_by_status,
    'by_branch', v_by_branch,
    'older_than', p_older_than,
    'reset_before_local_date', p_reset_before_local_date
  );
END;
$$;


ALTER FUNCTION "public"."cleanup_kds_tickets_as_system"("p_older_than" timestamp with time zone, "p_reset_before_local_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_kds_tickets_as_system"("p_older_than" timestamp with time zone, "p_reset_before_local_date" "date") IS 'Service-role-only KDS board cleanup. Deletes active queue tickets older than the cutoff or before the current Asia/Ho_Chi_Minh local date; does not mutate orders, order_items, kitchen batches, or counters.';



CREATE OR REPLACE FUNCTION "public"."clear_branch_menu_daily_limit"("p_branch_id" bigint, "p_menu_item_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_role      TEXT   := public.auth_role();
  v_branch    BIGINT := public.auth_branch_id();
  v_today     DATE   := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_deleted   INT;
BEGIN
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF v_role NOT IN ('owner', 'super_manager', 'area_manager',
                    'branch_manager', 'cashier', 'chef') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_role IN ('branch_manager', 'cashier', 'chef')
     AND (v_branch IS NULL OR v_branch <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.branch_menu_item_daily_limits
   WHERE tenant_id = v_tenant_id
     AND branch_id = p_branch_id
     AND menu_item_id = p_menu_item_id
     AND limit_date = v_today;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN jsonb_build_object('deleted', v_deleted);
END;
$$;


ALTER FUNCTION "public"."clear_branch_menu_daily_limit"("p_branch_id" bigint, "p_menu_item_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_order_discount"("p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid          UUID;
  v_prof_tenant  BIGINT;
  v_prof_branch  BIGINT;
  v_prof_role    TEXT;
  v_order        RECORD;
  v_total_amount NUMERIC(15,2);
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(po.legacy_role_code, 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'super_manager', 'area_manager', 'branch_manager', 'cashier', 'waiter')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status,
         o.subtotal, o.service_charge, o.discount_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner', 'super_manager', 'area_manager') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  v_total_amount := COALESCE(v_order.subtotal, 0)
                  + COALESCE(v_order.service_charge, 0);

  UPDATE public.orders
     SET discount_type   = NULL,
         discount_value  = NULL,
         discount_note   = NULL,
         discount_amount = 0,
         total_amount    = v_total_amount,
         updated_at      = now()
   WHERE id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_order.tenant_id, p_order_id, v_order.status, v_order.status, v_uid,
    'discount_cleared (was '
      || COALESCE(v_order.discount_amount::TEXT, '0') || 'đ)'
  );

  RETURN jsonb_build_object(
    'order_id',     p_order_id,
    'total_amount', v_total_amount
  );
END;
$$;


ALTER FUNCTION "public"."clear_order_discount"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_fiscal_period"("p_tenant_id" bigint, "p_year" integer, "p_month" integer, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       UUID := auth.uid();
  v_period    RECORD;
  v_recon     JSONB;
  v_has_diff  BOOLEAN := FALSE;
  v_item      JSONB;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT fp.* INTO v_period FROM public.fiscal_periods fp
  WHERE fp.tenant_id = p_tenant_id AND fp.period_month = p_month AND fp.period_year = p_year
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'fiscal_period_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_period.status = 'closed' THEN RAISE EXCEPTION 'fiscal_period_already_closed' USING ERRCODE = '22023'; END IF;

  UPDATE public.fiscal_periods SET status = 'closing', updated_at = now() WHERE id = v_period.id;
  PERFORM public.refresh_finance_views();
  v_recon := public.gl_reconciliation(p_tenant_id, p_year, p_month);

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_recon) LOOP
    IF ABS((v_item ->> 'difference')::NUMERIC) > 1 THEN v_has_diff := TRUE; END IF;
  END LOOP;

  UPDATE public.fiscal_periods
  SET status = 'closed', closed_by = v_uid, closed_at = now(),
      notes = concat_ws(' ', NULLIF(v_period.notes, ''), NULLIF(p_notes, ''),
                       CASE WHEN v_has_diff THEN '[CẢNH BÁO: Có chênh lệch đối chiếu]' END),
      updated_at = now()
  WHERE id = v_period.id;

  RETURN jsonb_build_object('period_id', v_period.id, 'status', 'closed',
                            'has_discrepancies', v_has_diff, 'reconciliation', v_recon);
END;
$$;


ALTER FUNCTION "public"."close_fiscal_period"("p_tenant_id" bigint, "p_year" integer, "p_month" integer, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_period_hard"("p_tenant_id" bigint, "p_year" integer, "p_month" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN RAISE EXCEPTION 'cross-tenant close forbidden' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  INSERT INTO public.accounting_periods (tenant_id, year, month, soft_closed_at, hard_closed_at, closed_by)
  VALUES (p_tenant_id, p_year, p_month, now(), now(), v_uid)
  ON CONFLICT (tenant_id, year, month) DO UPDATE
    SET soft_closed_at = COALESCE(public.accounting_periods.soft_closed_at, EXCLUDED.soft_closed_at),
        hard_closed_at = COALESCE(public.accounting_periods.hard_closed_at, EXCLUDED.hard_closed_at),
        closed_by = EXCLUDED.closed_by;
END; $$;


