CREATE OR REPLACE FUNCTION "public"."custom_access_token_hook"("event" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  claims JSONB;
  user_profile RECORD;
BEGIN
  claims := event -> 'claims';

  SELECT
    p.tenant_id,
    p.branch_id,
    COALESCE(po.legacy_role_code, 'office')     AS user_role,
    COALESCE(po.code,             'unassigned') AS position_code
  INTO user_profile
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = (event ->> 'user_id')::uuid
  LIMIT 1;

  -- Row found iff tenant_id is present (NOT NULL constraint).
  -- Avoid `user_profile IS NOT NULL` which requires every field non-null.
  IF user_profile.tenant_id IS NOT NULL THEN
    claims := jsonb_set(
      claims,
      '{app_metadata}',
      COALESCE(claims -> 'app_metadata', '{}'::jsonb) ||
      jsonb_build_object(
        'tenant_id', user_profile.tenant_id,
        'branch_id', user_profile.branch_id,
        'user_role', user_profile.user_role,
        'position',  user_profile.position_code
      )
    );
  END IF;

  event := jsonb_set(event, '{claims}', claims);
  RETURN event;
END;
$$;


ALTER FUNCTION "public"."custom_access_token_hook"("event" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrement_branch_menu_daily_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_branch_id  BIGINT;
  v_order_date DATE;
  v_target     RECORD;
BEGIN
  IF OLD.status = 'cancelled' OR NEW.status <> 'cancelled' THEN
    RETURN NEW;
  END IF;

  SELECT o.branch_id,
         (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  INTO v_branch_id, v_order_date
  FROM public.orders o
  WHERE o.id = NEW.order_id;

  IF v_branch_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR v_target IN
    WITH agg AS (
      SELECT OLD.menu_item_id::BIGINT AS item_id,
             OLD.quantity::INT        AS need_qty
      UNION ALL
      SELECT (s.elem ->> 'side_item_id')::BIGINT,
             (OLD.quantity * COALESCE(NULLIF(s.elem ->> 'quantity', '')::INT, 1))::INT
      FROM jsonb_array_elements(COALESCE(OLD.sides, '[]'::jsonb)) AS s(elem)
      WHERE s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    )
    SELECT item_id, SUM(need_qty)::INT AS need_qty
    FROM agg
    WHERE item_id IS NOT NULL
    GROUP BY item_id
    ORDER BY item_id ASC
  LOOP
    UPDATE public.branch_menu_item_daily_limits
    SET sold_today = GREATEST(0, sold_today - v_target.need_qty)
    WHERE branch_id    = v_branch_id
      AND menu_item_id = v_target.item_id
      AND limit_date   = v_order_date;
  END LOOP;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."decrement_branch_menu_daily_limit"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."decrement_branch_menu_daily_limit"() IS 'AFTER UPDATE OF status on order_items (→ cancelled): symmetric decrement using OLD.menu_item_id + OLD.sides aggregated by menu_item_id ASC. Bounded at 0 via GREATEST.';



CREATE OR REPLACE FUNCTION "public"."edit_pending_order_item"("p_order_item_id" bigint, "p_variant_id" bigint, "p_variant_name" "text", "p_unit_price" numeric, "p_modifiers" "jsonb", "p_sides" "jsonb", "p_note" "text", "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid            UUID;
  v_prof_tenant    BIGINT;
  v_prof_branch    BIGINT;
  v_prof_role      TEXT;
  v_item           public.order_items%ROWTYPE;
  v_order          public.orders%ROWTYPE;
  v_menu_active    BOOLEAN;
  v_base_price     NUMERIC(15,2);
  v_variant_adj    NUMERIC(15,2) := 0;
  v_modifier_sum   NUMERIC(15,2) := 0;
  v_sides_sum      NUMERIC(15,2) := 0;
  v_enriched_sides JSONB := '[]'::JSONB;
  v_new_unit       NUMERIC(15,2);
  v_old_qty        INT;
  v_old_unit       NUMERIC(15,2);
  v_new_subtotal   NUMERIC(15,2);
  v_subtotal_sum   NUMERIC(15,2);
  v_disc_amount    NUMERIC(15,2);
  v_total_amount   NUMERIC(15,2);
  v_flag_enabled   TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(po.legacy_role_code, 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'waiter') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_quantity IS NULL OR p_quantity < 1 THEN
    RAISE EXCEPTION 'quantity must be >= 1' USING ERRCODE = '22023';
  END IF;

  IF p_unit_price IS NULL OR p_unit_price < 0 THEN
    RAISE EXCEPTION 'unit_price must be >= 0' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_item.order_id);

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_edit_pending_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'feature disabled' USING ERRCODE = '22023';
  END IF;

  IF v_item.status <> 'pending' THEN
    RAISE EXCEPTION 'item not editable' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  SELECT base_price, is_active
  INTO v_base_price, v_menu_active
  FROM public.menu_items
  WHERE id = v_item.menu_item_id AND tenant_id = v_order.tenant_id;

  IF NOT FOUND OR COALESCE(v_menu_active, FALSE) = FALSE THEN
    RAISE EXCEPTION 'menu item inactive' USING ERRCODE = '22023';
  END IF;

  IF p_variant_id IS NOT NULL THEN
    SELECT price_adjustment INTO v_variant_adj
    FROM public.menu_item_variants
    WHERE id = p_variant_id
      AND item_id = v_item.menu_item_id
      AND tenant_id = v_order.tenant_id
      AND is_active = TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'variant inactive' USING ERRCODE = '22023';
    END IF;
  ELSE
    v_variant_adj := 0;
  END IF;

  v_modifier_sum := public.pos_order_modifier_sum(
    v_order.tenant_id,
    v_item.menu_item_id,
    COALESCE(p_modifiers, '[]'::JSONB)
  );

  SELECT sides_sum, enriched_sides
  INTO v_sides_sum, v_enriched_sides
  FROM public.pos_enrich_order_sides(
    v_order.tenant_id,
    v_item.menu_item_id,
    COALESCE(p_sides, '[]'::JSONB)
  );

  v_new_unit := v_base_price + v_variant_adj + v_modifier_sum + COALESCE(v_sides_sum, 0);

  v_old_qty := v_item.quantity;
  v_old_unit := v_item.unit_price;
  v_new_subtotal := v_new_unit * p_quantity;

  UPDATE public.order_items
  SET variant_id   = p_variant_id,
      variant_name = NULLIF(p_variant_name, ''),
      unit_price   = v_new_unit,
      modifiers    = COALESCE(p_modifiers, '[]'::JSONB),
      sides        = COALESCE(v_enriched_sides, '[]'::JSONB),
      note         = NULLIF(trim(COALESCE(p_note, '')), ''),
      quantity     = p_quantity,
      subtotal     = v_new_subtotal,
      updated_at   = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET updated_at = now()
  WHERE order_item_id = p_order_item_id
    AND tenant_id = v_item.tenant_id
    AND status NOT IN ('served', 'cancelled');

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal_sum
  FROM public.order_items
  WHERE order_id = v_item.order_id AND status <> 'cancelled';

  v_disc_amount := public.compute_discount_amount(
    v_order.discount_type, v_order.discount_value, v_subtotal_sum
  );
  v_total_amount := v_subtotal_sum
    + COALESCE(v_order.service_charge, 0)
    - v_disc_amount;

  UPDATE public.orders
  SET subtotal        = v_subtotal_sum,
      discount_amount = v_disc_amount,
      total_amount    = v_total_amount,
      updated_at      = now()
  WHERE id = v_item.order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_item.tenant_id, v_item.order_id, v_order.status, v_order.status, v_uid,
    'edit_item ' || p_order_item_id::TEXT
      || ': qty ' || v_old_qty::TEXT || '->' || p_quantity::TEXT
      || ', unit ' || v_old_unit::TEXT || '->' || v_new_unit::TEXT
  );

  RETURN jsonb_build_object(
    'order_id',           v_item.order_id,
    'order_item_id',      p_order_item_id,
    'old_quantity',       v_old_qty,
    'new_quantity',       p_quantity,
    'subtotal',           v_subtotal_sum,
    'discount_amount',    v_disc_amount,
    'total_amount',       v_total_amount,
    'was_sent_to_kitchen', v_item.sent_to_kitchen_at IS NOT NULL
  );
END;
$$;


ALTER FUNCTION "public"."edit_pending_order_item"("p_order_item_id" bigint, "p_variant_id" bigint, "p_variant_name" "text", "p_unit_price" numeric, "p_modifiers" "jsonb", "p_sides" "jsonb", "p_note" "text", "p_quantity" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."edit_pending_order_item"("p_order_item_id" bigint, "p_variant_id" bigint, "p_variant_name" "text", "p_unit_price" numeric, "p_modifiers" "jsonb", "p_sides" "jsonb", "p_note" "text", "p_quantity" integer) IS 'Sửa món đã gửi khi status=pending (chef chưa bắt đầu nấu). Server recompute unit_price/subtotal từ menu (base + variant_adj + modifier_sum + sides_sum) — BỎ QUA p_unit_price từ client (giữ trong signature cho compat). Mirror create_order/append_order_items convention. Sides JSONB được enrich qua pos_enrich_order_sides. Lock order + item, gate qua pos:void_order. Recompute discount qua compute_discount_amount, bump kds_tickets.updated_at. Block khi status<>pending, order completed/cancelled, payment_status=paid, menu_item inactive, variant inactive, feature flag pos_edit_pending_enabled=false.';



CREATE OR REPLACE FUNCTION "public"."enable_offline_for_session"("p_session_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_ss RECORD;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_ss FROM public.stocktake_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(NULL, 'settings:tenant') THEN
    RAISE EXCEPTION 'forbidden: settings:tenant required for offline pilot' USING ERRCODE = '42501';
  END IF;
  IF v_ss.status <> 'in_progress' THEN RAISE EXCEPTION 'session not in_progress (status=%)', v_ss.status USING ERRCODE = '22023'; END IF;
  IF v_ss.offline_enabled THEN RAISE EXCEPTION 'offline already enabled for session %', p_session_id USING ERRCODE = '22023'; END IF;
  UPDATE public.stocktake_sessions SET offline_enabled = true, offline_enabled_by = v_uid, offline_enabled_at = now()
   WHERE id = p_session_id;
  RETURN jsonb_build_object('session_id', p_session_id, 'offline_enabled', true, 'enabled_by', v_uid, 'enabled_at', now());
END; $$;


ALTER FUNCTION "public"."enable_offline_for_session"("p_session_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_branch_menu_daily_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_branch_id  BIGINT;
  v_order_date DATE;
  v_target     RECORD;
  v_limit      RECORD;
BEGIN
  IF COALESCE(current_setting('comtammatu.skip_quota_enforcement', true), 'false') = 'true' THEN
    RETURN NEW;
  END IF;

  SELECT o.branch_id,
         (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  INTO v_branch_id, v_order_date
  FROM public.orders o
  WHERE o.id = NEW.order_id;

  IF v_branch_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR v_target IN
    WITH agg AS (
      SELECT NEW.menu_item_id::BIGINT AS item_id,
             NEW.quantity::INT        AS need_qty
      UNION ALL
      SELECT (s.elem ->> 'side_item_id')::BIGINT,
             (NEW.quantity * COALESCE(NULLIF(s.elem ->> 'quantity', '')::INT, 1))::INT
      FROM jsonb_array_elements(COALESCE(NEW.sides, '[]'::jsonb)) AS s(elem)
      WHERE s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    )
    SELECT item_id, SUM(need_qty)::INT AS need_qty
    FROM agg
    WHERE item_id IS NOT NULL
    GROUP BY item_id
    ORDER BY item_id ASC
  LOOP
    SELECT * INTO v_limit
    FROM public.branch_menu_item_daily_limits
    WHERE branch_id    = v_branch_id
      AND menu_item_id = v_target.item_id
      AND limit_date   = v_order_date
    FOR UPDATE;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    IF v_limit.is_disabled THEN
      RAISE EXCEPTION 'daily_limit_item_disabled: %', v_target.item_id
        USING ERRCODE = 'P0001';
    END IF;

    IF v_limit.limit_quantity IS NOT NULL
       AND v_limit.sold_today + v_target.need_qty > v_limit.limit_quantity THEN
      RAISE EXCEPTION 'daily_limit_exceeded: item %, limit %, sold %, requested %',
        v_target.item_id, v_limit.limit_quantity, v_limit.sold_today, v_target.need_qty
        USING ERRCODE = 'P0001';
    END IF;

    UPDATE public.branch_menu_item_daily_limits
    SET sold_today = sold_today + v_target.need_qty
    WHERE id = v_limit.id;
  END LOOP;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."enforce_branch_menu_daily_limit"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_branch_menu_daily_limit"() IS 'AFTER INSERT on order_items: aggregate main + sides (JSONB) by menu_item_id ASC, lock each limit row FOR UPDATE, raise P0001 daily_limit_item_disabled / daily_limit_exceeded, increment sold_today. Skip-hatch: GUC comtammatu.skip_quota_enforcement = ''true'' (set by split-partial RPC).';



CREATE OR REPLACE FUNCTION "public"."enforce_period_close"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_status TEXT; v_effective TIMESTAMPTZ; v_tenant BIGINT;
BEGIN
  v_effective := (row_to_json(NEW.*)->>'effective_date')::TIMESTAMPTZ;
  v_tenant    := (row_to_json(NEW.*)->>'tenant_id')::BIGINT;
  IF v_effective IS NULL OR v_tenant IS NULL THEN RETURN NEW; END IF;
  v_status := public.period_status_at(v_tenant, v_effective);
  IF v_status = 'hard_closed' THEN
    IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN
      RAISE EXCEPTION 'target period is hard-closed' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."enforce_period_close"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_period_close_stock_issues"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_status TEXT;
BEGIN
  IF NEW.issued_at IS NULL OR NEW.tenant_id IS NULL THEN RETURN NEW; END IF;
  v_status := public.period_status_at(NEW.tenant_id, NEW.issued_at);
  IF v_status = 'hard_closed' AND NOT public.has_permission(NULL, 'accounting:period_reopen') THEN
    RAISE EXCEPTION 'target accounting period is hard-closed; accounting:period_reopen required' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."enforce_period_close_stock_issues"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_po_grn_branch_is_procurement"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.branches b
    WHERE b.id = NEW.branch_id
      AND b.tenant_id = NEW.tenant_id
      AND b.branch_kind IN ('central_warehouse', 'central_kitchen')
  ) THEN
    RAISE EXCEPTION 'branch must be central_warehouse or central_kitchen' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_po_grn_branch_is_procurement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_stock_transfer_direction"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from_kind TEXT;
  v_to_kind   TEXT;
BEGIN
  -- Intra-branch (same id): allowed; rely on app layer for location semantics.
  IF NEW.from_branch_id = NEW.to_branch_id THEN
    RETURN NEW;
  END IF;

  SELECT b.branch_kind INTO v_from_kind
  FROM public.branches b
  WHERE b.id = NEW.from_branch_id AND b.tenant_id = NEW.tenant_id;

  SELECT b.branch_kind INTO v_to_kind
  FROM public.branches b
  WHERE b.id = NEW.to_branch_id AND b.tenant_id = NEW.tenant_id;

  IF v_from_kind IS NULL OR v_to_kind IS NULL THEN
    RAISE EXCEPTION 'stock_transfers: invalid branch reference' USING ERRCODE = '23514';
  END IF;

  -- Whitelist valid inter-branch directions.
  IF (v_from_kind = 'central_warehouse' AND v_to_kind = 'central_kitchen')
  OR (v_from_kind = 'central_warehouse' AND v_to_kind = 'branch')
  OR (v_from_kind = 'central_kitchen'   AND v_to_kind = 'branch')
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'stock_transfers: invalid direction % -> %', v_from_kind, v_to_kind
    USING ERRCODE = '23514';
END;
$$;


ALTER FUNCTION "public"."enforce_stock_transfer_direction"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_stock_transfer_direction"() IS 'Allowed transfers: CW→CK, CW→Branch, CK→Branch, intra-branch. Reject all others.';



CREATE OR REPLACE FUNCTION "public"."enqueue_cancel_ticket_print"("p_order_item_id" bigint, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid           UUID;
  v_item          public.order_items%ROWTYPE;
  v_order         public.orders%ROWTYPE;
  v_table_no      INT;
  v_slot          SMALLINT;
  v_printer_id    BIGINT;
  v_category_id   BIGINT;
  v_voided_by     TEXT;
  v_flag_enabled  TEXT;
  v_items_payload JSONB;
  v_payload       JSONB;
  v_idempotency   TEXT;
  v_job_id        BIGINT;
  v_now           TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_cancel_ticket_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'feature_disabled');
  END IF;

  IF v_item.sent_to_kitchen_at IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_sent');
  END IF;

  SELECT mi.category_id INTO v_category_id
  FROM public.menu_items mi
  WHERE mi.id = v_item.menu_item_id;

  IF NOT EXISTS (
    SELECT 1
    FROM public.printer_menu_categories pmc
    WHERE pmc.tenant_id = v_order.tenant_id
      AND pmc.branch_id = v_order.branch_id
      AND pmc.category_id = v_category_id
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  SELECT p.id, CASE WHEN p.role = 'kitchen_2' THEN 2 ELSE 1 END
  INTO v_printer_id, v_slot
  FROM public.printer_menu_categories pmc
  JOIN public.printers p
    ON p.id = pmc.printer_id
   AND p.tenant_id = pmc.tenant_id
   AND p.branch_id = pmc.branch_id
   AND p.is_active = TRUE
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = 'cancel_ticket'
  WHERE pmc.tenant_id = v_order.tenant_id
    AND pmc.branch_id = v_order.branch_id
    AND pmc.category_id = v_category_id
  ORDER BY p.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_voided_by
  FROM public.profiles WHERE id = v_uid;

  v_items_payload := jsonb_build_array(jsonb_build_object(
    'item_name',    v_item.item_name,
    'variant_name', v_item.variant_name,
    'quantity',     v_item.quantity,
    'modifiers',    v_item.modifiers,
    'sides',        v_item.sides,
    'note',         v_item.note
  ));

  v_payload := jsonb_build_object(
    'kind',          'cancel_ticket',
    'order_number',  v_order.order_number,
    'order_type',    v_order.order_type,
    'table_number',  v_table_no,
    'slot',          v_slot,
    'items',         v_items_payload,
    'reason',        COALESCE(NULLIF(trim(p_reason), ''), v_item.cancel_reason, ''),
    'voided_by',     COALESCE(v_voided_by, ''),
    'printed_at',    to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                             'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || v_order.id::TEXT
    || ':cancel:' || p_order_item_id::TEXT;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'cancel_ticket',
    v_order.id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'slot',       v_slot
  );
END;
$$;


ALTER FUNCTION "public"."enqueue_cancel_ticket_print"("p_order_item_id" bigint, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_cancel_ticket_print"("p_order_item_id" bigint, "p_reason" "text") IS 'Enqueue a PHIẾU HUỶ MÓN print job targeting the original kitchen slot. Skips silently (returns skipped:true) when feature flag off, item never sent to kitchen, category has no slot, or no active printer for the slot. Called by the voidOrderItem Server Action after void_order_item commits.';



CREATE OR REPLACE FUNCTION "public"."enqueue_edit_pending_order_item_quantity_print"("p_order_item_id" bigint, "p_old_quantity" integer, "p_new_quantity" integer, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_item            public.order_items%ROWTYPE;
  v_order           public.orders%ROWTYPE;
  v_table_no        INT;
  v_slot            SMALLINT;
  v_printer_id      BIGINT;
  v_category_id     BIGINT;
  v_staff_name      TEXT;
  v_flag_enabled    TEXT;
  v_delta           INT;
  v_print_type      TEXT;
  v_items_payload   JSONB;
  v_payload         JSONB;
  v_idempotency     TEXT;
  v_job_id          BIGINT;
  v_now             TIMESTAMPTZ := now();
  v_change_note     TEXT;
  v_item_note       TEXT;
  v_event_token     TEXT;
  v_batch_ticket_number TEXT;
  v_batch_send_seq      INT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_old_quantity IS NULL OR p_new_quantity IS NULL
     OR p_old_quantity < 1 OR p_new_quantity < 1
  THEN
    RAISE EXCEPTION 'quantity must be >= 1' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  IF v_item.sent_to_kitchen_at IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_sent');
  END IF;

  IF p_old_quantity = p_new_quantity THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_quantity_change');
  END IF;

  IF p_new_quantity < p_old_quantity THEN
    SELECT value INTO v_flag_enabled
    FROM public.system_settings
    WHERE tenant_id = v_order.tenant_id AND key = 'pos_reduce_qty_enabled';
    IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
      RETURN jsonb_build_object('skipped', true, 'reason', 'feature_disabled');
    END IF;
  END IF;

  SELECT mi.category_id INTO v_category_id
  FROM public.menu_items mi
  WHERE mi.id = v_item.menu_item_id
    AND mi.tenant_id = v_order.tenant_id;

  IF v_category_id IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.printer_menu_categories pmc
    WHERE pmc.tenant_id = v_order.tenant_id
      AND pmc.branch_id = v_order.branch_id
      AND pmc.category_id = v_category_id
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  v_delta := abs(p_new_quantity - p_old_quantity);
  v_print_type := CASE
    WHEN p_new_quantity > p_old_quantity THEN 'kitchen_ticket'
    ELSE 'cancel_ticket'
  END;

  SELECT p.id, CASE WHEN p.role = 'kitchen_2' THEN 2 ELSE 1 END
  INTO v_printer_id, v_slot
  FROM public.printer_menu_categories pmc
  JOIN public.printers p
    ON p.id = pmc.printer_id
   AND p.tenant_id = pmc.tenant_id
   AND p.branch_id = pmc.branch_id
   AND p.is_active = TRUE
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = v_print_type
  WHERE pmc.tenant_id = v_order.tenant_id
    AND pmc.branch_id = v_order.branch_id
    AND pmc.category_id = v_category_id
  ORDER BY p.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_staff_name
  FROM public.profiles WHERE id = v_uid;

  SELECT ksb.kitchen_ticket_number, ksb.send_seq
  INTO v_batch_ticket_number, v_batch_send_seq
  FROM public.kds_tickets kt
  JOIN public.kitchen_send_batches ksb
    ON ksb.id = kt.kitchen_send_batch_id
  WHERE kt.tenant_id = v_order.tenant_id
    AND kt.order_item_id = v_item.id
  ORDER BY ksb.created_at DESC
  LIMIT 1;

  v_change_note := CASE
    WHEN p_new_quantity > p_old_quantity THEN
      'TANG SL ' || p_old_quantity::TEXT || ' -> ' || p_new_quantity::TEXT
    ELSE
      'GIAM SL ' || p_old_quantity::TEXT || ' -> ' || p_new_quantity::TEXT
  END;

  v_item_note := v_change_note
    || CASE
      WHEN NULLIF(trim(COALESCE(v_item.note, '')), '') IS NULL THEN ''
      ELSE ': ' || trim(v_item.note)
    END;

  v_items_payload := jsonb_build_array(jsonb_build_object(
    'item_name',    v_item.item_name,
    'variant_name', v_item.variant_name,
    'quantity',     v_delta,
    'modifiers',    v_item.modifiers,
    'sides',        v_item.sides,
    'note',         v_item_note
  ));

  v_event_token := replace(
    COALESCE(extract(epoch from v_item.updated_at)::NUMERIC(20,6)::TEXT, ''),
    '.',
    ''
  );

  IF p_new_quantity > p_old_quantity THEN
    v_payload := jsonb_build_object(
      'kind',                  'kitchen_ticket',
      'kitchen_ticket_number', COALESCE(v_batch_ticket_number, v_order.order_number),
      'source_order_number',   v_order.order_number,
      'order_number',          v_order.order_number,
      'order_type',            v_order.order_type,
      'table_number',          v_table_no,
      'cashier_name',          COALESCE(v_staff_name, ''),
      'send_seq',              COALESCE(v_batch_send_seq, v_order.kitchen_send_count, 1),
      'send_kind',             'append',
      'slot',                  v_slot,
      'note',                  v_change_note,
      'items',                 v_items_payload,
      'printed_at',            to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                       'YYYY-MM-DD"T"HH24:MI:SS')
    );
  ELSE
    v_payload := jsonb_build_object(
      'kind',         'cancel_ticket',
      'order_number', v_order.order_number,
      'order_type',   v_order.order_type,
      'table_number', v_table_no,
      'slot',         v_slot,
      'items',        v_items_payload,
      'reason',       v_change_note || ': '
                      || COALESCE(NULLIF(trim(p_reason), ''), 'Sua so luong mon'),
      'voided_by',    COALESCE(v_staff_name, ''),
      'printed_at',   to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                              'YYYY-MM-DD"T"HH24:MI:SS')
    );
  END IF;

  v_idempotency := 'order:' || v_order.id::TEXT
    || ':edit-qty:' || p_order_item_id::TEXT
    || ':' || p_old_quantity::TEXT || '->' || p_new_quantity::TEXT
    || ':printer:' || v_printer_id::TEXT
    || ':at:' || v_event_token;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, v_print_type,
    v_order.id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_id;

  IF v_job_id IS NULL THEN
    SELECT id INTO v_job_id
    FROM public.print_jobs
    WHERE idempotency_key = v_idempotency;
  END IF;

  RETURN jsonb_build_object(
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'slot',       v_slot,
    'job_type',   v_print_type,
    'delta',      v_delta
  );
END;
$$;


ALTER FUNCTION "public"."enqueue_edit_pending_order_item_quantity_print"("p_order_item_id" bigint, "p_old_quantity" integer, "p_new_quantity" integer, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_edit_pending_order_item_quantity_print"("p_order_item_id" bigint, "p_old_quantity" integer, "p_new_quantity" integer, "p_reason" "text") IS 'Enqueue a kitchen-visible print delta after edit_pending_order_item changes quantity for an already-sent pending item. Increase uses kitchen_ticket (GỌI THÊM); decrease uses cancel_ticket. Returns skipped reasons for not_sent, no_quantity_change, no_slot, no_printer, and feature_disabled.';



CREATE OR REPLACE FUNCTION "public"."enqueue_kitchen_print"("p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN private.enqueue_kitchen_print_internal(p_order_id, NULL, TRUE);
END;
$$;


ALTER FUNCTION "public"."enqueue_kitchen_print"("p_order_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_kitchen_print"("p_order_id" bigint) IS 'Enqueue kitchen tickets using branch-scoped printer_menu_categories, not tenant-wide menu_categories.kitchen_printer.';



CREATE OR REPLACE FUNCTION "public"."enqueue_partial_cancel_ticket_print"("p_order_item_id" bigint, "p_old_quantity" integer, "p_new_quantity" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_item            public.order_items%ROWTYPE;
  v_order           public.orders%ROWTYPE;
  v_table_no        INT;
  v_slot            SMALLINT;
  v_printer_id      BIGINT;
  v_category_id     BIGINT;
  v_voided_by       TEXT;
  v_flag_enabled    TEXT;
  v_items_payload   JSONB;
  v_payload         JSONB;
  v_idempotency     TEXT;
  v_job_id          BIGINT;
  v_now             TIMESTAMPTZ := now();
  v_reason_prefixed TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_reduce_qty_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'feature_disabled');
  END IF;

  IF v_item.sent_to_kitchen_at IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_sent');
  END IF;

  IF p_new_quantity >= p_old_quantity THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_reduction');
  END IF;

  SELECT mi.category_id INTO v_category_id
  FROM public.menu_items mi
  WHERE mi.id = v_item.menu_item_id;

  IF NOT EXISTS (
    SELECT 1
    FROM public.printer_menu_categories pmc
    WHERE pmc.tenant_id = v_order.tenant_id
      AND pmc.branch_id = v_order.branch_id
      AND pmc.category_id = v_category_id
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  SELECT p.id, CASE WHEN p.role = 'kitchen_2' THEN 2 ELSE 1 END
  INTO v_printer_id, v_slot
  FROM public.printer_menu_categories pmc
  JOIN public.printers p
    ON p.id = pmc.printer_id
   AND p.tenant_id = pmc.tenant_id
   AND p.branch_id = pmc.branch_id
   AND p.is_active = TRUE
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = 'cancel_ticket'
  WHERE pmc.tenant_id = v_order.tenant_id
    AND pmc.branch_id = v_order.branch_id
    AND pmc.category_id = v_category_id
  ORDER BY p.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_voided_by
  FROM public.profiles WHERE id = v_uid;

  v_items_payload := jsonb_build_array(jsonb_build_object(
    'item_name',     v_item.item_name,
    'variant_name',  v_item.variant_name,
    'quantity',      p_old_quantity - p_new_quantity,
    'modifiers',     v_item.modifiers,
    'sides',         v_item.sides,
    'note',          v_item.note
  ));

  v_reason_prefixed := 'GIAM SL ' || p_old_quantity::TEXT
    || ' -> ' || p_new_quantity::TEXT
    || ': ' || COALESCE(NULLIF(trim(p_reason), ''), '');

  v_payload := jsonb_build_object(
    'kind',          'cancel_ticket',
    'order_number',  v_order.order_number,
    'order_type',    v_order.order_type,
    'table_number',  v_table_no,
    'slot',          v_slot,
    'items',         v_items_payload,
    'reason',        v_reason_prefixed,
    'voided_by',     COALESCE(v_voided_by, ''),
    'printed_at',    to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                             'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || v_order.id::TEXT
    || ':reduce:' || p_order_item_id::TEXT
    || ':' || p_old_quantity::TEXT || '->' || p_new_quantity::TEXT;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'cancel_ticket',
    v_order.id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'slot',       v_slot
  );
END;
$$;


ALTER FUNCTION "public"."enqueue_partial_cancel_ticket_print"("p_order_item_id" bigint, "p_old_quantity" integer, "p_new_quantity" integer, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_partial_cancel_ticket_print"("p_order_item_id" bigint, "p_old_quantity" integer, "p_new_quantity" integer, "p_reason" "text") IS 'Enqueue PHIẾU GIẢM SL — payload.kind=cancel_ticket (reuse template HUỶ MÓN ở print-agent), items[].quantity=delta (số phần bị giảm), reason prefix "GIẢM SL N → M:" để chef phân biệt với phiếu huỷ-toàn-phần. Skip silently khi feature flag off, item chưa gửi bếp, không có slot/printer. Idempotency key bao gồm old_qty+new_qty cho phép giảm nhiều lần (5→3 rồi 3→1) mà vẫn dedup double-submit cùng delta.';



CREATE OR REPLACE FUNCTION "public"."enqueue_provisional_bill"("p_order_id" bigint, "p_qr_content" "text" DEFAULT NULL::"text", "p_qr_header_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid          UUID;
  v_order        public.orders%ROWTYPE;
  v_branch       public.branches%ROWTYPE;
  v_table_no     INT;
  v_printer_id   BIGINT;
  v_cashier_name TEXT;
  v_branch_tax   TEXT;
  v_qr_type      TEXT;
  v_flag_enabled TEXT;
  v_vietqr_bank  TEXT;
  v_vietqr_acc   TEXT;
  v_vietqr_name  TEXT;
  v_payment_qr   JSONB;
  v_items        JSONB;
  v_payload      JSONB;
  v_idempotency  TEXT;
  v_job_id       BIGINT;
  v_now          TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:print') THEN
    RAISE EXCEPTION 'permission denied: pos:print' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_provisional_bill_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'provisional bill printing is disabled' USING ERRCODE = 'P0001';
  END IF;

  IF v_order.payment_status = 'paid' THEN
    RAISE EXCEPTION 'order already paid; cannot print provisional bill' USING ERRCODE = 'P0001';
  END IF;

  IF v_order.status = 'cancelled' THEN
    RAISE EXCEPTION 'order is cancelled; cannot print provisional bill' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_branch FROM public.branches WHERE id = v_order.branch_id;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_order.created_by;

  SELECT value INTO v_branch_tax
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'branch_tax_code';

  v_printer_id := public.resolve_branch_printer_for_type(
    v_order.tenant_id,
    v_order.branch_id,
    'provisional_bill'
  );

  IF v_printer_id IS NULL THEN
    RAISE EXCEPTION 'no active receipt printer for branch %', v_order.branch_id
      USING ERRCODE = 'P0002';
  END IF;

  IF p_qr_content IS NOT NULL AND length(trim(p_qr_content)) > 0 THEN
    SELECT value INTO v_qr_type
    FROM public.system_settings
    WHERE tenant_id = v_order.tenant_id AND key = 'payment_qr_type';
    v_qr_type := COALESCE(v_qr_type, 'vietqr');

    IF v_qr_type = 'vietqr' THEN
      SELECT value INTO v_vietqr_bank FROM public.system_settings
       WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_bank_code';
      SELECT value INTO v_vietqr_acc FROM public.system_settings
       WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_no';
      SELECT value INTO v_vietqr_name FROM public.system_settings
       WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_name';
    END IF;

    v_payment_qr := jsonb_build_object(
      'type',          v_qr_type,
      'content',       p_qr_content,
      'header_label',  COALESCE(p_qr_header_label, UPPER(v_qr_type)),
      'account_no',    v_vietqr_acc,
      'account_name',  v_vietqr_name,
      'amount',        v_order.total_amount,
      'description',   'DH ' || v_order.order_number
    );
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'item_name',    oi.item_name,
      'variant_name', oi.variant_name,
      'quantity',     oi.quantity,
      'unit_price',   oi.unit_price,
      'modifiers',    oi.modifiers,
      'sides',        oi.sides,
      'subtotal',     oi.subtotal,
      'note',         oi.note
    )
    ORDER BY oi.id
  )
  INTO v_items
  FROM public.order_items oi
  WHERE oi.order_id = p_order_id
    AND oi.status <> 'cancelled';

  v_payload := jsonb_build_object(
    'kind',             'provisional_bill',
    'branch_name',      COALESCE(v_branch.name, ''),
    'branch_address',   COALESCE(v_branch.address, ''),
    'branch_phone',     COALESCE(v_branch.phone, ''),
    'branch_tax_code',  COALESCE(v_branch_tax, ''),
    'order_number',     v_order.order_number,
    'order_type',       v_order.order_type,
    'table_number',     v_table_no,
    'customer_count',   v_order.customer_count,
    'cashier_name',     COALESCE(v_cashier_name, ''),
    'note',             v_order.note,
    'items',            COALESCE(v_items, '[]'::jsonb),
    'subtotal',         v_order.subtotal,
    'tax_amount',       v_order.tax_amount,
    'service_charge',   v_order.service_charge,
    'discount_amount',  v_order.discount_amount,
    'total_amount',     v_order.total_amount,
    'payment_qr',       v_payment_qr,
    'created_at',       to_char(v_order.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS'),
    'printed_at',       to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || p_order_id::TEXT
    || ':provisional:' || extract(epoch from v_now)::BIGINT::TEXT;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  )
  VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'provisional_bill',
    p_order_id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET payload = EXCLUDED.payload
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'order_id',   p_order_id,
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'qr_type',    v_qr_type
  );
END;
$$;


ALTER FUNCTION "public"."enqueue_provisional_bill"("p_order_id" bigint, "p_qr_content" "text", "p_qr_header_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_receipt_print"("p_order_id" bigint, "p_cash_received" numeric DEFAULT NULL::numeric, "p_cash_change" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid          UUID;
  v_order        public.orders%ROWTYPE;
  v_branch       public.branches%ROWTYPE;
  v_table_no     INT;
  v_printer_id   BIGINT;
  v_cashier_name TEXT;
  v_branch_tax   TEXT;
  v_items        JSONB;
  v_payload      JSONB;
  v_idempotency  TEXT;
  v_job_id       BIGINT;
  v_now          TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.has_permission_any('pos:print')
    OR public.has_permission_any('pos:reprint_receipt')
  ) THEN
    RAISE EXCEPTION 'permission denied: pos:print' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_branch FROM public.branches WHERE id = v_order.branch_id;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_order.created_by;

  SELECT value INTO v_branch_tax
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'branch_tax_code';

  v_printer_id := public.resolve_branch_printer_for_type(
    v_order.tenant_id,
    v_order.branch_id,
    'receipt'
  );

  IF v_printer_id IS NULL THEN
    RAISE EXCEPTION 'no active receipt printer for branch %', v_order.branch_id
      USING ERRCODE = 'P0002';
  END IF;

  IF p_cash_received IS NOT NULL OR p_cash_change IS NOT NULL THEN
    UPDATE public.orders
       SET cash_received = p_cash_received,
           cash_change   = p_cash_change
     WHERE id = p_order_id;
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'item_name',    oi.item_name,
      'variant_name', oi.variant_name,
      'quantity',     oi.quantity,
      'unit_price',   oi.unit_price,
      'modifiers',    oi.modifiers,
      'sides',        oi.sides,
      'subtotal',     oi.subtotal,
      'note',         oi.note
    )
    ORDER BY oi.id
  )
  INTO v_items
  FROM public.order_items oi
  WHERE oi.order_id = p_order_id
    AND oi.status <> 'cancelled';

  v_payload := jsonb_build_object(
    'kind',             'receipt',
    'branch_name',      COALESCE(v_branch.name, ''),
    'branch_address',   COALESCE(v_branch.address, ''),
    'branch_phone',     COALESCE(v_branch.phone, ''),
    'branch_tax_code',  COALESCE(v_branch_tax, ''),
    'order_number',     v_order.order_number,
    'order_type',       v_order.order_type,
    'table_number',     v_table_no,
    'customer_count',   v_order.customer_count,
    'cashier_name',     COALESCE(v_cashier_name, ''),
    'note',             v_order.note,
    'items',            COALESCE(v_items, '[]'::jsonb),
    'subtotal',         v_order.subtotal,
    'tax_amount',       v_order.tax_amount,
    'service_charge',   v_order.service_charge,
    'discount_amount',  v_order.discount_amount,
    'total_amount',     v_order.total_amount,
    'payment_method',   v_order.payment_method,
    'cash_received',    p_cash_received,
    'cash_change',      p_cash_change,
    'created_at',       to_char(v_order.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS'),
    'printed_at',       to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || p_order_id::TEXT || ':receipt';

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  )
  VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'receipt',
    p_order_id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET
    payload    = EXCLUDED.payload,
    printer_id = EXCLUDED.printer_id,
    status = CASE
               WHEN public.print_jobs.status IN ('failed','expired','printed')
               THEN 'pending'
               ELSE public.print_jobs.status
             END,
    last_error       = NULL,
    claimed_by_agent = NULL,
    claimed_at       = NULL
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'order_id',   p_order_id,
    'job_id',     v_job_id,
    'printer_id', v_printer_id
  );
END;
$$;


ALTER FUNCTION "public"."enqueue_receipt_print"("p_order_id" bigint, "p_cash_received" numeric, "p_cash_change" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_shift_close_print"("p_session_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid                 UUID;
  v_session             RECORD;
  v_branch              RECORD;
  v_cashier_name        TEXT;
  v_approver_name       TEXT;
  v_branch_tax          TEXT;
  v_printer_id          BIGINT;
  v_breakdown           JSONB;
  v_total_revenue       NUMERIC(15,2);
  v_item_breakdown      JSONB;
  v_total_item_quantity INT;
  v_payload             JSONB;
  v_idempotency         TEXT;
  v_job_id              BIGINT;
  v_now                 TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT id, tenant_id, branch_id, status, opening_cash, closing_cash,
         expected_cash, cash_difference, opened_at, closed_at, closed_by,
         note, variance_approval_note, variance_approver_user_id
  INTO v_session
  FROM public.pos_sessions
  WHERE id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_session.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_session.status <> 'closed' THEN
    RAISE EXCEPTION 'session not closed yet' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission_any('pos:close_shift') THEN
    RAISE EXCEPTION 'permission denied: pos:close_shift' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_branch FROM public.branches WHERE id = v_session.branch_id;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_session.closed_by;

  IF v_session.variance_approver_user_id IS NOT NULL THEN
    SELECT full_name INTO v_approver_name
    FROM public.profiles WHERE id = v_session.variance_approver_user_id;
  END IF;

  SELECT value INTO v_branch_tax
  FROM public.system_settings
  WHERE tenant_id = v_session.tenant_id AND key = 'branch_tax_code';

  v_printer_id := public.resolve_branch_printer_for_type(
    v_session.tenant_id,
    v_session.branch_id,
    'shift_close_report'
  );

  IF v_printer_id IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'method',  payment_method,
      'count',   cnt,
      'amount',  amount
    ) ORDER BY payment_method), '[]'::jsonb),
    COALESCE(SUM(amount), 0)
  INTO v_breakdown, v_total_revenue
  FROM (
    SELECT
      COALESCE(payment_method, 'unknown') AS payment_method,
      COUNT(*) AS cnt,
      SUM(total_amount) AS amount
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND payment_status = 'paid'
      AND status <> 'cancelled'
    GROUP BY payment_method
  ) AS grp;

  WITH paid_items AS (
    SELECT
      oi.item_name,
      oi.quantity,
      oi.unit_price,
      CASE
        WHEN jsonb_typeof(oi.modifiers) = 'array' THEN oi.modifiers
        ELSE '[]'::jsonb
      END AS modifiers,
      CASE
        WHEN jsonb_typeof(oi.sides) = 'array' THEN oi.sides
        ELSE '[]'::jsonb
      END AS sides
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    WHERE o.pos_session_id = p_session_id
      AND o.tenant_id = v_session.tenant_id
      AND o.payment_status = 'paid'
      AND o.status <> 'cancelled'
      AND oi.status <> 'cancelled'
  ),
  item_unit_prices AS (
    SELECT
      pi.item_name,
      pi.quantity,
      pi.unit_price,
      pi.modifiers,
      pi.sides,
      COALESCE((
        SELECT SUM(COALESCE(NULLIF(m->>'price', '')::numeric, 0))
        FROM jsonb_array_elements(pi.modifiers) AS m
      ), 0) AS modifier_unit_sum,
      COALESCE((
        SELECT SUM(
          COALESCE(NULLIF(s->>'price', '')::numeric, 0)
          * COALESCE(NULLIF(s->>'quantity', '')::numeric, 1)
        )
        FROM jsonb_array_elements(pi.sides) AS s
      ), 0) AS side_unit_sum
    FROM paid_items pi
  ),
  main_agg AS (
    SELECT
      item_name AS name,
      'main'::TEXT AS source,
      COALESCE(SUM(COALESCE(quantity, 0)), 0)::INT AS qty,
      COALESCE(SUM(GREATEST(0, COALESCE(unit_price, 0) - modifier_unit_sum - side_unit_sum) * COALESCE(quantity, 0)), 0) AS revenue,
      1 AS source_order
    FROM item_unit_prices
    GROUP BY item_name
  ),
  side_agg AS (
    SELECT
      COALESCE(NULLIF(s->>'name', ''), NULLIF(s->>'side_item_name', ''), 'Side')::TEXT AS name,
      'side'::TEXT AS source,
      COALESCE(SUM(COALESCE(NULLIF(s->>'quantity', '')::numeric, 1) * COALESCE(pi.quantity, 0)), 0)::INT AS qty,
      COALESCE(SUM(
        COALESCE(NULLIF(s->>'price', '')::numeric, 0)
        * COALESCE(NULLIF(s->>'quantity', '')::numeric, 1)
        * COALESCE(pi.quantity, 0)
      ), 0) AS revenue,
      2 AS source_order
    FROM item_unit_prices pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.sides) AS s
    GROUP BY COALESCE(NULLIF(s->>'name', ''), NULLIF(s->>'side_item_name', ''), 'Side')
  ),
  mod_agg AS (
    SELECT
      COALESCE(NULLIF(m->>'name', ''), 'Modifier')::TEXT AS name,
      'modifier'::TEXT AS source,
      COALESCE(SUM(COALESCE(pi.quantity, 0)), 0)::INT AS qty,
      COALESCE(SUM(COALESCE(NULLIF(m->>'price', '')::numeric, 0) * COALESCE(pi.quantity, 0)), 0) AS revenue,
      3 AS source_order
    FROM item_unit_prices pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.modifiers) AS m
    GROUP BY COALESCE(NULLIF(m->>'name', ''), 'Modifier')
  ),
  all_items AS (
    SELECT name, source, qty, revenue, source_order FROM main_agg
    UNION ALL
    SELECT name, source, qty, revenue, source_order FROM side_agg
    UNION ALL
    SELECT name, source, qty, revenue, source_order FROM mod_agg
  )
  SELECT
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'name', name,
        'source', source,
        'qty', qty,
        'revenue', revenue
      )
      ORDER BY source_order, qty DESC, name
    ), '[]'::jsonb),
    COALESCE(SUM(qty), 0)::INT
  INTO v_item_breakdown, v_total_item_quantity
  FROM all_items;

  v_payload := jsonb_build_object(
    'kind',                  'shift_close_report',
    'branch_name',           COALESCE(v_branch.name, ''),
    'branch_address',        COALESCE(v_branch.address, ''),
    'branch_phone',          COALESCE(v_branch.phone, ''),
    'branch_tax_code',       COALESCE(v_branch_tax, ''),
    'session_id',            p_session_id,
    'cashier_name',          COALESCE(v_cashier_name, ''),
    'opened_at',             to_char(v_session.opened_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                     'YYYY-MM-DD"T"HH24:MI:SS'),
    'closed_at',             to_char(v_session.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                     'YYYY-MM-DD"T"HH24:MI:SS'),
    'opening_cash',          v_session.opening_cash,
    'closing_cash',          v_session.closing_cash,
    'expected_cash',         v_session.expected_cash,
    'cash_difference',       v_session.cash_difference,
    'note',                  v_session.note,
    'variance_note',         v_session.variance_approval_note,
    'variance_approver',     v_approver_name,
    'paid_order_count',      (
      SELECT COUNT(*) FROM public.orders
       WHERE pos_session_id = p_session_id
         AND tenant_id = v_session.tenant_id
         AND payment_status = 'paid'
         AND status <> 'cancelled'
    ),
    'unpaid_order_count',    (
      SELECT COUNT(*) FROM public.orders
       WHERE pos_session_id = p_session_id
         AND tenant_id = v_session.tenant_id
         AND payment_status <> 'paid'
         AND status <> 'cancelled'
    ),
    'cancelled_order_count', (
      SELECT COUNT(*) FROM public.orders
       WHERE pos_session_id = p_session_id
         AND tenant_id = v_session.tenant_id
         AND status = 'cancelled'
    ),
    'payment_breakdown',     v_breakdown,
    'total_revenue',         v_total_revenue,
    'total_item_quantity',   COALESCE(v_total_item_quantity, 0),
    'item_breakdown',        COALESCE(v_item_breakdown, '[]'::jsonb),
    'printed_at',            to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                     'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'session:' || p_session_id::TEXT || ':shift_close';

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_session.tenant_id, v_session.branch_id, v_printer_id, 'shift_close_report',
    NULL, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET
    payload = EXCLUDED.payload,
    status  = CASE WHEN public.print_jobs.status IN ('failed', 'expired')
                   THEN 'pending' ELSE public.print_jobs.status END,
    last_error = NULL,
    claimed_by_agent = NULL,
    claimed_at = NULL
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'session_id', p_session_id,
    'job_id',     v_job_id,
    'printer_id', v_printer_id
  );
END;
$$;


ALTER FUNCTION "public"."enqueue_shift_close_print"("p_session_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_branch_inventory_location_defaults"("p_tenant_id" bigint, "p_branch_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_branch_kind TEXT;
  v_warehouse_id BIGINT;
  v_kitchen_id BIGINT;
  v_needs_default_receive BOOLEAN;
  v_needs_default_issue BOOLEAN;
BEGIN
  SELECT branch_kind
  INTO v_branch_kind
  FROM public.branches
  WHERE id = p_branch_id
    AND tenant_id = p_tenant_id;

  IF NOT FOUND OR v_branch_kind IS DISTINCT FROM 'branch' THEN
    RETURN;
  END IF;

  SELECT il.id
  INTO v_warehouse_id
  FROM public.inventory_locations il
  WHERE il.tenant_id = p_tenant_id
    AND il.branch_id = p_branch_id
    AND il.location_kind = 'warehouse'
    AND il.is_active = TRUE
  ORDER BY il.is_default_receive DESC, il.sort_order NULLS LAST, il.id
  LIMIT 1;

  v_needs_default_receive := NOT EXISTS (
    SELECT 1
    FROM public.inventory_locations il
    WHERE il.tenant_id = p_tenant_id
      AND il.branch_id = p_branch_id
      AND il.is_default_receive = TRUE
      AND il.is_active = TRUE
  );

  v_needs_default_issue := NOT EXISTS (
    SELECT 1
    FROM public.inventory_locations il
    WHERE il.tenant_id = p_tenant_id
      AND il.branch_id = p_branch_id
      AND il.is_default_issue = TRUE
      AND il.is_active = TRUE
  );

  IF v_warehouse_id IS NULL THEN
    INSERT INTO public.inventory_locations (
      tenant_id,
      branch_id,
      code,
      name,
      location_kind,
      is_active,
      is_default_receive,
      is_default_issue,
      is_default_consumption,
      sort_order
    )
    VALUES (
      p_tenant_id,
      p_branch_id,
      'main_warehouse',
      U&'Kho chi nh\00E1nh',
      'warehouse',
      TRUE,
      v_needs_default_receive,
      v_needs_default_issue,
      FALSE,
      0
    )
    ON CONFLICT (code, branch_id, tenant_id) DO UPDATE
    SET name = EXCLUDED.name,
        location_kind = 'warehouse',
        is_active = TRUE,
        is_default_receive = EXCLUDED.is_default_receive,
        is_default_issue = EXCLUDED.is_default_issue,
        is_default_consumption = FALSE,
        sort_order = EXCLUDED.sort_order,
        updated_at = now()
    RETURNING id INTO v_warehouse_id;
  ELSE
    IF v_needs_default_receive THEN
      UPDATE public.inventory_locations
      SET is_default_receive = TRUE,
          updated_at = now()
      WHERE id = v_warehouse_id;
    END IF;

    IF v_needs_default_issue THEN
      UPDATE public.inventory_locations
      SET is_default_issue = TRUE,
          updated_at = now()
      WHERE id = v_warehouse_id;
    END IF;
  END IF;

  SELECT il.id
  INTO v_kitchen_id
  FROM public.inventory_locations il
  WHERE il.tenant_id = p_tenant_id
    AND il.branch_id = p_branch_id
    AND il.location_kind = 'kitchen'
    AND il.is_active = TRUE
    AND il.is_default_consumption = TRUE
  ORDER BY il.sort_order NULLS LAST, il.id
  LIMIT 1;

  IF v_kitchen_id IS NOT NULL THEN
    RETURN;
  END IF;

  UPDATE public.inventory_locations
  SET is_default_consumption = FALSE,
      updated_at = now()
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND is_active = TRUE
    AND is_default_consumption = TRUE;

  SELECT il.id
  INTO v_kitchen_id
  FROM public.inventory_locations il
  WHERE il.tenant_id = p_tenant_id
    AND il.branch_id = p_branch_id
    AND il.location_kind = 'kitchen'
    AND il.is_active = TRUE
  ORDER BY il.sort_order NULLS LAST, il.id
  LIMIT 1;

  IF v_kitchen_id IS NOT NULL THEN
    UPDATE public.inventory_locations
    SET is_default_consumption = TRUE,
        updated_at = now()
    WHERE id = v_kitchen_id;
    RETURN;
  END IF;

  INSERT INTO public.inventory_locations (
    tenant_id,
    branch_id,
    code,
    name,
    location_kind,
    is_active,
    is_default_receive,
    is_default_issue,
    is_default_consumption,
    sort_order
  )
  VALUES (
    p_tenant_id,
    p_branch_id,
    'kitchen',
    U&'B\1EBFp',
    'kitchen',
    TRUE,
    FALSE,
    FALSE,
    TRUE,
    10
  )
  ON CONFLICT (code, branch_id, tenant_id) DO UPDATE
  SET name = EXCLUDED.name,
      location_kind = 'kitchen',
      is_active = TRUE,
      is_default_receive = FALSE,
      is_default_issue = FALSE,
      is_default_consumption = TRUE,
      sort_order = EXCLUDED.sort_order,
      updated_at = now();
END;
$$;


ALTER FUNCTION "public"."ensure_branch_inventory_location_defaults"("p_tenant_id" bigint, "p_branch_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_journal_write_permission"("p_branch_id" bigint DEFAULT NULL::bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor  UUID := auth.uid();
  v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant claim missing' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NOT NULL THEN
    PERFORM 1
    FROM public.branches b
    WHERE b.id = p_branch_id
      AND b.tenant_id = v_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'branch not found for tenant' USING ERRCODE = 'P0002';
    END IF;

    IF NOT public.has_permission(p_branch_id, 'finance:expense_approve') THEN
      RAISE EXCEPTION 'permission denied: finance:expense_approve required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.has_permission(NULL, 'finance:expense_approve') THEN
      RAISE EXCEPTION 'permission denied: finance:expense_approve required'
        USING ERRCODE = '42501';
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "public"."ensure_journal_write_permission"("p_branch_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."escalate_round_4"("p_session_id" bigint, "p_ingredient_id" bigint, "p_final_qty" numeric, "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_ss RECORD;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_ss FROM public.stocktake_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_ss.branch_id, 'inventory:stocktake_recount') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF length(COALESCE(p_note, '')) < 20 THEN RAISE EXCEPTION 'escalation note must be at least 20 characters' USING ERRCODE = '22023'; END IF;
  INSERT INTO public.stocktake_lines (tenant_id, session_id, ingredient_id, system_quantity,
    counted_quantity, counted_by, counted_at, round_no, variance_reason, is_final, needs_recount, abc_class)
  SELECT v_ss.tenant_id, p_session_id, p_ingredient_id,
    (SELECT system_quantity FROM public.stocktake_lines WHERE session_id=p_session_id AND ingredient_id=p_ingredient_id AND round_no=1),
    p_final_qty, v_uid, now(), 4, '[ROUND4] ' || p_note, true, false,
    (SELECT abc_class FROM public.stocktake_lines WHERE session_id=p_session_id AND ingredient_id=p_ingredient_id AND round_no=1)
  ON CONFLICT (session_id, ingredient_id, round_no) DO UPDATE SET
    counted_quantity = EXCLUDED.counted_quantity, counted_by = EXCLUDED.counted_by,
    counted_at = EXCLUDED.counted_at, variance_reason = EXCLUDED.variance_reason, is_final = true;
  UPDATE public.stocktake_lines SET counted_quantity = p_final_qty, is_final = true, needs_recount = false,
    variance_reason = COALESCE(variance_reason, '') || E'\n[ROUND4 escalated by ' || v_uid::TEXT || ']'
  WHERE session_id = p_session_id AND ingredient_id = p_ingredient_id AND round_no = 1;
END; $$;


ALTER FUNCTION "public"."escalate_round_4"("p_session_id" bigint, "p_ingredient_id" bigint, "p_final_qty" numeric, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_stuck_print_jobs"("p_stale_after_seconds" integer DEFAULT 300) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_revived INT;
BEGIN
  UPDATE public.print_jobs
     SET status           = 'pending',
         claimed_by_agent = NULL,
         claimed_at       = NULL,
         last_error       = COALESCE(last_error, '') ||
                            CASE WHEN COALESCE(last_error, '') = '' THEN '' ELSE E'\n' END ||
                            'reaped: stuck in processing >' ||
                            p_stale_after_seconds || 's at ' || now()::text
   WHERE status     = 'processing'
     AND claimed_at < (now() - make_interval(secs => p_stale_after_seconds));

  GET DIAGNOSTICS v_revived = ROW_COUNT;
  RETURN v_revived;
END;
$$;


ALTER FUNCTION "public"."expire_stuck_print_jobs"("p_stale_after_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extend_express_window"("p_branch_id" bigint, "p_minutes" integer, "p_note" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_tz TEXT; v_recent INT; v_until TIMESTAMPTZ; v_win RECORD;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:grn_express_extend') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF p_minutes IS NULL OR p_minutes <= 0 OR p_minutes > 60 THEN RAISE EXCEPTION 'minutes must be in (0, 60]' USING ERRCODE = '22023'; END IF;
  IF length(COALESCE(p_note, '')) < 10 THEN RAISE EXCEPTION 'note must be at least 10 characters' USING ERRCODE = '22023'; END IF;
  SELECT COUNT(*) INTO v_recent FROM public.grn_express_extend_audit WHERE user_id = v_uid AND created_at > now() - INTERVAL '7 days';
  IF v_recent >= 3 THEN RAISE EXCEPTION 'express-extend rate-limit (3/week) exceeded' USING ERRCODE = '54000'; END IF;
  SELECT timezone INTO v_tz FROM public.branches WHERE id = p_branch_id;
  IF v_tz IS NULL THEN v_tz := 'Asia/Ho_Chi_Minh'; END IF;
  SELECT enabled, start_time, end_time INTO v_win FROM public.branch_express_window WHERE branch_id = p_branch_id;
  IF NOT FOUND OR NOT v_win.enabled THEN RAISE EXCEPTION 'express window not enabled for branch %', p_branch_id USING ERRCODE = '22023'; END IF;
  v_until := (((now() AT TIME ZONE v_tz)::DATE + v_win.end_time) AT TIME ZONE v_tz) + make_interval(mins => p_minutes);
  INSERT INTO public.grn_express_extend_audit (tenant_id, branch_id, user_id, extended_until, extend_minutes, note)
  SELECT b.tenant_id, p_branch_id, v_uid, v_until, p_minutes, p_note FROM public.branches b WHERE b.id = p_branch_id;
  RETURN v_until;
END; $$;


ALTER FUNCTION "public"."extend_express_window"("p_branch_id" bigint, "p_minutes" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."feedback_retention_cleanup"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_phone_nulled INT;
  v_ip_nulled INT;
  v_text_deleted INT;
  v_outbox_deleted INT;
BEGIN
  UPDATE feedbacks
  SET phone = NULL
  WHERE phone IS NOT NULL
    AND created_at < NOW() - INTERVAL '6 months';
  GET DIAGNOSTICS v_phone_nulled = ROW_COUNT;

  UPDATE feedbacks
  SET submit_ip_hash = NULL
  WHERE submit_ip_hash IS NOT NULL
    AND created_at < NOW() - INTERVAL '3 months';
  GET DIAGNOSTICS v_ip_nulled = ROW_COUNT;

  DELETE FROM feedbacks
  WHERE created_at < NOW() - INTERVAL '24 months';
  GET DIAGNOSTICS v_text_deleted = ROW_COUNT;

  DELETE FROM telegram_outbox
  WHERE status = 'sent'
    AND sent_at < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS v_outbox_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'phone_nulled', v_phone_nulled,
    'ip_nulled', v_ip_nulled,
    'text_deleted', v_text_deleted,
    'outbox_deleted', v_outbox_deleted
  );
END;
$$;


ALTER FUNCTION "public"."feedback_retention_cleanup"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."feedback_validate_categories"("p_cats" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  valid_cats CONSTANT TEXT[] := ARRAY[
    'food.quality.cold',
    'food.quality.raw',
    'food.quality.spoiled',
    'food.quality.taste',
    'food.quality.portion',
    'service.slow',
    'service.attitude',
    'service.wrong_order',
    'service.missing_item',
    'hygiene.dirty_table',
    'hygiene.bug',
    'hygiene.smell',
    'hygiene.toilet',
    'pricing.overcharged',
    'pricing.unclear',
    'ambience.noise',
    'ambience.crowded',
    'ambience.aircon',
    'ambience.parking',
    'praise.food',
    'praise.service',
    'praise.value',
    'suggestion.menu',
    'suggestion.facility',
    'other'
  ];
  v_cat TEXT;
BEGIN
  IF p_cats IS NULL THEN
    RETURN TRUE;
  END IF;
  FOREACH v_cat IN ARRAY p_cats LOOP
    IF NOT (v_cat = ANY(valid_cats)) THEN
      RETURN FALSE;
    END IF;
  END LOOP;
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."feedback_validate_categories"("p_cats" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."feedback_validate_categories"("p_cats" "text"[]) IS 'Returns TRUE iff every element is a member of the fixed feedback category taxonomy. Used in feedbacks.ai_categories CHECK constraint.';



CREATE OR REPLACE FUNCTION "public"."finalize_paid_order"("p_order_id" bigint, "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_order  RECORD;
  v_actor  UUID := COALESCE(p_actor_id, auth.uid());
BEGIN
  SELECT o.id, o.tenant_id, o.status
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RETURN;
  END IF;

  UPDATE public.orders
  SET status     = 'completed',
      updated_at = now()
  WHERE id = p_order_id;

  IF v_actor IS NOT NULL THEN
    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    )
    VALUES (
      v_order.tenant_id,
      p_order_id,
      v_order.status,
      'completed',
      v_actor,
      'auto_complete_on_payment'
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."finalize_paid_order"("p_order_id" bigint, "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_paid_order"("p_order_id" bigint, "p_actor_id" "uuid") IS 'Helper: marks order as completed after payment confirmed. Idempotent. Does NOT force order_items/kds_tickets — chef continues via KDS flow even after order completed (pay-first-cook-after is a valid F&B case). Table release fires via trg_release_table_on_order_status trigger.';



CREATE OR REPLACE FUNCTION "public"."finalize_stocktake"("p_session_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_ss RECORD; v_pending INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_ss FROM public.stocktake_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_ss.branch_id, 'inventory:stocktake_complete') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF v_ss.status <> 'in_progress' THEN RAISE EXCEPTION 'session not in_progress' USING ERRCODE = '22023'; END IF;
  SELECT COUNT(*) INTO v_pending FROM public.stocktake_lines WHERE session_id = p_session_id AND round_no = 1 AND is_final = false;
  IF v_pending > 0 THEN RAISE EXCEPTION 'cannot finalize: % round-1 line(s) still not final', v_pending USING ERRCODE = '22023'; END IF;
  UPDATE public.stocktake_sessions SET status = 'completed', completed_at = now() WHERE id = p_session_id;
  RETURN jsonb_build_object('session_id', p_session_id, 'status', 'completed', 'completed_at', now());
END; $$;


ALTER FUNCTION "public"."finalize_stocktake"("p_session_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finance_views_last_refresh"() RETURNS TABLE("last_run" timestamp with time zone, "status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'permission denied: finance:view required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT d.end_time, d.status
  FROM cron.job_run_details d
  JOIN cron.job j ON j.jobid = d.jobid
  WHERE j.jobname = 'refresh-finance-views-daily'
  ORDER BY d.start_time DESC
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."finance_views_last_refresh"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_payment_order_desync"("p_since" timestamp with time zone DEFAULT ("now"() - '30 days'::interval)) RETURNS TABLE("payment_id" bigint, "order_id" bigint, "tenant_id" bigint, "branch_id" bigint, "amount" numeric, "payment_method" "text", "payment_status" "text", "payment_paid_at" timestamp with time zone, "order_status" "text", "order_payment_status" "text", "order_created_at" timestamp with time zone, "age_minutes" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    p.id                                     AS payment_id,
    p.order_id                               AS order_id,
    p.tenant_id                              AS tenant_id,
    p.branch_id                              AS branch_id,
    p.amount                                 AS amount,
    p.method                                 AS payment_method,
    p.status                                 AS payment_status,
    p.paid_at                                AS payment_paid_at,
    o.status                                 AS order_status,
    o.payment_status                         AS order_payment_status,
    o.created_at                             AS order_created_at,
    GREATEST(
      EXTRACT(EPOCH FROM (now() - p.paid_at))::INTEGER / 60,
      0
    )                                        AS age_minutes
  FROM public.payments p
  JOIN public.orders   o ON o.id = p.order_id AND o.tenant_id = p.tenant_id
  WHERE p.tenant_id = public.auth_tenant_id()
    AND p.status = 'completed'
    AND COALESCE(o.payment_status, 'unpaid') <> 'paid'
    AND p.paid_at >= p_since
    AND public.has_permission_any('finance:view')
  ORDER BY p.paid_at DESC;
$$;


ALTER FUNCTION "public"."find_payment_order_desync"("p_since" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_payment_order_desync"("p_since" timestamp with time zone) IS 'Ops reconciliation: rows are payments marked completed whose order did not flip to paid. Returns empty for callers without finance:view. Lookback window defaults to 30 days.';



CREATE OR REPLACE FUNCTION "public"."fn_eval_account_expr"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_expr" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_op   TEXT;
  v_acc  TEXT;
  v_sum  NUMERIC(15,2) := 0;
  v_arg  JSONB;
  v_val  NUMERIC(15,2);
BEGIN
  IF p_tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_required' USING ERRCODE = '22023';
  END IF;
  IF auth.uid() IS NOT NULL AND p_tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  v_op := p_expr ->> 'op';

  IF v_op IN ('balance', 'debit_balance', 'credit_balance', 'period_credit', 'period_debit') THEN
    v_acc := p_expr ->> 'account';
    IF v_acc IS NULL OR v_acc !~ '^[0-9]{3,8}$' THEN
      RAISE EXCEPTION 'invalid_account_code: %', COALESCE(v_acc, '<null>')
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_op = 'balance' THEN
    SELECT COALESCE(SUM(jel.debit_amount - jel.credit_amount), 0)
    INTO v_sum
    FROM public.journal_entry_lines jel
    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE je.tenant_id = p_tenant_id
      AND je.status = 'posted'
      AND je.entry_date <= p_end_date
      AND (p_start_date IS NULL OR je.entry_date >= p_start_date)
      AND coa.account_code LIKE v_acc || '%';
    RETURN v_sum;
  ELSIF v_op = 'debit_balance' THEN
    SELECT COALESCE(SUM(jel.debit_amount - jel.credit_amount), 0)
    INTO v_sum
    FROM public.journal_entry_lines jel
    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE je.tenant_id = p_tenant_id
      AND je.status = 'posted'
      AND je.entry_date <= p_end_date
      AND (p_start_date IS NULL OR je.entry_date >= p_start_date)
      AND coa.account_code LIKE v_acc || '%';
    RETURN GREATEST(v_sum, 0);
  ELSIF v_op = 'credit_balance' THEN
    SELECT COALESCE(SUM(jel.credit_amount - jel.debit_amount), 0)
    INTO v_sum
    FROM public.journal_entry_lines jel
    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE je.tenant_id = p_tenant_id
      AND je.status = 'posted'
      AND je.entry_date <= p_end_date
      AND (p_start_date IS NULL OR je.entry_date >= p_start_date)
      AND coa.account_code LIKE v_acc || '%';
    RETURN GREATEST(v_sum, 0);
  ELSIF v_op = 'period_credit' THEN
    IF p_start_date IS NULL THEN RETURN 0; END IF;
    SELECT COALESCE(SUM(jel.credit_amount), 0)
    INTO v_sum
    FROM public.journal_entry_lines jel
    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE je.tenant_id = p_tenant_id
      AND je.status = 'posted'
      AND je.entry_date >= p_start_date
      AND je.entry_date <= p_end_date
      AND coa.account_code LIKE v_acc || '%';
    RETURN v_sum;
  ELSIF v_op = 'period_debit' THEN
    IF p_start_date IS NULL THEN RETURN 0; END IF;
    SELECT COALESCE(SUM(jel.debit_amount), 0)
    INTO v_sum
    FROM public.journal_entry_lines jel
    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE je.tenant_id = p_tenant_id
      AND je.status = 'posted'
      AND je.entry_date >= p_start_date
      AND je.entry_date <= p_end_date
      AND coa.account_code LIKE v_acc || '%';
    RETURN v_sum;
  ELSIF v_op = 'sum' THEN
    FOR v_arg IN SELECT * FROM jsonb_array_elements(p_expr -> 'args') LOOP
      v_sum := v_sum + public.fn_eval_account_expr(p_tenant_id, p_start_date, p_end_date, v_arg);
    END LOOP;
    RETURN v_sum;
  ELSIF v_op = 'negate' THEN
    RETURN -1 * public.fn_eval_account_expr(p_tenant_id, p_start_date, p_end_date, p_expr -> 'arg');
  ELSIF v_op = 'max_zero' THEN
    v_val := public.fn_eval_account_expr(p_tenant_id, p_start_date, p_end_date, p_expr -> 'arg');
    RETURN GREATEST(v_val, 0);
  ELSIF v_op = 'literal' THEN
    RETURN COALESCE((p_expr ->> 'value')::NUMERIC(15,2), 0);
  ELSE
    RAISE EXCEPTION 'unknown_dsl_op: %', v_op USING ERRCODE = '22023';
  END IF;
END;
$_$;


ALTER FUNCTION "public"."fn_eval_account_expr"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_expr" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generate_b01_dn"("p_tenant_id" bigint, "p_as_of_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lines    JSONB := '[]'::JSONB;
  v_row      RECORD;
  v_amount   NUMERIC(15,2);
  v_period   RECORD;
  v_status   TEXT := 'draft';
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT fp.status INTO v_period
  FROM public.fiscal_periods fp
  WHERE fp.tenant_id = p_tenant_id
    AND fp.period_year = EXTRACT(YEAR FROM p_as_of_date)::INT
    AND fp.period_month = EXTRACT(MONTH FROM p_as_of_date)::INT;
  IF FOUND AND v_period.status = 'closed' THEN
    v_status := 'final';
  END IF;

  FOR v_row IN
    SELECT line_code, line_label_vi, parent_line, level, formula, display_order, is_total
    FROM public.vas_report_lines
    WHERE form_code = 'B01-DN'
      AND tenant_id IS NULL
    ORDER BY display_order
  LOOP
    v_amount := public.fn_eval_account_expr(p_tenant_id, NULL, p_as_of_date, v_row.formula);

    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'line_code',  v_row.line_code,
      'line_label', v_row.line_label_vi,
      'parent',     v_row.parent_line,
      'level',      v_row.level,
      'amount',     v_amount,
      'is_total',   v_row.is_total
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'form', 'B01-DN',
    'tenant_id', p_tenant_id,
    'as_of_date', p_as_of_date,
    'status', v_status,
    'generated_at', now(),
    'lines', v_lines
  );
END;
$$;


ALTER FUNCTION "public"."fn_generate_b01_dn"("p_tenant_id" bigint, "p_as_of_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generate_b02_dn"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lines  JSONB := '[]'::JSONB;
  v_row    RECORD;
  v_amount NUMERIC(15,2);
  v_status TEXT := 'draft';
  v_open_count INT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_open_count
  FROM generate_series(
    date_trunc('month', p_start_date)::DATE,
    date_trunc('month', p_end_date)::DATE,
    INTERVAL '1 month'
  ) AS m
  LEFT JOIN public.fiscal_periods fp
    ON fp.tenant_id = p_tenant_id
   AND fp.period_year = EXTRACT(YEAR FROM m)::INT
   AND fp.period_month = EXTRACT(MONTH FROM m)::INT
  WHERE COALESCE(fp.status, 'open') <> 'closed';
  IF v_open_count = 0 THEN
    v_status := 'final';
  END IF;

  FOR v_row IN
    SELECT line_code, line_label_vi, parent_line, level, formula, display_order, is_total
    FROM public.vas_report_lines
    WHERE form_code = 'B02-DN'
      AND tenant_id IS NULL
    ORDER BY display_order
  LOOP
    v_amount := public.fn_eval_account_expr(p_tenant_id, p_start_date, p_end_date, v_row.formula);

    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'line_code',  v_row.line_code,
      'line_label', v_row.line_label_vi,
      'parent',     v_row.parent_line,
      'level',      v_row.level,
      'amount',     v_amount,
      'is_total',   v_row.is_total
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'form', 'B02-DN',
    'tenant_id', p_tenant_id,
    'start_date', p_start_date,
    'end_date', p_end_date,
    'status', v_status,
    'generated_at', now(),
    'lines', v_lines
  );
END;
$$;


ALTER FUNCTION "public"."fn_generate_b02_dn"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generate_b03_dn"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lines  JSONB := '[]'::JSONB;
  v_row    RECORD;
  v_amount NUMERIC(15,2);
  v_status TEXT := 'draft';
  v_open_count INT;
  -- Per-line buckets to support derived subtotals
  v_t01 NUMERIC(15,2) := 0;
  v_t02 NUMERIC(15,2) := 0;
  v_t09 NUMERIC(15,2) := 0;
  v_t10 NUMERIC(15,2) := 0;
  v_t11 NUMERIC(15,2) := 0;
  v_t20 NUMERIC(15,2) := 0;
  v_t21 NUMERIC(15,2) := 0;
  v_t22 NUMERIC(15,2) := 0;
  v_t30 NUMERIC(15,2) := 0;
  v_t31 NUMERIC(15,2) := 0;
  v_t34 NUMERIC(15,2) := 0;
  v_t40 NUMERIC(15,2) := 0;
  v_t50 NUMERIC(15,2) := 0;
  v_t60 NUMERIC(15,2) := 0;
  v_t70 NUMERIC(15,2) := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;

  -- 'final' only if every month spanned is closed (mirror B02-DN)
  SELECT COUNT(*) INTO v_open_count
  FROM generate_series(
    date_trunc('month', p_start_date)::DATE,
    date_trunc('month', p_end_date)::DATE,
    INTERVAL '1 month'
  ) AS m
  LEFT JOIN public.fiscal_periods fp
    ON fp.tenant_id = p_tenant_id
   AND fp.period_year = EXTRACT(YEAR FROM m)::INT
   AND fp.period_month = EXTRACT(MONTH FROM m)::INT
  WHERE COALESCE(fp.status, 'open') <> 'closed';
  IF v_open_count = 0 THEN
    v_status := 'final';
  END IF;

  -- Iterate lines in display_order. Subtotals (20, 30, 40, 50) and
  -- opening cash (60) are computed from buckets; everything else
  -- evaluates through the DSL.
  FOR v_row IN
    SELECT line_code, line_label_vi, parent_line, level, formula, display_order, is_total
    FROM public.vas_report_lines
    WHERE form_code = 'B03-DN'
      AND tenant_id IS NULL
    ORDER BY display_order
  LOOP
    IF v_row.line_code = '20' THEN
      v_amount := v_t01 + v_t02 + v_t09 + v_t10 + v_t11;
      v_t20 := v_amount;
    ELSIF v_row.line_code = '30' THEN
      v_amount := v_t21 + v_t22;
      v_t30 := v_amount;
    ELSIF v_row.line_code = '40' THEN
      v_amount := v_t31 + v_t34;
      v_t40 := v_amount;
    ELSIF v_row.line_code = '50' THEN
      v_amount := v_t20 + v_t30 + v_t40;
      v_t50 := v_amount;
    ELSIF v_row.line_code = '60' THEN
      -- Opening cash = balance(111+112) up to (start_date - 1)
      v_amount := public.fn_eval_account_expr(
        p_tenant_id,
        NULL,
        (p_start_date - INTERVAL '1 day')::DATE,
        '{"op":"sum","args":[
           {"op":"debit_balance","account":"111"},
           {"op":"debit_balance","account":"112"}
         ]}'::JSONB
      );
      v_t60 := v_amount;
    ELSE
      v_amount := public.fn_eval_account_expr(
        p_tenant_id,
        p_start_date,
        p_end_date,
        v_row.formula
      );
      -- Capture into bucket vars for subtotal computation
      IF v_row.line_code = '01' THEN v_t01 := v_amount;
      ELSIF v_row.line_code = '02' THEN v_t02 := v_amount;
      ELSIF v_row.line_code = '09' THEN v_t09 := v_amount;
      ELSIF v_row.line_code = '10' THEN v_t10 := v_amount;
      ELSIF v_row.line_code = '11' THEN v_t11 := v_amount;
      ELSIF v_row.line_code = '21' THEN v_t21 := v_amount;
      ELSIF v_row.line_code = '22' THEN v_t22 := v_amount;
      ELSIF v_row.line_code = '31' THEN v_t31 := v_amount;
      ELSIF v_row.line_code = '34' THEN v_t34 := v_amount;
      ELSIF v_row.line_code = '70' THEN v_t70 := v_amount;
      END IF;
    END IF;

    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'line_code',  v_row.line_code,
      'line_label', v_row.line_label_vi,
      'parent',     v_row.parent_line,
      'level',      v_row.level,
      'amount',     v_amount,
      'is_total',   v_row.is_total
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'form', 'B03-DN',
    'tenant_id', p_tenant_id,
    'start_date', p_start_date,
    'end_date', p_end_date,
    'status', v_status,
    'generated_at', now(),
    'lines', v_lines,
    'consistency_check', jsonb_build_object(
      'opening_cash', v_t60,
      'closing_cash', v_t70,
      'closing_minus_opening', v_t70 - v_t60,
      'net_cashflow', v_t50,
      'difference', (v_t70 - v_t60) - v_t50,
      'consistent', ABS((v_t70 - v_t60) - v_t50) < 1
    )
  );
END;
$$;


ALTER FUNCTION "public"."fn_generate_b03_dn"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_generate_b03_dn"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date") IS 'TT200 B03-DN Báo cáo lưu chuyển tiền tệ (indirect method). Returns lines + consistency_check (closing_minus_opening should equal net_cashflow). Subtotals 20/30/40/50 and opening cash 60 computed in wrapper; other lines via fn_eval_account_expr DSL.';



CREATE OR REPLACE FUNCTION "public"."fn_generate_form_01_gtgt"("p_tenant_id" bigint, "p_year" integer, "p_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lines  JSONB := '[]'::JSONB;
  v_row    RECORD;
  v_amount NUMERIC(15,2);
  v_start  DATE;
  v_end    DATE;
  v_status TEXT := 'draft';
  v_period RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  v_start := make_date(p_year, p_month, 1);
  v_end   := (v_start + INTERVAL '1 month' - INTERVAL '1 day')::DATE;

  SELECT fp.status INTO v_period
  FROM public.fiscal_periods fp
  WHERE fp.tenant_id = p_tenant_id
    AND fp.period_year = p_year
    AND fp.period_month = p_month;
  IF FOUND AND v_period.status = 'closed' THEN
    v_status := 'final';
  END IF;

  FOR v_row IN
    SELECT line_code, line_label_vi, parent_line, level, formula, display_order, is_total
    FROM public.vas_report_lines
    WHERE form_code = '01-GTGT'
      AND tenant_id IS NULL
    ORDER BY display_order
  LOOP
    v_amount := public.fn_eval_account_expr(p_tenant_id, v_start, v_end, v_row.formula);

    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'line_code',  v_row.line_code,
      'line_label', v_row.line_label_vi,
      'parent',     v_row.parent_line,
      'level',      v_row.level,
      'amount',     v_amount,
      'is_total',   v_row.is_total
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'form', '01-GTGT',
    'tenant_id', p_tenant_id,
    'year', p_year,
    'month', p_month,
    'status', v_status,
    'generated_at', now(),
    'lines', v_lines
  );
END;
$$;


ALTER FUNCTION "public"."fn_generate_form_01_gtgt"("p_tenant_id" bigint, "p_year" integer, "p_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reconcile_drilldown"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_category" "text", "p_side" "text", "p_branch_id" bigint DEFAULT NULL::bigint, "p_limit" integer DEFAULT 200) RETURNS TABLE("ref_id" bigint, "ref_label" "text", "ref_date" timestamp with time zone, "branch_id" bigint, "amount" numeric, "description" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_entry_ids BIGINT[];
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission_any('finance:view') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501'; END IF;
  IF p_side NOT IN ('subledger','gl') THEN RAISE EXCEPTION 'invalid_side' USING ERRCODE = '22023'; END IF;
  IF p_category NOT IN ('sales','cogs','inventory_in','payroll','ap_payment') THEN RAISE EXCEPTION 'invalid_category' USING ERRCODE = '22023'; END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 1000 THEN p_limit := 200; END IF;

  IF p_side = 'gl' THEN
    SELECT ARRAY_AGG(je.id) INTO v_entry_ids
      FROM public.journal_entries je
     WHERE je.tenant_id = p_tenant_id AND je.status = 'posted'
       AND je.entry_date >= p_start_date AND je.entry_date < (p_end_date + INTERVAL '1 day')
       AND (p_branch_id IS NULL OR je.branch_id = p_branch_id);
    IF v_entry_ids IS NULL THEN RETURN; END IF;
    RETURN QUERY
    SELECT je.id, je.entry_number, je.entry_date::TIMESTAMPTZ, je.branch_id,
      CASE WHEN p_category IN ('sales') THEN jel.credit_amount
           WHEN p_category IN ('cogs','inventory_in','payroll','ap_payment') THEN jel.debit_amount
           ELSE 0 END,
      COALESCE(jel.description, je.description)
    FROM public.journal_entry_lines jel
    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE jel.tenant_id = p_tenant_id AND jel.journal_entry_id = ANY(v_entry_ids)
      AND (
        (p_category = 'sales'        AND coa.account_code IN ('511','33311') AND je.reference_type = 'sale') OR
        (p_category = 'cogs'         AND coa.account_code = '621'             AND je.reference_type = 'sale') OR
        (p_category = 'inventory_in' AND coa.account_code = '152'             AND je.reference_type = 'purchase') OR
        (p_category = 'payroll'      AND coa.account_code = '622'             AND je.reference_type = 'payroll') OR
        (p_category = 'ap_payment'   AND coa.account_code = '331'             AND je.reference_type = 'purchase')
      )
    ORDER BY je.entry_date DESC, je.id DESC LIMIT p_limit;
    RETURN;
  END IF;

  IF p_category = 'sales' THEN
    RETURN QUERY
    SELECT p.id, ('PAY#' || p.id::TEXT), p.paid_at, p.branch_id, p.amount,
      ('Method: ' || COALESCE(p.method, '?'))
    FROM public.payments p
    WHERE p.tenant_id = p_tenant_id AND p.status = 'completed'
      AND p.paid_at >= p_start_date AND p.paid_at < (p_end_date + INTERVAL '1 day')
      AND (p_branch_id IS NULL OR p.branch_id = p_branch_id)
    ORDER BY p.paid_at DESC LIMIT p_limit;
  ELSIF p_category = 'cogs' THEN
    RETURN QUERY
    SELECT sm.id, ('SM#' || sm.id::TEXT), sm.created_at, sm.branch_id,
      (ABS(sm.quantity_change) * sm.unit_cost), sm.type::TEXT
    FROM public.stock_movements sm
    WHERE sm.tenant_id = p_tenant_id AND sm.type = 'consumption'
      AND sm.created_at >= p_start_date AND sm.created_at < (p_end_date + INTERVAL '1 day')
      AND (p_branch_id IS NULL OR sm.branch_id = p_branch_id)
    ORDER BY sm.created_at DESC LIMIT p_limit;
  ELSIF p_category = 'inventory_in' THEN
    RETURN QUERY
    SELECT sm.id, ('GRN-SM#' || sm.id::TEXT), sm.created_at, sm.branch_id,
      (sm.quantity_change * sm.unit_cost), sm.type::TEXT
    FROM public.stock_movements sm
    WHERE sm.tenant_id = p_tenant_id AND sm.type = 'grn_receipt'
      AND sm.created_at >= p_start_date AND sm.created_at < (p_end_date + INTERVAL '1 day')
      AND (p_branch_id IS NULL OR sm.branch_id = p_branch_id)
    ORDER BY sm.created_at DESC LIMIT p_limit;
  ELSIF p_category = 'payroll' THEN
    RETURN QUERY
    SELECT pe.id,
      ('Lương ' || pp.period_year || '-' || lpad(pp.period_month::TEXT, 2, '0')),
      (make_date(pp.period_year, pp.period_month, 1))::TIMESTAMPTZ,
      NULL::BIGINT, pe.gross_total, pp.status
    FROM public.payroll_entries pe
    JOIN public.payroll_periods pp ON pp.id = pe.payroll_period_id
    WHERE pe.tenant_id = p_tenant_id
      AND make_date(pp.period_year, pp.period_month, 1) >= date_trunc('month', p_start_date)::DATE
      AND make_date(pp.period_year, pp.period_month, 1) <= date_trunc('month', p_end_date)::DATE
      AND pp.status IN ('approved','paid')
    ORDER BY pp.period_year DESC, pp.period_month DESC, pe.id DESC LIMIT p_limit;
  ELSIF p_category = 'ap_payment' THEN
    RETURN QUERY
    SELECT sp.id, ('SP#' || sp.id::TEXT), sp.payment_date::TIMESTAMPTZ, NULL::BIGINT, sp.amount,
      ('NCC ' || COALESCE(s.name, '#' || si.supplier_id::TEXT)
        || ' / HĐ ' || COALESCE(si.invoice_number, si.id::TEXT))
    FROM public.supplier_payments sp
    JOIN public.supplier_invoices si ON si.id = sp.supplier_invoice_id
    LEFT JOIN public.suppliers      s ON s.id  = si.supplier_id
    WHERE sp.tenant_id = p_tenant_id
      AND sp.payment_date >= p_start_date
      AND sp.payment_date < (p_end_date + INTERVAL '1 day')
    ORDER BY sp.payment_date DESC LIMIT p_limit;
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_reconcile_drilldown"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_category" "text", "p_side" "text", "p_branch_id" bigint, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reconcile_period"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_branch_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result     JSONB := '[]'::JSONB;
  v_sub_total  NUMERIC(15,2);
  v_gl_total   NUMERIC(15,2);
  v_entry_ids  BIGINT[];
  v_branch_active BOOLEAN := p_branch_id IS NOT NULL;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;
  IF (p_end_date - p_start_date) > 366 THEN
    RAISE EXCEPTION 'date_range_too_large' USING ERRCODE = '22023';
  END IF;

  SELECT ARRAY_AGG(je.id)
  INTO v_entry_ids
  FROM public.journal_entries je
  WHERE je.tenant_id = p_tenant_id
    AND je.status = 'posted'
    AND je.entry_date >= p_start_date
    AND je.entry_date < (p_end_date + INTERVAL '1 day')
    AND (p_branch_id IS NULL OR je.branch_id = p_branch_id);

  IF v_entry_ids IS NULL THEN
    v_entry_ids := ARRAY[]::BIGINT[];
  END IF;

  SELECT COALESCE(SUM(p.amount), 0) INTO v_sub_total
  FROM public.payments p
  WHERE p.tenant_id = p_tenant_id
    AND p.status = 'completed'
    AND p.paid_at >= p_start_date
    AND p.paid_at < (p_end_date + INTERVAL '1 day')
    AND (p_branch_id IS NULL OR p.branch_id = p_branch_id);

  SELECT COALESCE(SUM(jel.credit_amount), 0) INTO v_gl_total
  FROM public.journal_entry_lines jel
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  WHERE jel.tenant_id = p_tenant_id
    AND jel.journal_entry_id = ANY(v_entry_ids)
    AND coa.account_code IN ('511', '33311')
    AND je.reference_type = 'sale';

  v_result := v_result || jsonb_build_array(jsonb_build_object(
    'category', 'sales',
    'label', 'Doanh thu + VAT (511+33311)',
    'subledger_total', v_sub_total,
    'gl_total', v_gl_total,
    'difference', v_sub_total - v_gl_total,
    'branch_scoped', true
  ));

  SELECT COALESCE(SUM(ABS(sm.quantity_change) * sm.unit_cost), 0) INTO v_sub_total
  FROM public.stock_movements sm
  WHERE sm.tenant_id = p_tenant_id
    AND sm.type = 'consumption'
    AND sm.created_at >= p_start_date
    AND sm.created_at < (p_end_date + INTERVAL '1 day')
    AND (p_branch_id IS NULL OR sm.branch_id = p_branch_id);

  SELECT COALESCE(SUM(jel.debit_amount), 0) INTO v_gl_total
  FROM public.journal_entry_lines jel
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  WHERE jel.tenant_id = p_tenant_id
    AND jel.journal_entry_id = ANY(v_entry_ids)
    AND coa.account_code = '621'
    AND je.reference_type = 'sale';

  v_result := v_result || jsonb_build_array(jsonb_build_object(
    'category', 'cogs',
    'label', 'Giá vốn bán hàng (621-sale)',
    'subledger_total', v_sub_total,
    'gl_total', v_gl_total,
    'difference', v_sub_total - v_gl_total,
    'branch_scoped', true
  ));

  SELECT COALESCE(SUM(sm.quantity_change * sm.unit_cost), 0) INTO v_sub_total
  FROM public.stock_movements sm
  WHERE sm.tenant_id = p_tenant_id
    AND sm.type = 'grn_receipt'
    AND sm.created_at >= p_start_date
    AND sm.created_at < (p_end_date + INTERVAL '1 day')
    AND (p_branch_id IS NULL OR sm.branch_id = p_branch_id);

  SELECT COALESCE(SUM(jel.debit_amount), 0) INTO v_gl_total
  FROM public.journal_entry_lines jel
  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
  JOIN public.journal_entries je ON je.id = jel.journal_entry_id
  WHERE jel.tenant_id = p_tenant_id
    AND jel.journal_entry_id = ANY(v_entry_ids)
    AND coa.account_code = '152'
    AND je.reference_type = 'purchase';

  v_result := v_result || jsonb_build_array(jsonb_build_object(
    'category', 'inventory_in',
    'label', 'Nhập kho NVL (152-purchase)',
    'subledger_total', v_sub_total,
    'gl_total', v_gl_total,
    'difference', v_sub_total - v_gl_total,
    'branch_scoped', true
  ));

  IF v_branch_active THEN
    v_sub_total := NULL;
    v_gl_total  := NULL;
  ELSE
    SELECT COALESCE(SUM(pe.gross_total), 0) INTO v_sub_total
    FROM public.payroll_entries pe
    JOIN public.payroll_periods pp ON pp.id = pe.payroll_period_id
    WHERE pe.tenant_id = p_tenant_id
      AND make_date(pp.period_year, pp.period_month, 1) >= date_trunc('month', p_start_date)::DATE
      AND make_date(pp.period_year, pp.period_month, 1) <= date_trunc('month', p_end_date)::DATE
      AND pp.status IN ('approved', 'paid');

    SELECT COALESCE(SUM(jel.debit_amount), 0) INTO v_gl_total
    FROM public.journal_entry_lines jel
    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE jel.tenant_id = p_tenant_id
      AND jel.journal_entry_id = ANY(v_entry_ids)
      AND coa.account_code = '622'
      AND je.reference_type = 'payroll';
  END IF;

  v_result := v_result || jsonb_build_array(jsonb_build_object(
    'category', 'payroll',
    'label', 'Lương nhân công (622)',
    'subledger_total', v_sub_total,
    'gl_total', v_gl_total,
    'difference', CASE
      WHEN v_sub_total IS NULL OR v_gl_total IS NULL THEN NULL
      ELSE v_sub_total - v_gl_total
    END,
    'branch_scoped', false
  ));

  IF v_branch_active THEN
    v_sub_total := NULL;
    v_gl_total  := NULL;
  ELSE
    SELECT COALESCE(SUM(sp.amount), 0) INTO v_sub_total
    FROM public.supplier_payments sp
    WHERE sp.tenant_id = p_tenant_id
      AND sp.payment_date >= p_start_date
      AND sp.payment_date < (p_end_date + INTERVAL '1 day');

    SELECT COALESCE(SUM(jel.debit_amount), 0) INTO v_gl_total
    FROM public.journal_entry_lines jel
    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id
    JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE jel.tenant_id = p_tenant_id
      AND jel.journal_entry_id = ANY(v_entry_ids)
      AND coa.account_code = '331'
      AND je.reference_type = 'purchase';
  END IF;

  v_result := v_result || jsonb_build_array(jsonb_build_object(
    'category', 'ap_payment',
    'label', 'Thanh toán NCC (331-purchase)',
    'subledger_total', v_sub_total,
    'gl_total', v_gl_total,
    'difference', CASE
      WHEN v_sub_total IS NULL OR v_gl_total IS NULL THEN NULL
      ELSE v_sub_total - v_gl_total
    END,
    'branch_scoped', false
  ));

  RETURN jsonb_build_object(
    'tenant_id', p_tenant_id,
    'branch_id', p_branch_id,
    'start_date', p_start_date,
    'end_date', p_end_date,
    'generated_at', now(),
    'categories', v_result
  );
END;
$$;


ALTER FUNCTION "public"."fn_reconcile_period"("p_tenant_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_branch_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reconcile_sales_by_day"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("date" "date", "revenue_paid" numeric, "gl_credit" numeric, "diff" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID;
  v_tenant BIGINT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NOT NULL THEN
    IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.has_permission_any('finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH pos_by_day AS (
    SELECT
      (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AS day,
      COALESCE(SUM(p.amount), 0) AS revenue_paid
    FROM public.payments p
    JOIN public.orders o
      ON o.id        = p.order_id
     AND o.tenant_id = p.tenant_id
    WHERE p.tenant_id = v_tenant
      AND p.status = 'completed'
      AND p.paid_at IS NOT NULL
      AND (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date >= p_start_date
      AND (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date <= p_end_date
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (
        (p_branch_id IS NOT NULL AND p.branch_id = p_branch_id)
        OR (p_branch_id IS NULL AND public.has_permission(p.branch_id, 'finance:view'))
      )
    GROUP BY 1
  ),
  gl_by_day AS (
    SELECT
      (je.entry_date AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AS day,
      COALESCE(SUM(jel.credit_amount), 0) AS gl_credit
    FROM public.journal_entry_lines jel
    JOIN public.journal_entries je
      ON je.id = jel.journal_entry_id
     AND je.tenant_id = jel.tenant_id
    JOIN public.chart_of_accounts coa
      ON coa.id = jel.account_id
    WHERE jel.tenant_id = v_tenant
      AND coa.account_code IN ('511', '33311')
      AND je.reference_type = 'sale'
      AND je.status = 'posted'
      AND (je.entry_date AT TIME ZONE 'Asia/Ho_Chi_Minh')::date >= p_start_date
      AND (je.entry_date AT TIME ZONE 'Asia/Ho_Chi_Minh')::date <= p_end_date
      AND (
        (p_branch_id IS NOT NULL AND je.branch_id = p_branch_id)
        OR (p_branch_id IS NULL
            AND je.branch_id IS NOT NULL
            AND public.has_permission(je.branch_id, 'finance:view'))
      )
    GROUP BY 1
  )
  SELECT
    COALESCE(pos.day, gl.day)                            AS date,
    COALESCE(pos.revenue_paid, 0)                        AS revenue_paid,
    COALESCE(gl.gl_credit, 0)                            AS gl_credit,
    COALESCE(pos.revenue_paid, 0) - COALESCE(gl.gl_credit, 0) AS diff
  FROM pos_by_day pos
  FULL OUTER JOIN gl_by_day gl ON gl.day = pos.day
  ORDER BY 1;
END;
$$;


ALTER FUNCTION "public"."fn_reconcile_sales_by_day"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_reconcile_sales_by_day"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") IS 'Per-day POS revenue (paid_at local) vs GL credit (511+33311, reference_type=sale, entry_date local). FULL OUTER JOIN — rows present on either side surface so missing-postings days are visible. NULL branch = sum across branches caller has finance:view.';



CREATE OR REPLACE FUNCTION "public"."get_branch_menu_daily_limits_for_pos"("p_branch_id" bigint) RETURNS TABLE("menu_item_id" bigint, "limit_quantity" integer, "is_disabled" boolean, "sold_today" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    bl.menu_item_id,
    bl.limit_quantity,
    bl.is_disabled,
    bl.sold_today
  FROM public.branch_menu_item_daily_limits bl
  WHERE bl.tenant_id = public.auth_tenant_id()
    AND bl.branch_id = p_branch_id
    AND bl.limit_date = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
    AND (
      public.auth_role() IN ('owner', 'super_manager', 'area_manager')
      OR public.auth_branch_id() = p_branch_id
    );
$$;


ALTER FUNCTION "public"."get_branch_menu_daily_limits_for_pos"("p_branch_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cash_variance_summary"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("session_count" bigint, "total_variance" numeric, "abs_variance_total" numeric, "short_count" bigint, "short_total" numeric, "over_count" bigint, "over_total" numeric, "worst_cashiers" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid    UUID;
  v_tenant BIGINT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'start/end required' USING ERRCODE = '22023';
  END IF;
  IF p_start_date > p_end_date THEN
    RAISE EXCEPTION 'start > end' USING ERRCODE = '22023';
  END IF;

  IF p_branch_id IS NOT NULL THEN
    IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.has_permission_any('finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH closed_in_range AS (
    SELECT
      ps.id,
      ps.opened_by AS cashier_id,
      ps.cash_difference
    FROM public.pos_sessions ps
    WHERE ps.tenant_id = v_tenant
      AND ps.status = 'closed'
      AND ps.closed_at IS NOT NULL
      AND ps.cash_difference IS NOT NULL
      AND (ps.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date >= p_start_date
      AND (ps.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date <= p_end_date
      AND (
        (p_branch_id IS NOT NULL AND ps.branch_id = p_branch_id)
        OR (p_branch_id IS NULL AND public.has_permission(ps.branch_id, 'finance:view'))
      )
  ),
  agg AS (
    SELECT
      COUNT(*)::BIGINT AS session_count,
      COALESCE(SUM(c.cash_difference), 0) AS total_variance,
      COALESCE(SUM(ABS(c.cash_difference)), 0) AS abs_variance_total,
      COUNT(*) FILTER (WHERE c.cash_difference < 0)::BIGINT AS short_count,
      COALESCE(SUM(c.cash_difference) FILTER (WHERE c.cash_difference < 0), 0) AS short_total,
      COUNT(*) FILTER (WHERE c.cash_difference > 0)::BIGINT AS over_count,
      COALESCE(SUM(c.cash_difference) FILTER (WHERE c.cash_difference > 0), 0) AS over_total
    FROM closed_in_range c
  ),
  by_cashier AS (
    SELECT
      c.cashier_id,
      COALESCE(pr.full_name, '—') AS cashier_name,
      COUNT(*)::BIGINT AS session_count,
      SUM(c.cash_difference) AS net_variance,
      SUM(ABS(c.cash_difference)) AS abs_variance
    FROM closed_in_range c
    LEFT JOIN public.profiles pr ON pr.id = c.cashier_id
    GROUP BY c.cashier_id, pr.full_name
  ),
  worst_top3 AS (
    SELECT bc.*
    FROM by_cashier bc
    WHERE bc.abs_variance > 0
    ORDER BY bc.abs_variance DESC
    LIMIT 3
  ),
  worst_json AS (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'cashier_id',     w.cashier_id,
          'cashier_name',   w.cashier_name,
          'session_count',  w.session_count,
          'net_variance',   w.net_variance,
          'abs_variance',   w.abs_variance
        )
        ORDER BY w.abs_variance DESC
      ),
      '[]'::jsonb
    ) AS rows
    FROM worst_top3 w
  )
  SELECT
    agg.session_count,
    agg.total_variance,
    agg.abs_variance_total,
    agg.short_count,
    agg.short_total,
    agg.over_count,
    agg.over_total,
    worst_json.rows AS worst_cashiers
  FROM agg
  CROSS JOIN worst_json;
END;
$$;


ALTER FUNCTION "public"."get_cash_variance_summary"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_cash_variance_summary"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") IS 'Aggregate POS cash variance over closed sessions in range. Variance is owned by pos_sessions.opened_by; closed_by is only the close actor and may be a manager closing another cashier shift. NULL branch = sum across branches caller has finance:view.';



CREATE OR REPLACE FUNCTION "public"."get_daily_revenue"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("date" "date", "branch_id" bigint, "tenant_id" bigint, "order_count" bigint, "total_revenue" numeric, "total_tax" numeric, "cash_revenue" numeric, "vietqr_revenue" numeric, "momo_revenue" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       UUID;
  v_tenant    BIGINT;
  v_start_utc TIMESTAMPTZ;
  v_end_utc   TIMESTAMPTZ;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NULL OR NOT public.has_permission(p_branch_id, 'finance:view') THEN
    RAISE EXCEPTION 'permission denied: finance:view required'
      USING ERRCODE = '42501';
  END IF;

  v_start_utc := (p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
    SELECT
      (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AS date,
      o.branch_id,
      o.tenant_id,
      COUNT(DISTINCT o.id)::BIGINT AS order_count,
      COALESCE(SUM(o.total_amount), 0) AS total_revenue,
      COALESCE(SUM(o.tax_amount), 0) AS total_tax,
      COALESCE(SUM(o.total_amount) FILTER (WHERE p.method = 'cash'), 0) AS cash_revenue,
      COALESCE(SUM(o.total_amount) FILTER (WHERE p.method = 'vietqr'), 0) AS vietqr_revenue,
      COALESCE(SUM(o.total_amount) FILTER (WHERE p.method = 'momo'), 0) AS momo_revenue
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
    WHERE p.tenant_id = v_tenant
      AND p.branch_id = p_branch_id
      AND p.status = 'completed'
      AND p.paid_at >= v_start_utc
      AND p.paid_at < v_end_utc
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
    GROUP BY 1, o.branch_id, o.tenant_id
    ORDER BY 1;
END;
$$;


ALTER FUNCTION "public"."get_daily_revenue"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_daily_revenue"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") IS 'Live paid-at revenue by day for one branch. Uses completed payments, Asia/Ho_Chi_Minh buckets, and finance:view branch permission.';



CREATE OR REPLACE FUNCTION "public"."get_finance_dashboard_summary"("p_start_date" "date", "p_end_date" "date", "p_branch_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("invoice_attention_count" bigint, "invoice_issued_count" bigint, "invoice_not_required_count" bigint, "journal_draft_count" bigint, "journal_posted_count" bigint, "failed_webhook_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid UUID;
  v_tenant BIGINT;
  v_start_utc TIMESTAMPTZ;
  v_end_utc TIMESTAMPTZ;
  v_has_tenant_scope BOOLEAN;
  v_branch_ids BIGINT[];
BEGIN
  IF p_start_date IS NULL OR p_end_date IS NULL OR p_start_date > p_end_date THEN
    RAISE EXCEPTION 'invalid_date_range' USING ERRCODE = '22023';
  END IF;

  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT fs.has_tenant_scope, fs.branch_ids
    INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') fs;

  IF p_branch_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.branches b
      WHERE b.id = p_branch_id
        AND b.tenant_id = v_tenant
    ) THEN
      RAISE EXCEPTION 'branch not found' USING ERRCODE = '22023';
    END IF;
    IF NOT (v_has_tenant_scope OR p_branch_id = ANY(v_branch_ids)) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT (v_has_tenant_scope OR cardinality(v_branch_ids) > 0) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_start_utc := (p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
  WITH scoped_tax_invoices AS MATERIALIZED (
    SELECT ti.*
    FROM public.tax_invoices ti
    WHERE ti.tenant_id = v_tenant
      AND (
        (p_branch_id IS NOT NULL AND ti.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (
            v_has_tenant_scope
            OR ti.branch_id = ANY(v_branch_ids)
          )
        )
      )
  ),
  scoped_journals AS MATERIALIZED (
    SELECT je.*
    FROM public.journal_entries je
    WHERE je.tenant_id = v_tenant
      AND (
        (p_branch_id IS NOT NULL AND je.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (
            v_has_tenant_scope
            OR je.branch_id = ANY(v_branch_ids)
          )
        )
      )
  ),
  scoped_failed_webhooks AS MATERIALIZED (
    SELECT we.id
    FROM public.webhook_events we
    LEFT JOIN public.payments p
      ON p.id = we.payment_id
     AND p.tenant_id = we.tenant_id
    WHERE we.tenant_id = v_tenant
      AND we.processing_status = 'failed'
      AND we.created_at >= v_start_utc
      AND we.created_at < v_end_utc
      AND (
        (p_branch_id IS NOT NULL AND p.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (
            v_has_tenant_scope
            OR p.branch_id = ANY(v_branch_ids)
          )
        )
      )
  )
  SELECT
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_tax_invoices ti
      WHERE ti.status IN ('draft', 'signing', 'submitted')
    ) AS invoice_attention_count,
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_tax_invoices ti
      WHERE ti.status = 'issued'
        AND ti.issued_at >= v_start_utc
        AND ti.issued_at < v_end_utc
    ) AS invoice_issued_count,
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_tax_invoices ti
      WHERE ti.status = 'not_required'
        AND ti.created_at >= v_start_utc
        AND ti.created_at < v_end_utc
    ) AS invoice_not_required_count,
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_journals je
      WHERE je.status = 'draft'
    ) AS journal_draft_count,
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_journals je
      WHERE je.status = 'posted'
        AND je.entry_date >= v_start_utc
        AND je.entry_date < v_end_utc
    ) AS journal_posted_count,
    (
      SELECT COUNT(*)::BIGINT
      FROM scoped_failed_webhooks
    ) AS failed_webhook_count;
END;
$$;


ALTER FUNCTION "public"."get_finance_dashboard_summary"("p_start_date" "date", "p_end_date" "date", "p_branch_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_finance_dashboard_summary"("p_start_date" "date", "p_end_date" "date", "p_branch_id" bigint) IS 'Finance home work-queue counters. Uses caller finance:view permission, branch scope, and Asia/Ho_Chi_Minh local date windows. p_branch_id NULL returns rows scoped to branches the caller can view plus tenant-wide journal entries.';



CREATE OR REPLACE FUNCTION "public"."get_food_cost"("p_branch_id" bigint DEFAULT NULL::bigint, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS TABLE("period_start" "date", "period_end" "date", "branch_id" bigint, "tenant_id" bigint, "menu_item_id" bigint, "item_name" "text", "quantity_sold" numeric, "revenue" numeric, "ingredient_cost" numeric, "food_cost_pct" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID;
  v_tenant BIGINT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant FROM public.profiles pr WHERE pr.id = v_uid;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NULL THEN
    IF NOT public.has_permission_any('finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required' USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
      RAISE EXCEPTION 'permission denied: finance:view required' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
    SELECT
      m.period_start,
      m.period_end,
      m.branch_id,
      m.tenant_id,
      m.menu_item_id,
      m.item_name,
      m.quantity_sold::NUMERIC,
      m.revenue,
      m.ingredient_cost,
      m.food_cost_pct
    FROM public.mv_food_cost m
    WHERE m.tenant_id = v_tenant
      AND (p_branch_id IS NOT NULL OR public.has_permission(m.branch_id, 'finance:view'))
      AND (p_branch_id IS NULL OR m.branch_id = p_branch_id)
      AND (p_start_date IS NULL OR m.period_start >= p_start_date)
      AND (p_end_date IS NULL OR m.period_start <= p_end_date)
    ORDER BY m.food_cost_pct DESC NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."get_food_cost"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_grn_price_baseline"("p_supplier_id" bigint, "p_ingredient_id" bigint, "p_uom" "text" DEFAULT NULL::"text") RETURNS TABLE("avg_30d" numeric, "sample_n" integer, "last_seen_at" "date", "baseline_source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(NULL, 'procurement:price_list_read') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY SELECT * FROM public._compute_grn_price_baseline(v_tenant, p_supplier_id, p_ingredient_id, p_uom);
END; $$;


ALTER FUNCTION "public"."get_grn_price_baseline"("p_supplier_id" bigint, "p_ingredient_id" bigint, "p_uom" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ingredient_abc_class"("p_branch_id" bigint, "p_ingredient_id" bigint) RETURNS character
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_tenant BIGINT := public.auth_tenant_id(); v_class CHAR; v_age INT;
BEGIN
  IF v_tenant IS NULL THEN RETURN NULL; END IF;
  SELECT class INTO v_class FROM public.ingredient_abc_class
    WHERE tenant_id = v_tenant AND branch_id = p_branch_id AND ingredient_id = p_ingredient_id;
  IF FOUND THEN RETURN v_class; END IF;
  SELECT EXTRACT(DAY FROM now() - created_at)::INT INTO v_age FROM public.branches WHERE id = p_branch_id;
  IF v_age IS NULL OR v_age < 30 THEN
    SELECT MODE() WITHIN GROUP (ORDER BY class) INTO v_class
    FROM public.ingredient_abc_class
    WHERE tenant_id = v_tenant AND ingredient_id = p_ingredient_id;
    IF v_class IS NOT NULL THEN RETURN v_class; END IF;
  END IF;
  RETURN NULL;
END; $$;


ALTER FUNCTION "public"."get_ingredient_abc_class"("p_branch_id" bigint, "p_ingredient_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_alerts"("p_branch_id" bigint, "p_types" "text"[] DEFAULT ARRAY['low_stock'::"text", 'out_of_stock'::"text", 'negative_stock'::"text"], "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("alert_type" "text", "severity_rank" integer, "ingredient_id" bigint, "ingredient_name" "text", "location_id" bigint, "location_name" "text", "current_quantity" numeric, "reorder_point" numeric, "shortage_ratio" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT (public.has_permission(p_branch_id, 'inventory:read') OR public.has_permission(NULL, 'reports:view_branch') OR public.has_permission(NULL, 'reports:view_tenant')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT (CASE WHEN m.current_quantity < 0 THEN 'negative_stock' WHEN m.current_quantity = 0 THEN 'out_of_stock' ELSE 'low_stock' END)::TEXT,
    (CASE WHEN m.current_quantity < 0 THEN 0 WHEN m.current_quantity = 0 THEN 1 ELSE 2 END)::INT,
    m.ingredient_id, m.ingredient_name, m.location_id, m.location_name, m.current_quantity, m.reorder_point,
    (CASE WHEN m.reorder_point > 0 THEN (m.reorder_point - m.current_quantity) / m.reorder_point ELSE 0 END)::NUMERIC
  FROM public.mv_inventory_stock_current m
  WHERE m.tenant_id = v_tenant AND m.branch_id = p_branch_id AND m.reorder_point IS NOT NULL AND m.current_quantity < m.reorder_point
    AND (('low_stock' = ANY(p_types) AND m.current_quantity > 0) OR ('out_of_stock' = ANY(p_types) AND m.current_quantity = 0) OR ('negative_stock' = ANY(p_types) AND m.current_quantity < 0))
  ORDER BY CASE WHEN m.current_quantity < 0 THEN 0 WHEN m.current_quantity = 0 THEN 1 ELSE 2 END,
           CASE WHEN m.reorder_point > 0 THEN (m.reorder_point - m.current_quantity) / m.reorder_point ELSE 0 END DESC
  LIMIT p_limit OFFSET p_offset;
END; $$;


ALTER FUNCTION "public"."get_inventory_alerts"("p_branch_id" bigint, "p_types" "text"[], "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_dashboard"("p_branch_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_tenant BIGINT := public.auth_tenant_id(); v_can_cost BOOLEAN;
  v_summary JSONB; v_locations JSONB; v_alerts JSONB; v_in_transit JSONB;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT (public.has_permission(p_branch_id, 'inventory:read') OR public.has_permission(NULL, 'reports:view_branch') OR public.has_permission(NULL, 'reports:view_tenant')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  v_can_cost := public.has_permission(NULL, 'reports:view_branch') OR public.has_permission(NULL, 'reports:view_tenant');

  SELECT jsonb_build_object(
    'total_skus', COALESCE(COUNT(DISTINCT m.ingredient_id), 0),
    'location_count', COALESCE(COUNT(DISTINCT m.location_id), 0),
    'total_quantity', COALESCE(SUM(m.current_quantity), 0),
    'total_value_vnd', CASE WHEN v_can_cost THEN COALESCE(SUM(m.stock_value), 0) ELSE NULL END,
    'alerts_count', (SELECT COUNT(*) FROM public.mv_inventory_stock_current a
                     WHERE a.tenant_id=v_tenant AND a.branch_id=p_branch_id
                       AND a.reorder_point IS NOT NULL AND a.current_quantity < a.reorder_point)
  ) INTO v_summary FROM public.mv_inventory_stock_current m
  WHERE m.tenant_id=v_tenant AND m.branch_id=p_branch_id;

  SELECT COALESCE(jsonb_agg(loc ORDER BY (loc->>'location_kind'), (loc->>'location_name')), '[]'::JSONB)
  INTO v_locations FROM (
    SELECT jsonb_build_object(
      'location_id', m.location_id, 'location_name', MAX(m.location_name), 'location_kind', MAX(m.location_kind),
      'sku_count', COUNT(DISTINCT m.ingredient_id), 'total_quantity', SUM(m.current_quantity),
      'total_value_vnd', CASE WHEN v_can_cost THEN SUM(m.stock_value) ELSE NULL END,
      'alerts_count', COUNT(*) FILTER (WHERE m.reorder_point IS NOT NULL AND m.current_quantity < m.reorder_point)
    ) AS loc FROM public.mv_inventory_stock_current m
    WHERE m.tenant_id=v_tenant AND m.branch_id=p_branch_id GROUP BY m.location_id) t;

  SELECT COALESCE(jsonb_agg(a ORDER BY (a->>'severity_rank'), (a->>'shortage_ratio') DESC), '[]'::JSONB)
  INTO v_alerts FROM (
    SELECT jsonb_build_object(
      'alert_type', CASE WHEN m.current_quantity < 0 THEN 'negative_stock'
                         WHEN m.current_quantity = 0 THEN 'out_of_stock' ELSE 'low_stock' END,
      'severity_rank', CASE WHEN m.current_quantity < 0 THEN 0 WHEN m.current_quantity = 0 THEN 1 ELSE 2 END,
      'ingredient_id', m.ingredient_id, 'ingredient_name', m.ingredient_name,
      'location_id', m.location_id, 'location_name', m.location_name,
      'current_quantity', m.current_quantity, 'reorder_point', m.reorder_point,
      'shortage_ratio', CASE WHEN m.reorder_point > 0 THEN (m.reorder_point - m.current_quantity) / m.reorder_point ELSE 0 END
    ) AS a FROM public.mv_inventory_stock_current m
    WHERE m.tenant_id=v_tenant AND m.branch_id=p_branch_id AND m.reorder_point IS NOT NULL AND m.current_quantity < m.reorder_point
    ORDER BY CASE WHEN m.current_quantity < 0 THEN 0 WHEN m.current_quantity = 0 THEN 1 ELSE 2 END,
             CASE WHEN m.reorder_point > 0 THEN (m.reorder_point - m.current_quantity) / m.reorder_point ELSE 0 END DESC
    LIMIT 5) t;

  SELECT COALESCE(jsonb_agg(row ORDER BY (row->>'ingredient_name')), '[]'::JSONB) INTO v_in_transit FROM (
    SELECT jsonb_build_object('ingredient_id', sti.ingredient_id, 'ingredient_name', ing.name,
      'total_quantity', SUM(sti.quantity), 'transfer_count', COUNT(DISTINCT st.id)) AS row
    FROM public.stock_transfers st
    JOIN public.stock_transfer_items sti ON sti.transfer_id = st.id
    JOIN public.ingredients ing ON ing.id = sti.ingredient_id
    WHERE st.tenant_id = v_tenant AND st.status IN ('confirmed_ship','in_transit','confirmed_receive')
      AND (st.from_branch_id = p_branch_id OR st.to_branch_id = p_branch_id)
    GROUP BY sti.ingredient_id, ing.name LIMIT 20) t;

  RETURN jsonb_build_object('branch_id', p_branch_id, 'computed_at', now(), 'can_view_cost', v_can_cost,
    'summary', v_summary, 'locations', v_locations, 'top_alerts', v_alerts, 'in_transit', v_in_transit);
END; $$;


ALTER FUNCTION "public"."get_inventory_dashboard"("p_branch_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_orders_for_day"("p_branch_id" bigint, "p_date" "date") RETURNS TABLE("order_id" bigint, "order_number" "text", "branch_id" bigint, "branch_name" "text", "paid_at" timestamp with time zone, "paid_hour" integer, "order_type" "text", "customer_count" integer, "subtotal" numeric, "discount_amount" numeric, "tax_amount" numeric, "total_amount" numeric, "payment_method" "text", "item_count" bigint, "invoice_status" "text", "invoice_number" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID;
  v_tenant BIGINT;
BEGIN
  IF p_branch_id IS NULL THEN
    RAISE EXCEPTION 'branch_id required for drill-down'
      USING ERRCODE = '22023';
  END IF;

  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
    FROM public.profiles pr WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'finance:view') THEN
    RAISE EXCEPTION 'permission denied: finance:view required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT
      o.id AS order_id,
      o.order_number,
      o.branch_id,
      b.name AS branch_name,
      p.paid_at,
      EXTRACT(HOUR FROM (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh'))::INT
        AS paid_hour,
      o.order_type,
      o.customer_count,
      o.subtotal,
      o.discount_amount,
      o.tax_amount,
      o.total_amount,
      o.payment_method,
      (SELECT COUNT(*) FROM public.order_items oi
        WHERE oi.order_id = o.id AND oi.status <> 'cancelled')::BIGINT
        AS item_count,
      ti.status         AS invoice_status,
      ti.invoice_number
    FROM public.orders o
    JOIN public.branches b
      ON b.id = o.branch_id
     AND b.tenant_id = o.tenant_id
    JOIN public.payments p
      ON p.order_id  = o.id
     AND p.tenant_id = o.tenant_id
     AND p.status    = 'completed'
     AND p.paid_at IS NOT NULL
    LEFT JOIN public.tax_invoices ti
      ON ti.order_id  = o.id
     AND ti.tenant_id = o.tenant_id
     AND ti.status NOT IN ('cancelled', 'replaced')
    WHERE o.tenant_id = v_tenant
      AND o.branch_id = p_branch_id
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = p_date
    ORDER BY p.paid_at;
END;
$$;


ALTER FUNCTION "public"."get_orders_for_day"("p_branch_id" bigint, "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pos_session_report"("p_session_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_session              RECORD;
  v_totals               RECORD;
  v_payment_mix          JSONB;
  v_top_items            JSONB;
  v_categories           JSONB;
  v_total_items          INT;
  v_hourly               JSONB;
  v_peak_hour            JSONB;
  v_aov_bins             JSONB;
  v_discount_count       INT;
  v_discount_total       NUMERIC(15,2);
  v_top_discount_orders  JSONB;
  v_void_item_count      INT;
BEGIN
  SELECT
    s.id, s.tenant_id, s.branch_id, s.terminal_id,
    s.opened_at, s.closed_at, s.opening_cash, s.closing_cash,
    s.expected_cash, s.cash_difference, s.status, s.note,
    s.variance_approval_note,
    t.name AS terminal_name,
    pop.full_name AS opened_by_name,
    pcl.full_name AS closed_by_name
  INTO v_session
  FROM public.pos_sessions s
  LEFT JOIN public.pos_terminals t  ON t.id  = s.terminal_id
  LEFT JOIN public.profiles pop     ON pop.id = s.opened_by
  LEFT JOIN public.profiles pcl     ON pcl.id = s.closed_by
  WHERE s.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_session.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT
    COUNT(*) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled') AS paid_count,
    COUNT(*) FILTER (WHERE payment_status <> 'paid' AND status <> 'cancelled') AS unpaid_count,
    COUNT(*) FILTER (WHERE status = 'cancelled') AS cancelled_count,
    COALESCE(SUM(subtotal) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS gross,
    COALESCE(SUM(discount_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS discount_total,
    COALESCE(SUM(tax_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS tax_total,
    COALESCE(SUM(service_charge) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS service_total,
    COALESCE(SUM(total_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled'), 0) AS net,
    COALESCE(SUM(total_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled' AND payment_method = 'cash'), 0) AS cash_revenue,
    COALESCE(SUM(total_amount) FILTER (WHERE payment_status = 'paid' AND status <> 'cancelled' AND (payment_method IS NULL OR payment_method <> 'cash')), 0) AS noncash_revenue
  INTO v_totals
  FROM public.orders
  WHERE pos_session_id = p_session_id
    AND tenant_id = v_session.tenant_id;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('method', payment_method, 'count', cnt, 'amount', amount)
    ORDER BY amount DESC
  ), '[]'::JSONB)
  INTO v_payment_mix
  FROM (
    SELECT payment_method, COUNT(*)::INT AS cnt, COALESCE(SUM(total_amount), 0) AS amount
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND payment_status = 'paid'
      AND status <> 'cancelled'
    GROUP BY payment_method
  ) pm;

  WITH paid_items AS (
    SELECT
      oi.menu_item_id, oi.item_name,
      mi.category_id, mc.name AS category_name,
      oi.quantity, oi.subtotal, oi.modifiers, oi.sides
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    LEFT JOIN public.menu_items mi      ON mi.id = oi.menu_item_id
    LEFT JOIN public.menu_categories mc ON mc.id = mi.category_id
    WHERE o.pos_session_id = p_session_id
      AND o.tenant_id = v_session.tenant_id
      AND o.payment_status = 'paid'
      AND o.status <> 'cancelled'
      AND oi.status <> 'cancelled'
  ),
  main_agg AS (
    SELECT item_name AS name, 'main'::TEXT AS source,
      COALESCE(SUM(quantity), 0)::INT AS qty,
      COALESCE(SUM(subtotal), 0) AS revenue
    FROM paid_items
    GROUP BY item_name
  ),
  side_agg AS (
    SELECT
      COALESCE(s ->> 'name', 'Side')::TEXT AS name,
      'side'::TEXT AS source,
      COALESCE(SUM(COALESCE((s ->> 'quantity')::INT, 1) * pi.quantity), 0)::INT AS qty,
      COALESCE(SUM(COALESCE((s ->> 'price')::NUMERIC, 0) * COALESCE((s ->> 'quantity')::INT, 1) * pi.quantity), 0) AS revenue
    FROM paid_items pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.sides) AS s
    GROUP BY s ->> 'name'
  ),
  mod_agg AS (
    SELECT
      COALESCE(m ->> 'name', 'Modifier')::TEXT AS name,
      'modifier'::TEXT AS source,
      COALESCE(SUM(pi.quantity), 0)::INT AS qty,
      COALESCE(SUM(COALESCE((m ->> 'price')::NUMERIC, 0) * pi.quantity), 0) AS revenue
    FROM paid_items pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.modifiers) AS m
    GROUP BY m ->> 'name'
  ),
  all_items AS (
    SELECT name, source, qty, revenue FROM main_agg
    UNION ALL
    SELECT name, source, qty, revenue FROM side_agg
    UNION ALL
    SELECT name, source, qty, revenue FROM mod_agg
  ),
  cat_agg AS (
    SELECT
      COALESCE(category_id, 0) AS category_id,
      COALESCE(category_name, 'Khác') AS category_name,
      COALESCE(SUM(quantity), 0)::INT AS qty,
      COALESCE(SUM(subtotal), 0) AS revenue
    FROM paid_items
    GROUP BY category_id, category_name
  )
  SELECT
    (SELECT COALESCE(jsonb_agg(jsonb_build_object('name', name, 'source', source, 'qty', qty, 'revenue', revenue) ORDER BY qty DESC, revenue DESC), '[]'::JSONB)
     FROM (SELECT name, source, qty, revenue FROM all_items ORDER BY qty DESC, revenue DESC LIMIT 10) ti),
    (SELECT COALESCE(jsonb_agg(jsonb_build_object('category_id', category_id, 'category_name', category_name, 'qty', qty, 'revenue', revenue) ORDER BY revenue DESC), '[]'::JSONB)
     FROM cat_agg),
    COALESCE((SELECT SUM(qty) FROM all_items), 0)::INT
  INTO v_top_items, v_categories, v_total_items;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('hour', hour, 'order_count', cnt, 'revenue', revenue)
    ORDER BY hour
  ), '[]'::JSONB)
  INTO v_hourly
  FROM (
    SELECT
      EXTRACT(HOUR FROM (created_at AT TIME ZONE 'Asia/Ho_Chi_Minh'))::INT AS hour,
      COUNT(*)::INT AS cnt,
      COALESCE(SUM(total_amount), 0) AS revenue
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND payment_status = 'paid'
      AND status <> 'cancelled'
    GROUP BY 1
  ) h;

  SELECT
    CASE WHEN cnt > 0 THEN
      jsonb_build_object('hour', hour, 'order_count', cnt, 'revenue', revenue)
    ELSE NULL END
  INTO v_peak_hour
  FROM (
    SELECT
      EXTRACT(HOUR FROM (created_at AT TIME ZONE 'Asia/Ho_Chi_Minh'))::INT AS hour,
      COUNT(*)::INT AS cnt,
      COALESCE(SUM(total_amount), 0) AS revenue
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND payment_status = 'paid'
      AND status <> 'cancelled'
    GROUP BY 1
    ORDER BY revenue DESC, cnt DESC
    LIMIT 1
  ) p;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('label', label, 'count', cnt) ORDER BY ord
  ), '[]'::JSONB)
  INTO v_aov_bins
  FROM (
    SELECT label, ord, COUNT(*)::INT AS cnt
    FROM (
      SELECT
        CASE
          WHEN total_amount <= 50000  THEN '≤50.000đ'
          WHEN total_amount <= 100000 THEN '50.000–100.000đ'
          WHEN total_amount <= 200000 THEN '100.000–200.000đ'
          WHEN total_amount <= 500000 THEN '200.000–500.000đ'
          ELSE '>500.000đ'
        END AS label,
        CASE
          WHEN total_amount <= 50000  THEN 1
          WHEN total_amount <= 100000 THEN 2
          WHEN total_amount <= 200000 THEN 3
          WHEN total_amount <= 500000 THEN 4
          ELSE 5
        END AS ord
      FROM public.orders
      WHERE pos_session_id = p_session_id
        AND tenant_id = v_session.tenant_id
        AND payment_status = 'paid'
        AND status <> 'cancelled'
    ) b
    GROUP BY label, ord
  ) g;

  SELECT COUNT(*)::INT, COALESCE(SUM(discount_amount), 0)
  INTO v_discount_count, v_discount_total
  FROM public.orders
  WHERE pos_session_id = p_session_id
    AND tenant_id = v_session.tenant_id
    AND discount_amount > 0
    AND status <> 'cancelled';

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'order_id', order_id, 'order_number', order_number,
      'amount', amount, 'note', note, 'type', type, 'value', value
    ) ORDER BY amount DESC
  ), '[]'::JSONB)
  INTO v_top_discount_orders
  FROM (
    SELECT
      id AS order_id, order_number,
      discount_amount AS amount, discount_note AS note,
      discount_type AS type, discount_value AS value
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND discount_amount > 0
      AND status <> 'cancelled'
    ORDER BY discount_amount DESC
    LIMIT 10
  ) d;

  SELECT COUNT(*)::INT
  INTO v_void_item_count
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE o.pos_session_id = p_session_id
    AND o.tenant_id = v_session.tenant_id
    AND oi.status = 'cancelled';

  RETURN jsonb_build_object(
    'session', jsonb_build_object(
      'id', v_session.id, 'opened_at', v_session.opened_at,
      'closed_at', v_session.closed_at, 'status', v_session.status,
      'terminal_name', v_session.terminal_name,
      'opened_by_name', v_session.opened_by_name,
      'closed_by_name', v_session.closed_by_name,
      'opening_cash', v_session.opening_cash,
      'closing_cash', v_session.closing_cash,
      'expected_cash', v_session.expected_cash,
      'cash_difference', v_session.cash_difference,
      'note', v_session.note,
      'variance_approval_note', v_session.variance_approval_note
    ),
    'totals', jsonb_build_object(
      'gross_revenue', v_totals.gross,
      'discount_total', v_totals.discount_total,
      'tax_total', v_totals.tax_total,
      'service_charge_total', v_totals.service_total,
      'net_revenue', v_totals.net,
      'cash_revenue', v_totals.cash_revenue,
      'noncash_revenue', v_totals.noncash_revenue,
      'paid_order_count', v_totals.paid_count,
      'unpaid_order_count', v_totals.unpaid_count,
      'cancelled_order_count', v_totals.cancelled_count,
      'void_item_count', v_void_item_count,
      'total_items', v_total_items,
      'aov', CASE WHEN v_totals.paid_count > 0 THEN ROUND(v_totals.net / v_totals.paid_count, 2) ELSE 0 END
    ),
    'payment_mix', v_payment_mix,
    'top_items', v_top_items,
    'category_breakdown', v_categories,
    'aov_bins', v_aov_bins,
    'hourly', v_hourly,
    'peak_hour', v_peak_hour,
    'discounts', jsonb_build_object(
      'count', v_discount_count, 'total', v_discount_total,
      'top_orders', v_top_discount_orders
    ),
    'generated_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."get_pos_session_report"("p_session_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_pos_session_report"("p_session_id" bigint) IS 'Aggregate read-only report cho 1 ca POS. SECURITY INVOKER + tenant recheck. Decompose combo (sides + modifiers as separate items). Hourly theo Asia/Ho_Chi_Minh tz. Filter payment_status=paid + status<>cancelled cho mọi revenue metric. Cash vs noncash split. Returns JSONB.';



CREATE OR REPLACE FUNCTION "public"."get_revenue_by_cashier"("p_branch_id" bigint DEFAULT NULL::bigint, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS TABLE("cashier_id" "uuid", "cashier_name" "text", "order_count" bigint, "net_revenue" numeric, "cash_revenue" numeric, "qr_revenue" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid UUID;
  v_tenant BIGINT;
  v_days INT;
  v_start_utc TIMESTAMPTZ;
  v_end_utc TIMESTAMPTZ;
  v_has_tenant_scope BOOLEAN;
  v_branch_ids BIGINT[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'start/end required' USING ERRCODE = '22023';
  END IF;
  IF p_start_date > p_end_date THEN
    RAISE EXCEPTION 'start > end' USING ERRCODE = '22023';
  END IF;

  v_days := (p_end_date - p_start_date) + 1;
  IF v_days > 90 THEN
    RAISE EXCEPTION 'range > 90 days' USING ERRCODE = '22023';
  END IF;

  SELECT fs.has_tenant_scope, fs.branch_ids
    INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') fs;

  IF p_branch_id IS NULL THEN
    IF NOT (v_has_tenant_scope OR cardinality(v_branch_ids) > 0) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT (v_has_tenant_scope OR p_branch_id = ANY(v_branch_ids)) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_start_utc := (p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
  WITH scoped_payments AS MATERIALIZED (
    SELECT
      p.id AS payment_id,
      p.method,
      p.amount,
      o.id AS order_id,
      o.subtotal,
      o.discount_amount,
      COALESCE(ps.opened_by, p.created_by) AS cashier_id
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
     AND o.branch_id = p.branch_id
    LEFT JOIN public.pos_sessions ps
      ON ps.id = o.pos_session_id
     AND ps.tenant_id = o.tenant_id
     AND ps.branch_id = o.branch_id
    WHERE p.tenant_id = v_tenant
      AND p.status = 'completed'
      AND p.paid_at >= v_start_utc
      AND p.paid_at < v_end_utc
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (
        (p_branch_id IS NOT NULL AND o.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (v_has_tenant_scope OR o.branch_id = ANY(v_branch_ids))
        )
      )
  ),
  order_rows AS (
    SELECT DISTINCT ON (sp.order_id)
      sp.cashier_id,
      sp.order_id,
      sp.subtotal,
      sp.discount_amount
    FROM scoped_payments sp
    ORDER BY sp.order_id, sp.payment_id DESC
  ),
  orders_by_cashier AS (
    SELECT
      o.cashier_id,
      COUNT(*)::BIGINT AS order_count,
      COALESCE(SUM(o.subtotal - o.discount_amount), 0)::NUMERIC AS net_revenue
    FROM order_rows o
    GROUP BY o.cashier_id
  ),
  payments_by_cashier AS (
    SELECT
      sp.cashier_id,
      COALESCE(SUM(sp.amount) FILTER (WHERE sp.method = 'cash'), 0)::NUMERIC AS cash_revenue,
      COALESCE(SUM(sp.amount) FILTER (WHERE sp.method IN ('vietqr', 'momo')), 0)::NUMERIC AS qr_revenue
    FROM scoped_payments sp
    GROUP BY sp.cashier_id
  )
  SELECT
    ob.cashier_id,
    COALESCE(pr.full_name, '— Không xác định')::TEXT AS cashier_name,
    ob.order_count,
    ob.net_revenue,
    COALESCE(pb.cash_revenue, 0)::NUMERIC AS cash_revenue,
    COALESCE(pb.qr_revenue, 0)::NUMERIC AS qr_revenue
  FROM orders_by_cashier ob
  LEFT JOIN payments_by_cashier pb ON pb.cashier_id = ob.cashier_id
  LEFT JOIN public.profiles pr ON pr.id = ob.cashier_id
  ORDER BY ob.net_revenue DESC;
END;
$$;


ALTER FUNCTION "public"."get_revenue_by_cashier"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_revenue_by_cashier"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") IS 'Cashier productivity for Finance Revenue. Cashier identity comes from orders.pos_session_id -> pos_sessions.opened_by, falling back to payments.created_by for legacy orders without a session link. Uses payments.method and completed paid_at rows.';



CREATE OR REPLACE FUNCTION "public"."get_revenue_by_hour"("p_branch_id" bigint DEFAULT NULL::bigint, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS TABLE("dow" smallint, "hour" smallint, "order_count" bigint, "net_revenue" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_tenant BIGINT;
  v_days INT;
  v_start_utc TIMESTAMPTZ;
  v_end_utc TIMESTAMPTZ;
  v_has_tenant_scope BOOLEAN;
  v_branch_ids BIGINT[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'start/end required' USING ERRCODE = '22023';
  END IF;
  IF p_start_date > p_end_date THEN
    RAISE EXCEPTION 'start > end' USING ERRCODE = '22023';
  END IF;

  v_days := (p_end_date - p_start_date) + 1;
  IF v_days > 90 THEN
    RAISE EXCEPTION 'range > 90 days' USING ERRCODE = '22023';
  END IF;

  SELECT fs.has_tenant_scope, fs.branch_ids
    INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') fs;

  IF p_branch_id IS NULL THEN
    IF NOT (v_has_tenant_scope OR cardinality(v_branch_ids) > 0) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT (v_has_tenant_scope OR p_branch_id = ANY(v_branch_ids)) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_start_utc := (p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
  WITH paid AS MATERIALIZED (
    SELECT
      (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh') AS paid_local,
      o.id AS order_id,
      o.subtotal,
      o.discount_amount
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
     AND o.branch_id = p.branch_id
    WHERE p.tenant_id = v_tenant
      AND p.status = 'completed'
      AND p.paid_at >= v_start_utc
      AND p.paid_at < v_end_utc
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (
        (p_branch_id IS NOT NULL AND o.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (v_has_tenant_scope OR o.branch_id = ANY(v_branch_ids))
        )
      )
  )
  SELECT
    EXTRACT(DOW FROM paid.paid_local)::SMALLINT AS dow,
    EXTRACT(HOUR FROM paid.paid_local)::SMALLINT AS hour,
    COUNT(DISTINCT paid.order_id)::BIGINT AS order_count,
    COALESCE(SUM(paid.subtotal - paid.discount_amount), 0)::NUMERIC AS net_revenue
  FROM paid
  GROUP BY 1, 2
  ORDER BY 1, 2;
END;
$$;


ALTER FUNCTION "public"."get_revenue_by_hour"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_revenue_kpis"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("net_revenue" numeric, "subtotal_revenue" numeric, "discount_amount" numeric, "total_tax" numeric, "vat_8_amount" numeric, "vat_10_amount" numeric, "order_count" bigint, "total_covers" bigint, "cash_revenue" numeric, "vietqr_revenue" numeric, "momo_revenue" numeric, "dine_in_revenue" numeric, "takeaway_revenue" numeric, "voided_amount" numeric, "voided_count" bigint, "refreshed_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid UUID;
  v_tenant BIGINT;
  v_start_utc TIMESTAMPTZ;
  v_end_utc TIMESTAMPTZ;
  v_has_tenant_scope BOOLEAN;
  v_branch_ids BIGINT[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT fs.has_tenant_scope, fs.branch_ids
    INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') fs;

  IF p_branch_id IS NULL THEN
    IF NOT (v_has_tenant_scope OR cardinality(v_branch_ids) > 0) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT (v_has_tenant_scope OR p_branch_id = ANY(v_branch_ids)) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_start_utc := (p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
  WITH paid_orders AS MATERIALIZED (
    SELECT
      o.id,
      o.branch_id,
      o.tenant_id,
      o.total_amount,
      o.subtotal,
      o.discount_amount,
      o.tax_amount,
      o.customer_count,
      o.order_type,
      p.method
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
     AND o.branch_id = p.branch_id
    WHERE p.tenant_id = v_tenant
      AND p.status = 'completed'
      AND p.paid_at >= v_start_utc
      AND p.paid_at < v_end_utc
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (
        (p_branch_id IS NOT NULL AND o.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (v_has_tenant_scope OR o.branch_id = ANY(v_branch_ids))
        )
      )
  ),
  sales AS (
    SELECT
      COALESCE(SUM(total_amount), 0) AS net_revenue,
      COALESCE(SUM(subtotal), 0) AS subtotal_revenue,
      COALESCE(SUM(discount_amount), 0) AS discount_amount,
      COALESCE(SUM(tax_amount), 0) AS total_tax,
      COUNT(*)::BIGINT AS order_count,
      COALESCE(SUM(customer_count), 0)::BIGINT AS total_covers,
      COALESCE(SUM(total_amount) FILTER (WHERE method = 'cash'), 0) AS cash_revenue,
      COALESCE(SUM(total_amount) FILTER (WHERE method = 'vietqr'), 0) AS vietqr_revenue,
      COALESCE(SUM(total_amount) FILTER (WHERE method = 'momo'), 0) AS momo_revenue,
      COALESCE(SUM(total_amount) FILTER (WHERE order_type = 'dine_in'), 0) AS dine_in_revenue,
      COALESCE(SUM(total_amount) FILTER (WHERE order_type = 'takeaway'), 0) AS takeaway_revenue
    FROM paid_orders
  ),
  vat_split AS (
    SELECT
      COALESCE(SUM(
        CASE WHEN ROUND(oi.vat_rate::numeric, 2) = 8.00
          THEN (oi.subtotal * scaled.scale) - ((oi.subtotal * scaled.scale) / (1 + oi.vat_rate / 100))
          ELSE 0
        END
      ), 0) AS vat_8_amount,
      COALESCE(SUM(
        CASE WHEN ROUND(oi.vat_rate::numeric, 2) = 10.00
          THEN (oi.subtotal * scaled.scale) - ((oi.subtotal * scaled.scale) / (1 + oi.vat_rate / 100))
          ELSE 0
        END
      ), 0) AS vat_10_amount
    FROM (
      SELECT
        po.id AS order_id,
        po.tenant_id,
        CASE
          WHEN SUM(oi2.subtotal) > 0 THEN po.total_amount / SUM(oi2.subtotal)
          ELSE 1
        END AS scale
      FROM paid_orders po
      JOIN public.order_items oi2
        ON oi2.tenant_id = po.tenant_id
       AND oi2.order_id = po.id
       AND oi2.status <> 'cancelled'
      GROUP BY po.id, po.tenant_id, po.total_amount
    ) scaled
    JOIN public.order_items oi
      ON oi.tenant_id = scaled.tenant_id
     AND oi.order_id = scaled.order_id
     AND oi.status <> 'cancelled'
  ),
  refunds AS (
    SELECT
      COALESCE(SUM(p.amount), 0) AS voided_amount,
      COUNT(DISTINCT p.order_id)::BIGINT AS voided_count
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
     AND o.branch_id = p.branch_id
    WHERE p.tenant_id = v_tenant
      AND p.status = 'refunded'
      AND p.paid_at >= v_start_utc
      AND p.paid_at < v_end_utc
      AND (
        (p_branch_id IS NOT NULL AND o.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (v_has_tenant_scope OR o.branch_id = ANY(v_branch_ids))
        )
      )
  )
  SELECT
    sales.net_revenue,
    sales.subtotal_revenue,
    sales.discount_amount,
    sales.total_tax,
    vat_split.vat_8_amount,
    vat_split.vat_10_amount,
    sales.order_count,
    sales.total_covers,
    sales.cash_revenue,
    sales.vietqr_revenue,
    sales.momo_revenue,
    sales.dine_in_revenue,
    sales.takeaway_revenue,
    refunds.voided_amount,
    refunds.voided_count,
    now() AS refreshed_at
  FROM sales
  CROSS JOIN vat_split
  CROSS JOIN refunds;
END;
$$;


ALTER FUNCTION "public"."get_revenue_kpis"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_revenue_kpis"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date") IS 'Live KPI bundle for Finance revenue. refreshed_at is request time, not MV refresh time.';



CREATE OR REPLACE FUNCTION "public"."get_revenue_rollup"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_granularity" "text") RETURNS TABLE("period_start" "date", "period_end" "date", "period_label" "text", "branch_id" bigint, "order_count" bigint, "total_revenue" numeric, "total_tax" numeric, "subtotal_revenue" numeric, "discount_amount" numeric, "cash_revenue" numeric, "vietqr_revenue" numeric, "momo_revenue" numeric, "dine_in_revenue" numeric, "takeaway_revenue" numeric, "total_covers" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_tenant BIGINT;
  v_start_utc TIMESTAMPTZ;
  v_end_utc TIMESTAMPTZ;
  v_has_tenant_scope BOOLEAN;
  v_branch_ids BIGINT[];
BEGIN
  IF p_granularity NOT IN ('day', 'week', 'month') THEN
    RAISE EXCEPTION 'invalid_granularity (expected day/week/month)'
      USING ERRCODE = '22023';
  END IF;

  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT fs.has_tenant_scope, fs.branch_ids
    INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') fs;

  IF p_branch_id IS NULL THEN
    IF NOT (v_has_tenant_scope OR cardinality(v_branch_ids) > 0) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT (v_has_tenant_scope OR p_branch_id = ANY(v_branch_ids)) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_start_utc := (p_start_date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((p_end_date + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
  WITH live_daily AS (
    SELECT
      (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AS paid_date,
      o.branch_id,
      COUNT(DISTINCT o.id)::BIGINT AS order_count,
      COALESCE(SUM(o.total_amount), 0) AS total_revenue,
      COALESCE(SUM(o.tax_amount), 0) AS total_tax,
      COALESCE(SUM(o.subtotal), 0) AS subtotal_revenue,
      COALESCE(SUM(o.discount_amount), 0) AS discount_amount,
      COALESCE(SUM(o.total_amount) FILTER (WHERE p.method = 'cash'), 0) AS cash_revenue,
      COALESCE(SUM(o.total_amount) FILTER (WHERE p.method = 'vietqr'), 0) AS vietqr_revenue,
      COALESCE(SUM(o.total_amount) FILTER (WHERE p.method = 'momo'), 0) AS momo_revenue,
      COALESCE(SUM(o.total_amount) FILTER (WHERE o.order_type = 'dine_in'), 0) AS dine_in_revenue,
      COALESCE(SUM(o.total_amount) FILTER (WHERE o.order_type = 'takeaway'), 0) AS takeaway_revenue,
      COALESCE(SUM(o.customer_count), 0)::BIGINT AS total_covers
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
     AND o.branch_id = p.branch_id
    WHERE p.tenant_id = v_tenant
      AND p.status = 'completed'
      AND p.paid_at >= v_start_utc
      AND p.paid_at < v_end_utc
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (
        (p_branch_id IS NOT NULL AND o.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (v_has_tenant_scope OR o.branch_id = ANY(v_branch_ids))
        )
      )
    GROUP BY 1, o.branch_id
  ),
  bucketed AS (
    SELECT
      CASE p_granularity
        WHEN 'day' THEN d.paid_date
        WHEN 'week' THEN date_trunc('week', d.paid_date)::date
        WHEN 'month' THEN date_trunc('month', d.paid_date)::date
      END AS p_start,
      CASE p_granularity
        WHEN 'day' THEN d.paid_date
        WHEN 'week' THEN (date_trunc('week', d.paid_date) + INTERVAL '6 days')::date
        WHEN 'month' THEN (date_trunc('month', d.paid_date) + INTERVAL '1 month - 1 day')::date
      END AS p_end,
      d.*
    FROM live_daily d
  )
  SELECT
    b.p_start AS period_start,
    b.p_end AS period_end,
    CASE p_granularity
      WHEN 'day' THEN to_char(b.p_start, 'DD/MM/YYYY')
      WHEN 'week' THEN
        'Tuần ' || to_char(b.p_start, 'IW') || ' ('
          || to_char(b.p_start, 'DD/MM') || '-'
          || to_char(b.p_end, 'DD/MM/YYYY') || ')'
      WHEN 'month' THEN 'Tháng ' || to_char(b.p_start, 'MM/YYYY')
    END AS period_label,
    b.branch_id,
    COALESCE(SUM(b.order_count), 0)::BIGINT AS order_count,
    COALESCE(SUM(b.total_revenue), 0) AS total_revenue,
    COALESCE(SUM(b.total_tax), 0) AS total_tax,
    COALESCE(SUM(b.subtotal_revenue), 0) AS subtotal_revenue,
    COALESCE(SUM(b.discount_amount), 0) AS discount_amount,
    COALESCE(SUM(b.cash_revenue), 0) AS cash_revenue,
    COALESCE(SUM(b.vietqr_revenue), 0) AS vietqr_revenue,
    COALESCE(SUM(b.momo_revenue), 0) AS momo_revenue,
    COALESCE(SUM(b.dine_in_revenue), 0) AS dine_in_revenue,
    COALESCE(SUM(b.takeaway_revenue), 0) AS takeaway_revenue,
    COALESCE(SUM(b.total_covers), 0)::BIGINT AS total_covers
  FROM bucketed b
  GROUP BY b.p_start, b.p_end, b.branch_id
  ORDER BY b.p_start, b.branch_id;
END;
$$;


ALTER FUNCTION "public"."get_revenue_rollup"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_revenue_rollup"("p_branch_id" bigint, "p_start_date" "date", "p_end_date" "date", "p_granularity" "text") IS 'Live paid-at revenue rollup. p_branch_id NULL returns period x branch rows for branches where caller has finance:view.';



CREATE OR REPLACE FUNCTION "public"."get_stocktake_lines_blind"("p_session_id" bigint) RETURNS TABLE("line_id" bigint, "ingredient_id" bigint, "ingredient_name" "text", "unit" "text", "abc_class" character, "round_no" smallint, "counted_quantity" numeric, "counted_by" "uuid", "counted_at" timestamp with time zone, "needs_recount" boolean, "is_final" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tenant BIGINT := public.auth_tenant_id();
  v_ss     RECORD;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT s.branch_id, s.blind_mode, s.tenant_id INTO v_ss
  FROM public.stocktake_sessions s WHERE s.id = p_session_id;
  IF NOT FOUND OR v_ss.tenant_id <> v_tenant THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_ss.branch_id, 'inventory:stocktake_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    sl.id,
    sl.ingredient_id,
    ing.name,
    COALESCE(ing.purchase_unit, ing.unit),
    sl.abc_class,
    sl.round_no,
    sl.counted_quantity,
    sl.counted_by,
    sl.counted_at,
    sl.needs_recount,
    sl.is_final
  FROM public.stocktake_lines sl
  JOIN public.ingredients ing ON ing.id = sl.ingredient_id
  WHERE sl.session_id = p_session_id
  ORDER BY sl.round_no, ing.name;
END;
$$;


ALTER FUNCTION "public"."get_stocktake_lines_blind"("p_session_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_top_items"("p_branch_id" bigint DEFAULT NULL::bigint, "p_period_start" "date" DEFAULT NULL::"date", "p_limit" integer DEFAULT 20) RETURNS TABLE("period_start" "date", "period_end" "date", "branch_id" bigint, "tenant_id" bigint, "menu_item_id" bigint, "item_name" "text", "quantity_sold" numeric, "revenue" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_tenant BIGINT;
  v_effective_limit INT;
  v_period_start DATE;
  v_period_end DATE;
  v_start_utc TIMESTAMPTZ;
  v_end_utc TIMESTAMPTZ;
  v_has_tenant_scope BOOLEAN;
  v_branch_ids BIGINT[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT pr.tenant_id INTO v_tenant
  FROM public.profiles pr
  WHERE pr.id = v_uid;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT fs.has_tenant_scope, fs.branch_ids
    INTO v_has_tenant_scope, v_branch_ids
  FROM private.finance_scope(v_uid, 'finance:view') fs;

  IF p_branch_id IS NULL THEN
    IF NOT (v_has_tenant_scope OR cardinality(v_branch_ids) > 0) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT (v_has_tenant_scope OR p_branch_id = ANY(v_branch_ids)) THEN
      RAISE EXCEPTION 'permission denied: finance:view required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_effective_limit := GREATEST(1, LEAST(COALESCE(p_limit, 20), 200));
  v_period_start := COALESCE(
    p_period_start,
    date_trunc('month', (now() AT TIME ZONE 'Asia/Ho_Chi_Minh'))::date
  );
  v_period_end := (date_trunc('month', v_period_start)::date + INTERVAL '1 month - 1 day')::date;
  v_start_utc := (v_period_start::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');
  v_end_utc := ((v_period_end + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh');

  RETURN QUERY
  WITH paid_orders AS MATERIALIZED (
    SELECT DISTINCT
      o.id,
      o.branch_id,
      o.tenant_id
    FROM public.payments p
    JOIN public.orders o
      ON o.id = p.order_id
     AND o.tenant_id = p.tenant_id
     AND o.branch_id = p.branch_id
    WHERE p.tenant_id = v_tenant
      AND p.status = 'completed'
      AND p.paid_at >= v_start_utc
      AND p.paid_at < v_end_utc
      AND o.status <> 'cancelled'
      AND o.payment_status = 'paid'
      AND (
        (p_branch_id IS NOT NULL AND o.branch_id = p_branch_id)
        OR (
          p_branch_id IS NULL
          AND (v_has_tenant_scope OR o.branch_id = ANY(v_branch_ids))
        )
      )
  )
  SELECT
    v_period_start AS period_start,
    v_period_end AS period_end,
    po.branch_id,
    po.tenant_id,
    oi.menu_item_id,
    MAX(oi.item_name) AS item_name,
    COALESCE(SUM(oi.quantity), 0)::NUMERIC AS quantity_sold,
    COALESCE(SUM(oi.subtotal), 0)::NUMERIC AS revenue
  FROM paid_orders po
  JOIN public.order_items oi
    ON oi.tenant_id = po.tenant_id
   AND oi.order_id = po.id
   AND oi.status <> 'cancelled'
  GROUP BY po.branch_id, po.tenant_id, oi.menu_item_id
  ORDER BY quantity_sold DESC, revenue DESC
  LIMIT v_effective_limit;
END;
$$;


ALTER FUNCTION "public"."get_top_items"("p_branch_id" bigint, "p_period_start" "date", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_top_items"("p_branch_id" bigint, "p_period_start" "date", "p_limit" integer) IS 'Live paid-at top items. p_branch_id NULL still checks finance:view per returned branch row.';



CREATE OR REPLACE FUNCTION "public"."gl_reconciliation"("p_tenant_id" bigint, "p_year" integer, "p_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_start_date DATE;
  v_end_date   DATE;
  v_full       JSONB;
BEGIN
  v_start_date := make_date(p_year, p_month, 1);
  v_end_date   := (v_start_date + INTERVAL '1 month' - INTERVAL '1 day')::DATE;

  v_full := public.fn_reconcile_period(p_tenant_id, v_start_date, v_end_date, NULL);

  RETURN (
    SELECT jsonb_agg(jsonb_build_object(
      'category', cat ->> 'label',
      'subledger_total', cat ->> 'subledger_total',
      'gl_total', cat ->> 'gl_total',
      'difference', cat ->> 'difference'
    ))
    FROM jsonb_array_elements(v_full -> 'categories') cat
  );
END;
$$;


ALTER FUNCTION "public"."gl_reconciliation"("p_tenant_id" bigint, "p_year" integer, "p_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_permission"("p_target_user" "uuid", "p_branch_id" bigint, "p_permission_key" "text", "p_source_template" bigint DEFAULT NULL::bigint, "p_valid_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_valid_until" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT;
  v_target_tenant BIGINT;
  v_grant_id  BIGINT;
  v_from      TIMESTAMPTZ := COALESCE(p_valid_from, now());
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'staff:assign_permission') THEN
    RAISE EXCEPTION 'forbidden: missing staff:assign_permission' USING ERRCODE = '42501';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.profiles WHERE id = auth.uid();
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'actor_no_profile' USING ERRCODE = '42501';
  END IF;

  SELECT tenant_id INTO v_target_tenant FROM public.profiles WHERE id = p_target_user;
  IF v_target_tenant IS NULL OR v_target_tenant <> v_tenant_id THEN
    RAISE EXCEPTION 'target_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  IF public._auth_v2_is_owner(p_target_user) THEN
    RAISE EXCEPTION 'cannot_manage_owner_permissions' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.permission_keys WHERE key = p_permission_key) THEN
    RAISE EXCEPTION 'unknown_permission_key: %', p_permission_key USING ERRCODE = '22023';
  END IF;

  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branches WHERE id = p_branch_id AND tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'branch_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  IF p_valid_until IS NOT NULL AND p_valid_until <= v_from THEN
    RAISE EXCEPTION 'invalid_validity_window: valid_until must be after valid_from' USING ERRCODE = '22023';
  END IF;

  -- Upsert semantics:
  --   Existing row for same (user, branch, key) → UPDATE validity if longer,
  --   else leave alone. This keeps audit meaningful: re-granting extends the
  --   window rather than creating duplicates.
  SELECT id INTO v_grant_id
  FROM public.staff_permissions
  WHERE user_id = p_target_user
    AND permission_key = p_permission_key
    AND (
      (p_branch_id IS NULL AND branch_id IS NULL)
      OR branch_id = p_branch_id
    )
  LIMIT 1;

  IF v_grant_id IS NULL THEN
    INSERT INTO public.staff_permissions (
      user_id, tenant_id, branch_id, permission_key, source_template, granted_by,
      valid_from, valid_until
    ) VALUES (
      p_target_user, v_tenant_id, p_branch_id, p_permission_key, p_source_template, auth.uid(),
      v_from, p_valid_until
    )
    RETURNING id INTO v_grant_id;

    INSERT INTO public.permission_audit_log (
      tenant_id, actor_user_id, target_user_id, branch_id,
      permission_key, action, source_template_id, metadata
    ) VALUES (
      v_tenant_id, auth.uid(), p_target_user, p_branch_id,
      p_permission_key, 'grant', p_source_template,
      jsonb_build_object(
        'valid_from',  v_from,
        'valid_until', p_valid_until
      )
    );
  ELSE
    -- Extend validity if new window is broader (or change explicit)
    UPDATE public.staff_permissions
    SET valid_from  = LEAST(valid_from, v_from),
        valid_until = CASE
          WHEN p_valid_until IS NULL THEN NULL  -- make permanent
          WHEN valid_until  IS NULL THEN valid_until  -- already permanent, keep
          ELSE GREATEST(valid_until, p_valid_until)
        END
    WHERE id = v_grant_id;
  END IF;

  RETURN v_grant_id;
END;
$$;


ALTER FUNCTION "public"."grant_permission"("p_target_user" "uuid", "p_branch_id" bigint, "p_permission_key" "text", "p_source_template" bigint, "p_valid_from" timestamp with time zone, "p_valid_until" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grn_is_auto_approvable"("p_grn_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tenant BIGINT := public.auth_tenant_id(); v_grn RECORD; v_tz TEXT; v_local_time TIMESTAMP; v_win RECORD;
  v_in_base BOOLEAN := false; v_in_ext BOOLEAN := false; v_in_window BOOLEAN;
  v_total_grn NUMERIC; v_total_po NUMERIC; v_line_qty_max NUMERIC; v_line_prc_max NUMERIC;
  v_bad_qc INT; v_bad_review INT; v_bad_var INT; v_sup_hist INT; v_trust NUMERIC;
  v_cap NUMERIC := 10000000;
  v_c1 BOOLEAN; v_c2 BOOLEAN; v_c3 BOOLEAN; v_c4 BOOLEAN;
  v_c5 BOOLEAN; v_c6 BOOLEAN; v_c7 BOOLEAN; v_c8 BOOLEAN;
  v_hard_ok BOOLEAN; v_soft_ok BOOLEAN; v_approved BOOLEAN;
  v_reasons TEXT[] := ARRAY[]::TEXT[];
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_grn FROM public.goods_received_notes WHERE id = p_grn_id AND tenant_id = v_tenant;
  IF NOT FOUND THEN RAISE EXCEPTION 'grn not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_grn.branch_id, 'inventory:read') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;

  SELECT timezone INTO v_tz FROM public.branches WHERE id = v_grn.branch_id;
  IF v_tz IS NULL THEN v_tz := 'Asia/Ho_Chi_Minh'; END IF;
  v_local_time := now() AT TIME ZONE v_tz;
  SELECT enabled, start_time, end_time INTO v_win FROM public.branch_express_window WHERE branch_id = v_grn.branch_id;
  IF FOUND AND v_win.enabled THEN
    v_in_base := (v_local_time::TIME >= v_win.start_time AND v_local_time::TIME < v_win.end_time);
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.grn_express_extend_audit WHERE branch_id = v_grn.branch_id AND extended_until > now() AND created_at > now() - INTERVAL '1 day') INTO v_in_ext;
  v_in_window := v_in_base OR v_in_ext;

  v_c1 := v_grn.po_id IS NOT NULL;
  IF NOT v_c1 THEN v_reasons := array_append(v_reasons, 'no_po'); END IF;

  SELECT COUNT(*) INTO v_bad_var FROM public.grn_items WHERE grn_id = p_grn_id AND (variance_tier IS NULL OR variance_tier > 1);
  v_c2 := v_bad_var = 0;
  IF NOT v_c2 THEN v_reasons := array_append(v_reasons, 'variance_tier_gt1'); END IF;

  IF v_c1 THEN
    SELECT COALESCE(SUM((received_quantity - COALESCE(rejected_quantity, 0)) * unit_cost), 0)
      INTO v_total_grn FROM public.grn_items WHERE grn_id = p_grn_id;
    SELECT COALESCE(SUM(line_total), 0) INTO v_total_po FROM public.purchase_order_items WHERE po_id = v_grn.po_id;
    SELECT COALESCE(MAX(ABS(gi.received_quantity - gi.po_quantity) / NULLIF(gi.po_quantity, 0)), 0) INTO v_line_qty_max FROM public.grn_items gi WHERE gi.grn_id = p_grn_id;
    SELECT COALESCE(MAX(ABS(gi.unit_cost - gi.po_unit_price) / NULLIF(gi.po_unit_price, 0)), 0) INTO v_line_prc_max FROM public.grn_items gi WHERE gi.grn_id = p_grn_id;
    v_c3 := (v_total_po > 0 AND ABS(v_total_grn - v_total_po) / v_total_po <= 0.03) AND v_line_qty_max <= 0.10 AND v_line_prc_max <= 0.15;
  ELSE
    v_c3 := false;
  END IF;
  IF NOT v_c3 THEN v_reasons := array_append(v_reasons, 'line_totals_diff'); END IF;

  SELECT COUNT(*) INTO v_bad_qc FROM public.grn_items WHERE grn_id = p_grn_id
    AND (quality_status IN ('rejected','partial') OR rejected_quantity > 0 OR short_delivery_action IS NOT NULL);
  v_c4 := v_bad_qc = 0;
  IF NOT v_c4 THEN v_reasons := array_append(v_reasons, 'quality_issue'); END IF;

  IF v_total_grn IS NULL THEN
    SELECT COALESCE(SUM((received_quantity - COALESCE(rejected_quantity, 0)) * unit_cost), 0)
      INTO v_total_grn FROM public.grn_items WHERE grn_id = p_grn_id;
  END IF;
  v_c5 := v_total_grn <= v_cap;
  IF NOT v_c5 THEN v_reasons := array_append(v_reasons, 'value_cap'); END IF;

  SELECT COUNT(*) INTO v_sup_hist FROM public.goods_received_notes WHERE supplier_id = v_grn.supplier_id
    AND status = 'confirmed' AND received_date > now() - INTERVAL '90 days' AND id <> p_grn_id;
  v_c6 := v_sup_hist >= 3;
  IF NOT v_c6 THEN v_reasons := array_append(v_reasons, 'supplier_history_lt3'); END IF;

  SELECT COUNT(*) INTO v_bad_review FROM public.grn_items gi WHERE gi.grn_id = p_grn_id
    AND public.inventory_requires_manual_review(gi.ingredient_id) = true;
  v_c7 := v_bad_review = 0;
  IF NOT v_c7 THEN v_reasons := array_append(v_reasons, 'ingredient_manual_review'); END IF;

  v_trust := public.compute_user_trust_score(v_grn.created_by, v_grn.branch_id);
  v_c8 := v_trust >= 70;
  IF NOT v_c8 THEN v_reasons := array_append(v_reasons, 'trust_score_lt70'); END IF;

  v_hard_ok := v_c1 AND v_c3 AND v_c4 AND v_c5 AND v_c7 AND v_c8;
  v_soft_ok := v_c2 AND v_c6;
  v_approved := v_hard_ok AND (v_soft_ok OR v_in_window);

  RETURN jsonb_build_object('grn_id', p_grn_id, 'approved', v_approved, 'hard_ok', v_hard_ok, 'soft_ok', v_soft_ok,
    'in_window', v_in_window, 'in_base_window', v_in_base, 'in_extended_window', v_in_ext,
    'total_grn_value', v_total_grn, 'total_po_value', v_total_po, 'supplier_grn_count_90d', v_sup_hist,
    'trust_score', v_trust,
    'conditions', jsonb_build_object('c1_has_po', v_c1, 'c2_variance_ok', v_c2, 'c3_line_totals_diff', v_c3,
      'c4_no_quality_issue', v_c4, 'c5_value_cap', v_c5, 'c6_supplier_history', v_c6,
      'c7_no_manual_review', v_c7, 'c8_trust_score_ok', v_c8),
    'failed_reasons', to_jsonb(v_reasons), 'evaluated_at', now());
END; $$;


ALTER FUNCTION "public"."grn_is_auto_approvable"("p_grn_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."grn_is_auto_approvable"("p_grn_id" bigint) IS 'Auto-approve evaluator. v_total_grn dùng net (received - rejected) × cost — parity với GL inventory_total và stock value. Line qty variance vẫn so sánh delivered vs ordered.';



CREATE OR REPLACE FUNCTION "public"."grn_items_compute_variance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_grn RECORD; v_baseline RECORD; v_signed NUMERIC; v_abs_pct NUMERIC; v_tier SMALLINT;
BEGIN
  IF NEW.unit_cost IS NULL OR NEW.unit_cost <= 0 THEN
    NEW.variance_tier := NULL; NEW.baseline_source := NULL; NEW.baseline_sample_n := NULL;
    NEW.baseline_variance_pct := NULL; NEW.is_hard_blocked := false; RETURN NEW;
  END IF;
  SELECT tenant_id, supplier_id INTO v_grn FROM public.goods_received_notes WHERE id = NEW.grn_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  SELECT avg_30d, sample_n, baseline_source INTO v_baseline
    FROM public._compute_grn_price_baseline(v_grn.tenant_id, v_grn.supplier_id, NEW.ingredient_id, NEW.unit);
  NEW.baseline_source := v_baseline.baseline_source;
  NEW.baseline_sample_n := v_baseline.sample_n;
  IF v_baseline.avg_30d IS NULL THEN
    NEW.variance_tier := NULL; NEW.baseline_variance_pct := NULL; NEW.is_hard_blocked := false; RETURN NEW;
  END IF;
  v_signed := (NEW.unit_cost - v_baseline.avg_30d) / v_baseline.avg_30d;
  v_abs_pct := ABS(v_signed);
  NEW.baseline_variance_pct := (v_signed * 100)::NUMERIC(7,3);
  IF      v_abs_pct < 0.15 THEN v_tier := 0;
  ELSIF   v_abs_pct < 0.30 THEN v_tier := 1;
  ELSIF   v_abs_pct < 1.00 THEN v_tier := 2;
  ELSE                          v_tier := 3;
  END IF;
  NEW.variance_tier := v_tier;
  NEW.is_hard_blocked := (v_tier = 3) AND NOT EXISTS (SELECT 1 FROM public.grn_hardblock_overrides WHERE grn_item_id = NEW.id);
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."grn_items_compute_variance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_journal_entry_no_delete_posted"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.status IN ('posted', 'voided') THEN
    RAISE EXCEPTION
      'cannot_delete_posted_journal_entry: entry % has status=%; void it (status flag) to preserve sequence continuity per Luật Kế toán Đ24',
      OLD.entry_number,
      OLD.status
      USING ERRCODE = '23514';
  END IF;
  -- status='draft' → allow delete (pre-posting working set)
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."guard_journal_entry_no_delete_posted"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_journal_entry_no_delete_posted"() IS 'Blocks DELETE of journal_entries with status posted/voided. Rule JE-VOID-REVERSING-ONLY + Luật Kế toán 2015 Đ24 sequence continuity.';



CREATE OR REPLACE FUNCTION "public"."guard_journal_entry_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_period_status TEXT;
  v_period_year   INT;
  v_period_month  INT;
BEGIN
  IF NEW.status = 'posted' AND OLD.status = 'draft' THEN
    v_period_year := EXTRACT(YEAR FROM NEW.entry_date AT TIME ZONE 'Asia/Ho_Chi_Minh')::INT;
    v_period_month := EXTRACT(MONTH FROM NEW.entry_date AT TIME ZONE 'Asia/Ho_Chi_Minh')::INT;

    SELECT fp.status INTO v_period_status
    FROM public.fiscal_periods fp
    WHERE fp.tenant_id = NEW.tenant_id
      AND fp.period_year = v_period_year
      AND fp.period_month = v_period_month
    FOR SHARE;

    IF v_period_status = 'closed' THEN
      RAISE EXCEPTION
        'fiscal_period_closed_cannot_post: %-% is closed, cannot post journal entry %',
        v_period_year,
        lpad(v_period_month::TEXT, 2, '0'),
        NEW.entry_number
        USING ERRCODE = '23514';
    END IF;

    IF v_period_status IS NULL THEN
      INSERT INTO public.fiscal_periods (tenant_id, period_month, period_year, status)
      VALUES (NEW.tenant_id, v_period_month, v_period_year, 'open')
      ON CONFLICT (period_month, period_year, tenant_id) DO NOTHING;
    END IF;
  END IF;

  -- Only fire when a POSTED entry is being voided. Drafts have no
  -- GL impact yet; their void/delete is a working-set operation.
  IF NEW.status = 'voided' AND OLD.status = 'posted' THEN
    v_period_year := EXTRACT(YEAR FROM OLD.entry_date AT TIME ZONE 'Asia/Ho_Chi_Minh')::INT;
    v_period_month := EXTRACT(MONTH FROM OLD.entry_date AT TIME ZONE 'Asia/Ho_Chi_Minh')::INT;

    SELECT fp.status INTO v_period_status
    FROM public.fiscal_periods fp
    WHERE fp.tenant_id = OLD.tenant_id
      AND fp.period_year = v_period_year
      AND fp.period_month = v_period_month
    FOR SHARE;

    IF v_period_status = 'closed' THEN
      RAISE EXCEPTION
        'period_closed_cannot_void: entry % was posted in %-% which is closed; create a reversing entry in the current open period instead',
        OLD.entry_number,
        v_period_year,
        lpad(v_period_month::TEXT, 2, '0')
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_journal_entry_period"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_journal_entry_period"() IS 'Blocks posting/voiding journal entries when the relevant fiscal period is closed. Period boundary uses Asia/Ho_Chi_Minh.';



CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_tenant_id   BIGINT;
  v_branch_id   BIGINT;
  v_role_text   TEXT;
  v_position_id BIGINT;
BEGIN
  v_tenant_id := COALESCE(
    (NEW.raw_app_meta_data ->> 'tenant_id')::bigint,
    (SELECT id FROM public.tenants WHERE slug = 'comtammatu' LIMIT 1)
  );
  v_branch_id := NULLIF(NEW.raw_app_meta_data ->> 'branch_id', '')::bigint;
  v_role_text := COALESCE(NEW.raw_app_meta_data ->> 'role', 'owner');
  v_position_id := public._auth_v2_position_id_from_role(v_role_text, v_tenant_id);

  -- H3a invariant: profiles.position_id is NOT NULL. Refuse to insert a
  -- broken row — surface the misconfiguration to the operator instead of
  -- silently demoting the new user (or — worse — auto-falling-back to
  -- 'office', which historically defaulted to 'owner' and would be a
  -- privilege-escalation vector via raw_app_meta_data role typos).
  IF v_position_id IS NULL THEN
    RAISE EXCEPTION
      'handle_new_user: position_not_resolved for role=% tenant=% — verify positions seeded for tenant + role string is one of (owner, super_manager, area_manager, branch_manager, warehouse_manager, production_manager, cashier, waiter, chef, office)',
      v_role_text, v_tenant_id
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.profiles (id, tenant_id, branch_id, position_id, full_name)
  VALUES (
    NEW.id, v_tenant_id, v_branch_id, v_position_id,
    COALESCE(NEW.raw_app_meta_data ->> 'full_name', NEW.raw_user_meta_data ->> 'full_name', '')
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_new_user"() IS 'Auth trigger — creates a profile row when an auth.users row is inserted. H3a: refuses to insert NULL position_id (RAISE EXCEPTION). Operator must seed positions before tenant signup or pass a valid role in raw_app_meta_data.';



CREATE OR REPLACE FUNCTION "public"."has_permission"("p_branch_id" bigint, "p_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    EXISTS (
      SELECT 1 FROM public.profiles pr
      JOIN public.positions po ON po.id = pr.position_id
      WHERE pr.id = auth.uid() AND po.code = 'owner'
    )
    OR
    EXISTS (
      SELECT 1 FROM public.staff_permissions sp
      WHERE sp.user_id = auth.uid()
        AND sp.permission_key = p_key
        AND (sp.branch_id = p_branch_id OR sp.branch_id IS NULL)
        AND sp.valid_from <= now()
        AND (sp.valid_until IS NULL OR sp.valid_until > now())
    );
$$;


ALTER FUNCTION "public"."has_permission"("p_branch_id" bigint, "p_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."has_permission"("p_branch_id" bigint, "p_key" "text") IS 'Authoritative authz check. Call from RLS policies as has_permission(row.branch_id, ''module:action'').';



