CREATE OR REPLACE FUNCTION "public"."heartbeat_zone_lock"("p_session_id" bigint, "p_zone_id" "text", "p_ttl_seconds" integer DEFAULT 1800) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_new TIMESTAMPTZ;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  UPDATE public.stocktake_zone_locks SET last_heartbeat_at = now(), expires_at = now() + make_interval(secs => p_ttl_seconds)
   WHERE session_id = p_session_id AND zone_id = p_zone_id AND locked_by = v_uid RETURNING expires_at INTO v_new;
  IF v_new IS NULL THEN RAISE EXCEPTION 'zone lock not held by caller' USING ERRCODE = '42501'; END IF;
  RETURN v_new;
END; $$;


ALTER FUNCTION "public"."heartbeat_zone_lock"("p_session_id" bigint, "p_zone_id" "text", "p_ttl_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inventory_requires_manual_review"("p_ingredient_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ing AS (
    SELECT tenant_id, category, review_override
    FROM public.ingredients
    WHERE id = p_ingredient_id
  )
  SELECT COALESCE(
    (SELECT review_override FROM ing),
    (SELECT p.requires_manual_review
     FROM ing i
     LEFT JOIN public.ingredient_category_review_policy p
       ON p.tenant_id = i.tenant_id
      AND p.category  = i.category),
    false
  );
$$;


