COMMENT ON FUNCTION "public"."inventory_requires_manual_review"("p_ingredient_id" bigint) IS 'Effective manual-review flag: item override takes precedence over category policy; defaults to false. Used by GRN auto-approve evaluator.';



CREATE OR REPLACE FUNCTION "public"."inventory_shift_key"("p_branch_id" bigint, "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tz           TEXT;
  v_local        TIMESTAMP;
  v_hour         INT;
  v_segment      TEXT;
  v_anchor_date  DATE;
BEGIN
  SELECT timezone INTO v_tz
  FROM public.branches
  WHERE id = p_branch_id;

  IF v_tz IS NULL THEN
    v_tz := 'Asia/Ho_Chi_Minh';
  END IF;

  v_local := p_at AT TIME ZONE v_tz;
  v_hour  := EXTRACT(HOUR FROM v_local)::INT;

  IF v_hour < 4 THEN
    v_anchor_date := (v_local - INTERVAL '1 day')::DATE;
    v_segment     := 'evening';
  ELSIF v_hour < 12 THEN
    v_anchor_date := v_local::DATE;
    v_segment     := 'morning';
  ELSIF v_hour < 18 THEN
    v_anchor_date := v_local::DATE;
    v_segment     := 'afternoon';
  ELSE
    v_anchor_date := v_local::DATE;
    v_segment     := 'evening';
  END IF;

  RETURN to_char(v_anchor_date, 'YYYY-MM-DD') || '_' || v_segment;
END;
$$;


ALTER FUNCTION "public"."inventory_shift_key"("p_branch_id" bigint, "p_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."inventory_shift_key"("p_branch_id" bigint, "p_at" timestamp with time zone) IS 'Canonical shift key YYYY-MM-DD_{morning|afternoon|evening} per branch local time with 04:00 business-day cutoff.';



