CREATE OR REPLACE FUNCTION "public"."list_branch_menu_daily_limits"("p_branch_id" bigint, "p_limit_date" "date" DEFAULT NULL::"date") RETURNS TABLE("menu_item_id" bigint, "item_name" "text", "category_id" bigint, "category_name" "text", "base_price" numeric, "limit_id" bigint, "limit_date" "date", "limit_quantity" integer, "is_disabled" boolean, "sold_today" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_role      TEXT   := public.auth_role();
  v_branch    BIGINT := public.auth_branch_id();
  v_date      DATE   := COALESCE(
    p_limit_date,
    (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  );
BEGIN
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF v_role NOT IN ('owner', 'super_manager', 'area_manager')
     AND (v_branch IS NULL OR v_branch <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM public.branches b
   WHERE b.id = p_branch_id AND b.tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    mi.id,
    mi.name,
    mc.id,
    mc.name,
    mi.base_price,
    bl.id,
    bl.limit_date,
    bl.limit_quantity,
    COALESCE(bl.is_disabled, FALSE),
    COALESCE(bl.sold_today, 0)
  FROM public.menu_items mi
  JOIN public.menu_categories mc ON mc.id = mi.category_id
  LEFT JOIN public.branch_menu_item_daily_limits bl
    ON bl.menu_item_id = mi.id
   AND bl.branch_id = p_branch_id
   AND bl.limit_date = v_date
  WHERE mi.tenant_id = v_tenant_id
    AND mi.is_active = TRUE
  ORDER BY mc.sort_order, mi.sort_order, mi.name;
END;
$$;


ALTER FUNCTION "public"."list_branch_menu_daily_limits"("p_branch_id" bigint, "p_limit_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_audit"("p_action" "text", "p_entity_type" "text", "p_entity_id" bigint DEFAULT NULL::bigint, "p_old" "jsonb" DEFAULT NULL::"jsonb", "p_new" "jsonb" DEFAULT NULL::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id   UUID   := auth.uid();
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_id        BIGINT;
BEGIN
  -- Reject anonymous / missing-claim callers — append-only audit must
  -- always have a real actor.
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'audit.log_audit: anonymous caller'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'audit.log_audit: missing tenant_id claim'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_action IS NULL OR length(p_action) = 0 THEN
    RAISE EXCEPTION 'audit.log_audit: action required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_entity_type IS NULL OR length(p_entity_type) = 0 THEN
    RAISE EXCEPTION 'audit.log_audit: entity_type required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  INSERT INTO public.audit_logs (
    tenant_id,
    user_id,
    action,
    entity_type,
    entity_id,
    old_data,
    new_data
  ) VALUES (
    v_tenant_id,
    v_user_id,
    p_action,
    p_entity_type,
    p_entity_id,
    p_old,
    p_new
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."log_audit"("p_action" "text", "p_entity_type" "text", "p_entity_id" bigint, "p_old" "jsonb", "p_new" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_audit"("p_action" "text", "p_entity_type" "text", "p_entity_id" bigint, "p_old" "jsonb", "p_new" "jsonb") IS 'Append a row to audit_logs. tenant_id and user_id are forced server-side from auth claims — callers cannot spoof them. Only path to write audit_logs (direct INSERT revoked).';



CREATE OR REPLACE FUNCTION "public"."mark_all_notifications_read"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_count BIGINT;
BEGIN
  WITH ctx AS MATERIALIZED (
    SELECT
      auth.uid() AS user_id,
      public.auth_tenant_id() AS tenant_id,
      public.auth_branch_id() AS branch_id,
      public.auth_role() AS user_role
  ),
  visible_unread AS (
    SELECT n.id, ctx.user_id
    FROM ctx
    JOIN public.notifications n
      ON n.tenant_id = ctx.tenant_id
    WHERE ctx.user_id IS NOT NULL
      AND ctx.tenant_id IS NOT NULL
      AND ctx.user_role IS NOT NULL
      AND n.target_roles @> ARRAY[ctx.user_role]::text[]
      AND (
        n.target_branch_id IS NULL
        OR n.target_branch_id = ctx.branch_id
        OR ctx.user_role IN ('owner', 'super_manager', 'area_manager')
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.notification_reads r
        WHERE r.notification_id = n.id
          AND r.user_id = ctx.user_id
      )
      AND (n.expires_at IS NULL OR n.expires_at > now())
  )
  INSERT INTO public.notification_reads (notification_id, user_id)
  SELECT id, user_id
  FROM visible_unread
  ON CONFLICT (notification_id, user_id) DO NOTHING;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."mark_all_notifications_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_kds_item_out_of_stock"("p_ticket_id" bigint, "p_disable_for_day" boolean DEFAULT true, "p_reason" "text" DEFAULT 'Hết món'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             UUID := auth.uid();
  v_reason          TEXT := COALESCE(NULLIF(trim(p_reason), ''), 'Hết món');
  v_row             RECORD;
  v_subtotal        NUMERIC(15,2);
  v_discount_amount NUMERIC(15,2);
  v_limit           RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('kds:mark_ready') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  IF length(v_reason) < 2 THEN
    RAISE EXCEPTION 'reason too short' USING ERRCODE = '22023';
  END IF;

  SELECT
    kt.id AS ticket_id,
    kt.tenant_id,
    kt.branch_id,
    kt.status AS ticket_status,
    kt.order_id,
    kt.order_item_id,
    oi.menu_item_id,
    oi.item_name,
    oi.status AS item_status,
    o.order_number,
    o.status AS order_status,
    o.payment_status,
    o.service_charge,
    o.discount_type,
    o.discount_value
  INTO v_row
  FROM public.kds_tickets kt
  JOIN public.order_items oi
    ON oi.id = kt.order_item_id
   AND oi.tenant_id = kt.tenant_id
  JOIN public.orders o
    ON o.id = kt.order_id
   AND o.tenant_id = kt.tenant_id
  WHERE kt.id = p_ticket_id
    AND kt.tenant_id = public.auth_tenant_id()
    AND public.can_access_branch(kt.branch_id)
  FOR UPDATE OF kt, oi, o;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ticket_not_found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_row.order_id);

  IF v_row.order_status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order_terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_row.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order_already_paid' USING ERRCODE = '22023';
  END IF;

  IF v_row.ticket_status NOT IN ('pending', 'preparing')
     OR v_row.item_status NOT IN ('pending', 'preparing') THEN
    RAISE EXCEPTION 'item_not_out_of_stockable' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
  SET status = 'cancelled',
      cancel_reason = 'kds_out_of_stock: ' || v_reason,
      updated_at = now()
  WHERE id = v_row.order_item_id
    AND tenant_id = v_row.tenant_id;

  UPDATE public.kds_tickets
  SET status = 'cancelled',
      bumped_at = now(),
      bumped_by = v_uid,
      updated_at = now()
  WHERE id = v_row.ticket_id
    AND tenant_id = v_row.tenant_id;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal
  FROM public.order_items
  WHERE order_id = v_row.order_id
    AND tenant_id = v_row.tenant_id
    AND status <> 'cancelled';

  v_discount_amount := public.compute_discount_amount(
    v_row.discount_type,
    v_row.discount_value,
    v_subtotal
  );

  UPDATE public.orders o
  SET
    subtotal        = v_subtotal,
    discount_type   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_type END,
    discount_value  = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_value END,
    discount_note   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_note END,
    discount_amount = v_discount_amount,
    total_amount    = v_subtotal + COALESCE(o.service_charge, 0) - v_discount_amount,
    updated_at      = now()
  WHERE o.id = v_row.order_id
    AND o.tenant_id = v_row.tenant_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_row.tenant_id,
    v_row.order_id,
    v_row.order_status,
    v_row.order_status,
    v_uid,
    'kds_out_of_stock_item ' || v_row.order_item_id::TEXT || ': ' || v_reason
  );

  IF p_disable_for_day THEN
    INSERT INTO public.branch_menu_item_daily_limits (
      tenant_id,
      branch_id,
      menu_item_id,
      limit_date,
      limit_quantity,
      is_disabled,
      sold_today
    )
    VALUES (
      v_row.tenant_id,
      v_row.branch_id,
      v_row.menu_item_id,
      (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
      NULL,
      TRUE,
      0
    )
    ON CONFLICT (branch_id, menu_item_id, limit_date)
    DO UPDATE SET
      is_disabled = TRUE,
      updated_at = now()
    RETURNING limit_quantity, is_disabled, sold_today
    INTO v_limit;
  ELSE
    SELECT limit_quantity, is_disabled, sold_today
    INTO v_limit
    FROM public.branch_menu_item_daily_limits
    WHERE branch_id = v_row.branch_id
      AND menu_item_id = v_row.menu_item_id
      AND limit_date = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;

    IF NOT FOUND THEN
      SELECT NULL::INT AS limit_quantity,
             FALSE AS is_disabled,
             0::INT AS sold_today
      INTO v_limit;
    END IF;
  END IF;

  INSERT INTO public.notifications (
    tenant_id,
    target_branch_id,
    target_roles,
    kind,
    severity,
    title,
    body,
    entity_type,
    entity_id,
    action_url,
    dedup_key,
    meta
  )
  VALUES (
    v_row.tenant_id,
    v_row.branch_id,
    ARRAY['cashier', 'waiter', 'branch_manager']::TEXT[],
    'pos.kds_out_of_stock',
    'warning',
    format('Bếp báo hết món #%s', v_row.order_number),
    format('%s cần đổi món hoặc bỏ khỏi đơn.', v_row.item_name),
    'order_item',
    v_row.order_item_id,
    format('/br/%s/pos?order=%s', v_row.branch_id, v_row.order_id),
    format('kds_out_of_stock:%s', v_row.ticket_id),
    jsonb_build_object(
      'order_id', v_row.order_id,
      'order_number', v_row.order_number,
      'order_item_id', v_row.order_item_id,
      'menu_item_id', v_row.menu_item_id,
      'item_name', v_row.item_name,
      'reason', v_reason,
      'disabled_for_day', p_disable_for_day
    )
  )
  ON CONFLICT (tenant_id, dedup_key) WHERE dedup_key IS NOT NULL
  DO UPDATE SET
    severity = EXCLUDED.severity,
    title = EXCLUDED.title,
    body = EXCLUDED.body,
    action_url = EXCLUDED.action_url,
    meta = EXCLUDED.meta,
    created_at = now(),
    expires_at = NULL;

  PERFORM public.check_order_ready(v_row.order_id);

  RETURN jsonb_build_object(
    'ticket_id', v_row.ticket_id,
    'order_id', v_row.order_id,
    'order_item_id', v_row.order_item_id,
    'menu_item_id', v_row.menu_item_id,
    'item_name', v_row.item_name,
    'disabled_for_day', p_disable_for_day,
    'limit_quantity', v_limit.limit_quantity,
    'is_disabled', COALESCE(v_limit.is_disabled, p_disable_for_day),
    'sold_today', COALESCE(v_limit.sold_today, 0)
  );
END;
$$;


ALTER FUNCTION "public"."mark_kds_item_out_of_stock"("p_ticket_id" bigint, "p_disable_for_day" boolean, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_kds_item_out_of_stock"("p_ticket_id" bigint, "p_disable_for_day" boolean, "p_reason" "text") IS 'KDS dispatch exception. Cancels one active kitchen ticket/order item as out-of-stock, optionally disables the menu item for the branch/day, and notifies POS.';



CREATE OR REPLACE FUNCTION "public"."mark_order_item_served"("p_item_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_item RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(po.legacy_role_code, 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT
    oi.id,
    oi.order_id,
    oi.tenant_id,
    oi.status        AS item_status,
    o.branch_id,
    o.status         AS order_status
  INTO v_item
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_item_id
  FOR UPDATE OF oi;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_item.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner', 'super_manager', 'area_manager') THEN
    NULL;
  ELSIF v_prof_branch IS NOT NULL AND v_item.branch_id <> v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_item.order_status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF v_item.item_status NOT IN ('pending', 'preparing', 'ready') THEN
    RAISE EXCEPTION 'invalid item transition to served' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
  SET status = 'served',
      updated_at = now()
  WHERE id = p_item_id;

  UPDATE public.kds_tickets
  SET status = 'served',
      bumped_at = COALESCE(bumped_at, now()),
      bumped_by = COALESCE(bumped_by, v_uid),
      updated_at = now()
  WHERE order_item_id = p_item_id
    AND tenant_id = v_item.tenant_id
    AND status <> 'cancelled';

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_item.tenant_id, v_item.order_id, v_item.order_status, v_item.order_status,
    v_uid, 'mark_item_served ' || p_item_id::text
  );

  RETURN jsonb_build_object(
    'item_id',   p_item_id,
    'order_id',  v_item.order_id,
    'status',    'served'
  );
END;
$$;


ALTER FUNCTION "public"."mark_order_item_served"("p_item_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_order_item_served"("p_item_id" bigint) IS 'POS waiter per-item served action. Sets one order_items row + matching kds_tickets to served. Order-level state machine is untouched; cashier still drives ''served''/''completed'' via update_pos_order_status / payment close. Permission: pos role with branch scope (cashier/waiter/manager).';



CREATE OR REPLACE FUNCTION "public"."materialize_print_document"("p_kind" "text", "p_payload" "jsonb", "p_template_id" bigint, "p_template_version" integer, "p_paper_width_mm" integer, "p_font_profile" "text", "p_content" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_blocks JSONB;
  v_block JSONB;
  v_render_block JSONB;
  v_type TEXT;
  v_left TEXT;
  v_right TEXT;
  v_out JSONB := '[]'::jsonb;
BEGIN
  v_blocks := p_content->'blocks';
  IF v_blocks IS NULL
     OR jsonb_typeof(v_blocks) <> 'array'
     OR COALESCE(jsonb_array_length(v_blocks), 0) = 0 THEN
    v_blocks := public.print_template_default_content(p_kind)->'blocks';
  END IF;

  FOR v_block IN SELECT value FROM jsonb_array_elements(v_blocks)
  LOOP
    v_type := v_block->>'type';
    IF v_type IS NULL THEN
      CONTINUE;
    END IF;

    IF NOT public.print_template_block_visible(v_block, p_payload) THEN
      CONTINUE;
    END IF;

    v_render_block := v_block
      - 'when_field'
      - 'when_equals'
      - 'when_not_equals'
      - 'when_not_equals_field'
      - 'when_not_empty'
      - 'when_min';

    CASE v_type
      WHEN 'text' THEN
        v_out := v_out || jsonb_build_array(
          jsonb_set(
            v_render_block,
            '{text}',
            to_jsonb(public.print_template_interpolate(v_block->>'text', p_payload)),
            true
          )
        );
      WHEN 'row' THEN
        v_left := public.print_template_interpolate(v_block->>'left', p_payload);
        v_right := public.print_template_interpolate(v_block->>'right', p_payload);
        v_out := v_out || jsonb_build_array(
          jsonb_set(
            jsonb_set(v_render_block, '{left}', to_jsonb(v_left), true),
            '{right}',
            to_jsonb(v_right),
            true
          )
        );
      WHEN 'branchInfo' THEN
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object(
            'branch_name', COALESCE(p_payload->>'branch_name', ''),
            'branch_address', COALESCE(p_payload->>'branch_address', ''),
            'branch_phone', COALESCE(p_payload->>'branch_phone', ''),
            'branch_tax_code', COALESCE(p_payload->>'branch_tax_code', '')
          )
        );
      WHEN 'billMeta' THEN
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object(
            'order_number', COALESCE(p_payload->>'order_number', ''),
            'order_type', COALESCE(p_payload->>'order_type', ''),
            'table_number', p_payload->'table_number',
            'cashier_name', COALESCE(p_payload->>'cashier_name', ''),
            'created_at', COALESCE(p_payload->>'created_at', '')
          )
        );
      WHEN 'paymentMethod' THEN
        IF COALESCE(p_payload->>'payment_method', '') = '' THEN
          CONTINUE;
        END IF;
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object('method', p_payload->>'payment_method')
        );
      WHEN 'itemsTable' THEN
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object('items', COALESCE(p_payload->'items', '[]'::jsonb))
        );
      WHEN 'totals' THEN
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object(
            'subtotal', p_payload->'subtotal',
            'tax_amount', p_payload->'tax_amount',
            'service_charge', p_payload->'service_charge',
            'discount_amount', p_payload->'discount_amount',
            'total_amount', p_payload->'total_amount'
          )
        );
      WHEN 'cashChange' THEN
        IF NOT (p_payload ? 'cash_received' OR p_payload ? 'cash_change') THEN
          CONTINUE;
        END IF;
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object(
            'cash_received', p_payload->'cash_received',
            'cash_change', p_payload->'cash_change',
            'total_amount', p_payload->'total_amount'
          )
        );
      WHEN 'note' THEN
        IF COALESCE(NULLIF(trim(p_payload->>'note'), ''), '') = '' THEN
          CONTINUE;
        END IF;
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object('text', p_payload->>'note')
        );
      WHEN 'paymentQr' THEN
        IF jsonb_typeof(p_payload->'payment_qr') <> 'object'
           OR COALESCE(p_payload#>>'{payment_qr,content}', '') = '' THEN
          CONTINUE;
        END IF;
        v_out := v_out || jsonb_build_array(
          v_render_block || jsonb_build_object('qr', p_payload->'payment_qr')
        );
      WHEN 'kitchenItems' THEN
        v_out := v_out || public.print_template_kitchen_item_blocks(p_payload, false);
      WHEN 'cancelItems' THEN
        v_out := v_out || public.print_template_kitchen_item_blocks(p_payload, true);
      WHEN 'shiftCashReconciliation' THEN
        v_out := v_out || public.print_template_shift_cash_blocks(p_payload);
      WHEN 'paymentBreakdown' THEN
        v_out := v_out || public.print_template_payment_breakdown_blocks(p_payload);
      WHEN 'shiftOrderSummary' THEN
        v_out := v_out || public.print_template_shift_summary_blocks(p_payload);
      WHEN 'shiftItemBreakdown' THEN
        v_out := v_out || public.print_template_shift_item_breakdown_blocks(p_payload);
      WHEN 'shiftVarianceNotice' THEN
        v_out := v_out || public.print_template_shift_variance_notice_blocks(p_payload);
      WHEN 'shiftSignature' THEN
        v_out := v_out || public.print_template_shift_signature_blocks();
      WHEN 'varianceApproval' THEN
        v_out := v_out || public.print_template_variance_approval_blocks(p_payload);
      WHEN 'kitchenTicket' THEN
        v_out := v_out || (
          public.materialize_print_document(
            'kitchen_ticket',
            p_payload,
            p_template_id,
            p_template_version,
            p_paper_width_mm,
            p_font_profile,
            public.print_template_default_content('kitchen_ticket')
          )->'blocks'
        );
      WHEN 'cancelTicket' THEN
        v_out := v_out || (
          public.materialize_print_document(
            'cancel_ticket',
            p_payload,
            p_template_id,
            p_template_version,
            p_paper_width_mm,
            p_font_profile,
            public.print_template_default_content('cancel_ticket')
          )->'blocks'
        );
      WHEN 'shiftCloseReport' THEN
        v_out := v_out || (
          public.materialize_print_document(
            'shift_close_report',
            p_payload,
            p_template_id,
            p_template_version,
            p_paper_width_mm,
            p_font_profile,
            public.print_template_default_content('shift_close_report')
          )->'blocks'
        );
      ELSE
        v_out := v_out || jsonb_build_array(v_render_block);
    END CASE;
  END LOOP;

  IF jsonb_array_length(v_out) = 0 THEN
    v_out := jsonb_build_array(
      jsonb_build_object('type', 'text', 'text', COALESCE(p_payload->>'kind', p_kind))
    );
  END IF;

  RETURN jsonb_build_object(
    'schema_version', 1,
    'template_id', COALESCE(p_template_id, 0),
    'template_version', COALESCE(p_template_version, 1),
    'paper_width_mm', COALESCE(p_paper_width_mm, 80),
    'font_profile', COALESCE(p_font_profile, 'thermal_vietnamese'),
    'blocks', v_out
  );
END;
$$;


ALTER FUNCTION "public"."materialize_print_document"("p_kind" "text", "p_payload" "jsonb", "p_template_id" bigint, "p_template_version" integer, "p_paper_width_mm" integer, "p_font_profile" "text", "p_content" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."materialize_print_document"("p_kind" "text", "p_payload" "jsonb", "p_template_id" bigint, "p_template_version" integer, "p_paper_width_mm" integer, "p_font_profile" "text", "p_content" "jsonb") IS 'Materialize active print templates into primitive schema_version=1 document blocks. New ticket layouts should be changed in print_template_versions, not in branch print-agent deployments.';



CREATE OR REPLACE FUNCTION "public"."merge_orders"("p_source_order_id" bigint, "p_target_order_id" bigint, "p_idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid                  UUID;
  v_prof_tenant          BIGINT;
  v_prof_branch          BIGINT;
  v_prof_role            TEXT;
  v_source               RECORD;
  v_target               RECORD;
  v_lock_lo              BIGINT;
  v_lock_hi              BIGINT;
  v_flag_enabled         TEXT;
  v_moved_count          INT;
  v_target_subtotal      NUMERIC(15,2);
  v_target_discount_type   TEXT;
  v_target_discount_value  NUMERIC(15,2);
  v_target_discount_note   TEXT;
  v_target_discount_amount NUMERIC(15,2);
  v_target_total           NUMERIC(15,2);
  v_source_total           NUMERIC(15,2);
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(po.legacy_role_code, 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'super_manager', 'area_manager', 'branch_manager', 'cashier', 'waiter')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_source_order_id = p_target_order_id THEN
    RAISE EXCEPTION 'merge_self' USING ERRCODE = '22023';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT t.id INTO v_lock_lo
    FROM public.orders t
    WHERE t.id = p_target_order_id
      AND t.merge_request_key = p_idempotency_key
    LIMIT 1;
    IF FOUND THEN
      SELECT subtotal, total_amount INTO v_target_subtotal, v_target_total
      FROM public.orders WHERE id = p_target_order_id;
      RETURN jsonb_build_object(
        'source_order_id',  p_source_order_id,
        'target_order_id',  p_target_order_id,
        'target_subtotal',  COALESCE(v_target_subtotal, 0),
        'target_total',     COALESCE(v_target_total, 0),
        'idempotent',       true
      );
    END IF;
  END IF;

  v_lock_lo := LEAST(p_source_order_id, p_target_order_id);
  v_lock_hi := GREATEST(p_source_order_id, p_target_order_id);
  PERFORM pg_advisory_xact_lock(v_lock_lo);
  PERFORM pg_advisory_xact_lock(v_lock_hi);

  IF v_lock_lo = p_source_order_id THEN
    SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
           o.payment_status, o.subtotal, o.service_charge,
           o.discount_type, o.discount_value, o.discount_amount, o.discount_note,
           o.merged_into_order_id, o.note, o.customer_count, o.order_number
    INTO v_source FROM public.orders o WHERE o.id = p_source_order_id FOR UPDATE;

    SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
           o.payment_status, o.subtotal, o.service_charge,
           o.discount_type, o.discount_value, o.discount_amount, o.discount_note,
           o.merged_into_order_id, o.note, o.customer_count, o.order_number
    INTO v_target FROM public.orders o WHERE o.id = p_target_order_id FOR UPDATE;
  ELSE
    SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
           o.payment_status, o.subtotal, o.service_charge,
           o.discount_type, o.discount_value, o.discount_amount, o.discount_note,
           o.merged_into_order_id, o.note, o.customer_count, o.order_number
    INTO v_target FROM public.orders o WHERE o.id = p_target_order_id FOR UPDATE;

    SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
           o.payment_status, o.subtotal, o.service_charge,
           o.discount_type, o.discount_value, o.discount_amount, o.discount_note,
           o.merged_into_order_id, o.note, o.customer_count, o.order_number
    INTO v_source FROM public.orders o WHERE o.id = p_source_order_id FOR UPDATE;
  END IF;

  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'source order not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_target.id IS NULL THEN
    RAISE EXCEPTION 'target order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_source.tenant_id <> v_prof_tenant OR v_target.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_source.branch_id <> v_target.branch_id THEN
    RAISE EXCEPTION 'merge_different_branch' USING ERRCODE = '22023';
  END IF;

  IF v_prof_role IN ('owner', 'super_manager', 'area_manager') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_source.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_source.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_source.tenant_id AND key = 'pos_split_merge_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'split_merge_disabled' USING ERRCODE = 'P0001';
  END IF;

  IF v_source.order_type <> 'dine_in' OR v_target.order_type <> 'dine_in' THEN
    RAISE EXCEPTION 'merge_dine_in_only' USING ERRCODE = '22023';
  END IF;

  IF v_source.table_id IS NULL OR v_target.table_id IS NULL
     OR v_source.table_id <> v_target.table_id
  THEN
    RAISE EXCEPTION 'merge_different_tables' USING ERRCODE = '22023';
  END IF;

  IF v_source.status IN ('completed', 'cancelled')
     OR v_target.status IN ('completed', 'cancelled')
  THEN
    RAISE EXCEPTION 'merge_terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_source.payment_status, 'unpaid') = 'paid'
     OR COALESCE(v_target.payment_status, 'unpaid') = 'paid'
  THEN
    RAISE EXCEPTION 'merge_paid' USING ERRCODE = '22023';
  END IF;

  IF v_source.merged_into_order_id IS NOT NULL OR v_target.merged_into_order_id IS NOT NULL THEN
    RAISE EXCEPTION 'merge_already_merged' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.payments
  WHERE order_id IN (p_source_order_id, p_target_order_id)
    AND status NOT IN ('failed', 'completed');
  IF FOUND THEN
    RAISE EXCEPTION 'merge_payment_pending' USING ERRCODE = '22023';
  END IF;

  IF (v_source.discount_type = 'pct' AND COALESCE(v_source.discount_amount, 0) > 0)
     OR (v_target.discount_type = 'pct' AND COALESCE(v_target.discount_amount, 0) > 0)
  THEN
    RAISE EXCEPTION 'merge_pct_discount_blocked' USING ERRCODE = '22023';
  END IF;

  IF v_source.discount_type = 'vnd' AND v_target.discount_type = 'vnd' THEN
    v_target_discount_type  := 'vnd';
    v_target_discount_value := COALESCE(v_source.discount_value, 0)
                             + COALESCE(v_target.discount_value, 0);
    v_target_discount_note  := COALESCE(v_target.discount_note, '')
      || ' + ' || COALESCE(v_source.discount_note, '');
  ELSIF v_source.discount_type = 'vnd' AND v_target.discount_type IS NULL THEN
    v_target_discount_type  := 'vnd';
    v_target_discount_value := v_source.discount_value;
    v_target_discount_note  := v_source.discount_note;
  ELSIF v_target.discount_type = 'vnd' AND v_source.discount_type IS NULL THEN
    v_target_discount_type  := 'vnd';
    v_target_discount_value := v_target.discount_value;
    v_target_discount_note  := v_target.discount_note;
  ELSE
    v_target_discount_type  := NULL;
    v_target_discount_value := NULL;
    v_target_discount_note  := NULL;
  END IF;

  UPDATE public.order_items
     SET order_id   = p_target_order_id,
         updated_at = now()
   WHERE order_id = p_source_order_id
     AND status <> 'cancelled';
  GET DIAGNOSTICS v_moved_count = ROW_COUNT;

  UPDATE public.kds_tickets
     SET order_id   = p_target_order_id,
         updated_at = now()
   WHERE order_id = p_source_order_id;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_target_subtotal
  FROM public.order_items
  WHERE order_id = p_target_order_id AND status <> 'cancelled';

  v_target_discount_amount := public.compute_discount_amount(
    v_target_discount_type, v_target_discount_value, v_target_subtotal
  );

  v_target_total := v_target_subtotal
                  + COALESCE(v_target.service_charge, 0)
                  - v_target_discount_amount;

  IF v_target_discount_amount = 0 THEN
    v_target_discount_type  := NULL;
    v_target_discount_value := NULL;
    v_target_discount_note  := NULL;
  END IF;

  UPDATE public.orders
     SET subtotal             = v_target_subtotal,
         discount_type        = v_target_discount_type,
         discount_value       = v_target_discount_value,
         discount_note        = v_target_discount_note,
         discount_amount      = v_target_discount_amount,
         total_amount         = v_target_total,
         customer_count       = GREATEST(v_target.customer_count, v_source.customer_count),
         note                 = CASE
                                  WHEN v_source.note IS NOT NULL AND length(trim(v_source.note)) > 0
                                  THEN COALESCE(v_target.note || E'\n', '')
                                       || '[Gộp từ ' || v_source.order_number || ']: ' || v_source.note
                                  ELSE v_target.note
                                END,
         merge_request_key    = p_idempotency_key,
         updated_at           = now()
   WHERE id = p_target_order_id;

  v_source_total := 0 + COALESCE(v_source.service_charge, 0);

  UPDATE public.orders
     SET status               = 'cancelled',
         subtotal             = 0,
         discount_type        = NULL,
         discount_value       = NULL,
         discount_note        = NULL,
         discount_amount      = 0,
         total_amount         = v_source_total,
         merged_into_order_id = p_target_order_id,
         updated_at           = now()
   WHERE id = p_source_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES
    (v_source.tenant_id, p_source_order_id, v_source.status, 'cancelled', v_uid,
     'merged_into: ' || v_target.order_number || ' (#' || p_target_order_id::TEXT
       || '), moved ' || v_moved_count::TEXT || ' items'),
    (v_target.tenant_id, p_target_order_id, v_target.status, v_target.status, v_uid,
     'merged_from: ' || v_source.order_number || ' (#' || p_source_order_id::TEXT
       || '), received ' || v_moved_count::TEXT || ' items');

  RETURN jsonb_build_object(
    'source_order_id',  p_source_order_id,
    'target_order_id',  p_target_order_id,
    'moved_count',      v_moved_count,
    'target_subtotal',  v_target_subtotal,
    'target_total',     v_target_total
  );
END;
$$;


ALTER FUNCTION "public"."merge_orders"("p_source_order_id" bigint, "p_target_order_id" bigint, "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_orders"("p_source_order_id" bigint, "p_target_order_id" bigint, "p_idempotency_key" "uuid") IS 'Gộp source vào target (cùng table + branch + dine_in, cả 2 chưa paid). Source bị cancel với merged_into_order_id pointer. Items + KDS tickets re-point sang target. Discount: pct ở bên nào → BLOCK; VND cộng dồn. Source-side clears discount_type/value/note when subtotal collapses to 0 (satisfies orders_discount_metadata_paired). Lock LEAST/GREATEST(a,b) tránh deadlock cross-merge. Idempotent qua p_idempotency_key.';



CREATE OR REPLACE FUNCTION "public"."next_manual_journal_entry_number"("p_tenant_id" bigint, "p_entry_date" "date") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_date_key TEXT;
  v_next     INT;
  v_suffix   TEXT;
BEGIN
  IF p_tenant_id IS NULL OR p_entry_date IS NULL THEN
    RAISE EXCEPTION 'journal_entry_number: tenant and date required'
      USING ERRCODE = '22023';
  END IF;

  v_date_key := to_char(p_entry_date, 'YYYYMMDD');

  PERFORM pg_advisory_xact_lock(
    hashtextextended('journal_entry_number:' || p_tenant_id::TEXT || ':' || v_date_key, 0)
  );

  SELECT COALESCE(
    MAX(
      substring(entry_number FROM ('^JE-' || v_date_key || '-([0-9]{3,})$'))::INT
    ),
    0
  ) + 1
  INTO v_next
  FROM public.journal_entries
  WHERE tenant_id = p_tenant_id
    AND entry_number LIKE 'JE-' || v_date_key || '-%';

  v_suffix := CASE
    WHEN v_next < 1000 THEN lpad(v_next::TEXT, 3, '0')
    ELSE v_next::TEXT
  END;

  RETURN 'JE-' || v_date_key || '-' || v_suffix;
END;
$_$;


ALTER FUNCTION "public"."next_manual_journal_entry_number"("p_tenant_id" bigint, "p_entry_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_po_display_id"("p_tenant_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_year SMALLINT;
  v_seq  BIGINT;
BEGIN
  IF p_tenant_id IS NULL OR p_tenant_id <= 0 THEN
    RAISE EXCEPTION 'next_po_display_id: invalid tenant_id'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF public.auth_tenant_id() IS NULL OR public.auth_tenant_id() <> p_tenant_id THEN
    RAISE EXCEPTION 'next_po_display_id: tenant scope mismatch'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Year scoped to VN timezone so 23:59 +07 on Dec 31 still allocates 2026.
  v_year := EXTRACT(year FROM (now() AT TIME ZONE 'Asia/Ho_Chi_Minh'))::SMALLINT;

  -- Atomic upsert + increment in a single statement; row lock handles
  -- concurrent callers. Returns the seq this caller owns.
  INSERT INTO public.tenant_po_counters (tenant_id, year, next_seq, updated_at)
  VALUES (p_tenant_id, v_year, 2, now())
  ON CONFLICT (tenant_id, year) DO UPDATE
    SET next_seq = public.tenant_po_counters.next_seq + 1,
        updated_at = now()
  RETURNING (
    CASE
      WHEN xmax::TEXT::INT = 0 THEN 1            -- inserted: caller owns seq=1
      ELSE public.tenant_po_counters.next_seq - 1 -- updated: caller owns prior next_seq
    END
  ) INTO v_seq;

  RETURN 'PO-' || v_year::TEXT || '-' || lpad(v_seq::TEXT, 4, '0');
END;
$$;


ALTER FUNCTION "public"."next_po_display_id"("p_tenant_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."next_po_display_id"("p_tenant_id" bigint) IS 'Atomically allocate the next PO display ID for the caller tenant in current VN-timezone year. Returns PO-YYYY-####. Concurrent-safe via single-statement upsert. Sprint 6 F-017.';



CREATE OR REPLACE FUNCTION "public"."override_grn_hardblock"("p_grn_item_id" bigint, "p_evidence_url" "text", "p_reason_code" "text", "p_note" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_item RECORD; v_baseline RECORD; v_recent INT; v_ov_id BIGINT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT gi.*, grn.branch_id, grn.tenant_id AS grn_tenant, grn.supplier_id AS grn_supplier
    INTO v_item FROM public.grn_items gi
    JOIN public.goods_received_notes grn ON grn.id = gi.grn_id WHERE gi.id = p_grn_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'grn_item not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_item.branch_id, 'inventory:grn_hardblock_override') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_item.variance_tier IS NULL OR v_item.variance_tier < 3 THEN
    RAISE EXCEPTION 'grn_item is not hard-blocked' USING ERRCODE = '22023';
  END IF;
  IF length(COALESCE(p_note, '')) < 50 THEN RAISE EXCEPTION 'note must be at least 50 characters' USING ERRCODE = '22023'; END IF;
  IF p_evidence_url IS NULL OR length(p_evidence_url) = 0 THEN RAISE EXCEPTION 'evidence_url required' USING ERRCODE = '22023'; END IF;
  SELECT COUNT(*) INTO v_recent FROM public.grn_hardblock_overrides
    WHERE overridden_by = v_uid AND overridden_at > now() - INTERVAL '7 days';
  IF v_recent >= 2 THEN RAISE EXCEPTION 'hardblock override rate-limit (2/week) exceeded — escalate to admin' USING ERRCODE = '54000'; END IF;
  SELECT avg_30d INTO v_baseline FROM public._compute_grn_price_baseline(v_item.grn_tenant, v_item.grn_supplier, v_item.ingredient_id, v_item.unit);
  INSERT INTO public.grn_hardblock_overrides (tenant_id, branch_id, grn_item_id, supplier_id, ingredient_id, uom,
    submitted_price, baseline_avg_30d, variance_pct, evidence_url, reason_code, note, overridden_by)
  VALUES (v_item.grn_tenant, v_item.branch_id, p_grn_item_id, v_item.grn_supplier, v_item.ingredient_id, v_item.unit,
    v_item.unit_cost, v_baseline.avg_30d, v_item.baseline_variance_pct, p_evidence_url, p_reason_code, p_note, v_uid)
  RETURNING id INTO v_ov_id;
  INSERT INTO public.grn_baseline_pause (tenant_id, supplier_id, ingredient_id, uom, paused_until, reason, source_ref, created_by)
  VALUES (v_item.grn_tenant, v_item.grn_supplier, v_item.ingredient_id, v_item.unit,
    CURRENT_DATE + INTERVAL '30 days', 'hardblock_override',
    jsonb_build_object('hardblock_override_id', v_ov_id, 'grn_id', v_item.grn_id), v_uid);
  UPDATE public.grn_items SET is_hard_blocked = false WHERE id = p_grn_item_id;
  RETURN v_ov_id;
END; $$;


ALTER FUNCTION "public"."override_grn_hardblock"("p_grn_item_id" bigint, "p_evidence_url" "text", "p_reason_code" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."period_status_at"("p_tenant_id" bigint, "p_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_year INT := EXTRACT(YEAR FROM p_at)::INT; v_month INT := EXTRACT(MONTH FROM p_at)::INT; v_p public.accounting_periods%ROWTYPE;
BEGIN
  SELECT * INTO v_p FROM public.accounting_periods WHERE tenant_id = p_tenant_id AND year = v_year AND month = v_month;
  IF NOT FOUND THEN RETURN 'open'; END IF;
  IF v_p.hard_closed_at IS NOT NULL THEN RETURN 'hard_closed'; END IF;
  IF v_p.soft_closed_at IS NOT NULL THEN RETURN 'soft_closed'; END IF;
  RETURN 'open';
END; $$;


ALTER FUNCTION "public"."period_status_at"("p_tenant_id" bigint, "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."populate_order_item_vat_rate"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only fill when caller didn't explicitly set it. Treats 0.00 as
  -- a legitimate value (VAT-exempt item) so we don't overwrite it.
  IF NEW.vat_rate IS NULL THEN
    SELECT mi.vat_rate INTO NEW.vat_rate
    FROM public.menu_items mi
    WHERE mi.id = NEW.menu_item_id;

    -- Fallback when menu_item is missing (e.g. orphaned reference,
    -- legacy data, or NULL menu_item_id). Default 8% matches the
    -- system-wide default for food.
    IF NEW.vat_rate IS NULL THEN
      NEW.vat_rate := 8.00;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."populate_order_item_vat_rate"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."populate_order_item_vat_rate"() IS 'Fills order_items.vat_rate from menu_items.vat_rate at INSERT time. Rule VAT-PER-LINE-NOT-PER-INVOICE — every order line carries its own VAT rate snapshot so invoice issuance can aggregate correctly even for mixed-rate orders.';



CREATE OR REPLACE FUNCTION "public"."pos_enrich_order_sides"("p_tenant_id" bigint, "p_main_item_id" bigint, "p_sides" "jsonb") RETURNS TABLE("sides_sum" numeric, "enriched_sides" "jsonb")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_raw_count   INT := 0;
  v_valid_count INT := 0;
  v_live_count  INT := 0;
BEGIN
  IF p_sides IS NULL THEN
    RETURN QUERY SELECT 0::NUMERIC(15,2), '[]'::JSONB;
    RETURN;
  END IF;

  IF jsonb_typeof(p_sides) <> 'array' THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  v_raw_count := jsonb_array_length(p_sides);
  IF v_raw_count = 0 THEN
    RETURN QUERY SELECT 0::NUMERIC(15,2), '[]'::JSONB;
    RETURN;
  END IF;

  WITH side_input AS (
    SELECT
      (side_el ->> 'side_item_id')::BIGINT AS side_item_id,
      CASE
        WHEN (side_el ->> 'quantity') ~ '^[0-9]+$'
          THEN LEAST(99, GREATEST(1, (side_el ->> 'quantity')::INT))
        ELSE 1
      END AS quantity
    FROM jsonb_array_elements(p_sides) AS side_el
    WHERE side_el ? 'side_item_id'
      AND (side_el ->> 'side_item_id') ~ '^[0-9]+$'
  )
  SELECT COUNT(*)::INT INTO v_valid_count
  FROM side_input;

  IF v_valid_count <> v_raw_count THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  WITH side_input AS (
    SELECT
      (side_el ->> 'side_item_id')::BIGINT AS side_item_id,
      CASE
        WHEN (side_el ->> 'quantity') ~ '^[0-9]+$'
          THEN LEAST(99, GREATEST(1, (side_el ->> 'quantity')::INT))
        ELSE 1
      END AS quantity
    FROM jsonb_array_elements(p_sides) AS side_el
    WHERE side_el ? 'side_item_id'
      AND (side_el ->> 'side_item_id') ~ '^[0-9]+$'
  ),
  live_sides AS (
    SELECT 1
    FROM side_input si
    JOIN public.menu_item_available_sides mas
      ON mas.tenant_id = p_tenant_id
     AND mas.main_item_id = p_main_item_id
     AND mas.side_item_id = si.side_item_id
    JOIN public.menu_items mi
      ON mi.id = si.side_item_id
     AND mi.tenant_id = p_tenant_id
     AND mi.is_active = TRUE
  )
  SELECT COUNT(*)::INT INTO v_live_count
  FROM live_sides;

  IF v_live_count <> v_valid_count THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH side_input AS (
    SELECT
      (side_el ->> 'side_item_id')::BIGINT AS side_item_id,
      CASE
        WHEN (side_el ->> 'quantity') ~ '^[0-9]+$'
          THEN LEAST(99, GREATEST(1, (side_el ->> 'quantity')::INT))
        ELSE 1
      END AS quantity
    FROM jsonb_array_elements(p_sides) AS side_el
    WHERE side_el ? 'side_item_id'
      AND (side_el ->> 'side_item_id') ~ '^[0-9]+$'
  ),
  live_sides AS (
    SELECT
      mi.id,
      mi.name,
      mi.base_price,
      mas.is_default,
      si.quantity
    FROM side_input si
    JOIN public.menu_item_available_sides mas
      ON mas.tenant_id = p_tenant_id
     AND mas.main_item_id = p_main_item_id
     AND mas.side_item_id = si.side_item_id
    JOIN public.menu_items mi
      ON mi.id = si.side_item_id
     AND mi.tenant_id = p_tenant_id
     AND mi.is_active = TRUE
  )
  SELECT
    COALESCE(SUM(base_price * quantity), 0)::NUMERIC(15,2),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'side_item_id', id,
          'name', name,
          'price', base_price,
          'quantity', quantity,
          'is_default', is_default
        )
        ORDER BY name
      ),
      '[]'::JSONB
    )
  FROM live_sides;
END;
$_$;


ALTER FUNCTION "public"."pos_enrich_order_sides"("p_tenant_id" bigint, "p_main_item_id" bigint, "p_sides" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_order_modifier_sum"("p_tenant_id" bigint, "p_main_item_id" bigint, "p_modifiers" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_raw_count   INT := 0;
  v_valid_count INT := 0;
  v_live_count  INT := 0;
  v_sum         NUMERIC(15,2) := 0;
BEGIN
  IF p_modifiers IS NULL THEN
    RETURN 0;
  END IF;

  IF jsonb_typeof(p_modifiers) <> 'array' THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  v_raw_count := jsonb_array_length(p_modifiers);
  IF v_raw_count = 0 THEN
    RETURN 0;
  END IF;

  WITH modifier_input AS (
    SELECT (mod_el ->> 'modifier_id')::BIGINT AS modifier_id
    FROM jsonb_array_elements(p_modifiers) AS mod_el
    WHERE mod_el ? 'modifier_id'
      AND (mod_el ->> 'modifier_id') ~ '^[0-9]+$'
  )
  SELECT COUNT(*)::INT INTO v_valid_count
  FROM modifier_input;

  IF v_valid_count <> v_raw_count THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  WITH modifier_input AS (
    SELECT (mod_el ->> 'modifier_id')::BIGINT AS modifier_id
    FROM jsonb_array_elements(p_modifiers) AS mod_el
    WHERE mod_el ? 'modifier_id'
      AND (mod_el ->> 'modifier_id') ~ '^[0-9]+$'
  ),
  live_modifiers AS (
    SELECT m.price
    FROM modifier_input mi
    JOIN public.menu_item_modifiers m
      ON m.id = mi.modifier_id
     AND m.item_id = p_main_item_id
     AND m.tenant_id = p_tenant_id
     AND m.is_active = TRUE
  )
  SELECT COUNT(*)::INT, COALESCE(SUM(price), 0)::NUMERIC(15,2)
  INTO v_live_count, v_sum
  FROM live_modifiers;

  IF v_live_count <> v_valid_count THEN
    RAISE EXCEPTION 'stale_side_or_modifier' USING ERRCODE = '22023';
  END IF;

  RETURN v_sum;
END;
$_$;


ALTER FUNCTION "public"."pos_order_modifier_sum"("p_tenant_id" bigint, "p_main_item_id" bigint, "p_modifiers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_manual_journal_entry"("p_entry_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor        UUID := auth.uid();
  v_tenant       BIGINT := public.auth_tenant_id();
  v_entry        RECORD;
  v_total_debit  NUMERIC(15,2);
  v_total_credit NUMERIC(15,2);
  v_line_count   INT;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant claim missing' USING ERRCODE = '28000';
  END IF;

  IF p_entry_id IS NULL THEN
    RAISE EXCEPTION 'entry id required' USING ERRCODE = '22023';
  END IF;

  SELECT id, tenant_id, branch_id, entry_number, status
  INTO v_entry
  FROM public.journal_entries
  WHERE id = p_entry_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'journal entry not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.ensure_journal_write_permission(v_entry.branch_id);

  IF v_entry.status <> 'draft' THEN
    RAISE EXCEPTION 'journal entry must be draft to post' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*), COALESCE(SUM(debit_amount), 0), COALESCE(SUM(credit_amount), 0)
  INTO v_line_count, v_total_debit, v_total_credit
  FROM public.journal_entry_lines
  WHERE journal_entry_id = p_entry_id AND tenant_id = v_tenant;

  IF v_line_count < 2 OR abs(v_total_debit - v_total_credit) > 0.01 OR v_total_debit <= 0 THEN
    RAISE EXCEPTION 'journal entry not balanced' USING ERRCODE = '22023';
  END IF;

  UPDATE public.journal_entries
     SET status = 'posted',
         posted_by = v_actor,
         posted_at = now()
   WHERE id = p_entry_id AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'journal.post', 'journal_entry', p_entry_id,
    jsonb_build_object('status', 'draft'),
    jsonb_build_object('status', 'posted')
  );

  RETURN jsonb_build_object(
    'id', p_entry_id, 'entry_number', v_entry.entry_number, 'status', 'posted'
  );
END;
$$;


ALTER FUNCTION "public"."post_manual_journal_entry"("p_entry_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_manual_journal_entry"("p_entry_id" bigint) IS 'Posts a draft manual journal entry atomically after locking the header and validating balance.';



CREATE OR REPLACE FUNCTION "public"."post_payroll_journal"("p_payroll_period_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_tenant BIGINT := public.auth_tenant_id();
  v_period RECORD; v_totals RECORD; v_lines JSONB := '[]'::JSONB; v_journal_id BIGINT; v_desc TEXT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission_any('finance:payroll_approve') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT pp.* INTO v_period FROM public.payroll_periods pp
  WHERE pp.id = p_payroll_period_id AND pp.tenant_id = v_tenant FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'payroll_period_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_period.status NOT IN ('approved', 'paid') THEN RAISE EXCEPTION 'payroll_not_approved' USING ERRCODE = '22023'; END IF;
  IF v_period.journal_entry_id IS NOT NULL THEN RETURN v_period.journal_entry_id; END IF;

  SELECT
    COALESCE(SUM(pe.gross_total), 0) AS total_gross,
    COALESCE(SUM(pe.bhxh_employee), 0) AS total_bhxh_ee,
    COALESCE(SUM(pe.bhyt_employee), 0) AS total_bhyt_ee,
    COALESCE(SUM(pe.bhtn_employee), 0) AS total_bhtn_ee,
    COALESCE(SUM(pe.bhxh_employer), 0) AS total_bhxh_er,
    COALESCE(SUM(pe.bhyt_employer), 0) AS total_bhyt_er,
    COALESCE(SUM(pe.bhtn_employer), 0) AS total_bhtn_er,
    COALESCE(SUM(pe.pit_tax), 0) AS total_pit
  INTO v_totals
  FROM public.payroll_entries pe
  WHERE pe.payroll_period_id = p_payroll_period_id AND pe.tenant_id = v_tenant;

  IF v_totals.total_gross > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('rule_code','PAYROLL_SALARY','amount',v_totals.total_gross,
      'line_description','Lương T'||v_period.period_month||'/'||v_period.period_year));
  END IF;
  IF v_totals.total_bhxh_er > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('rule_code','PAYROLL_BHXH_ER','amount',v_totals.total_bhxh_er,
      'line_description','BHXH DN T'||v_period.period_month||'/'||v_period.period_year));
  END IF;
  IF v_totals.total_bhyt_er > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('rule_code','PAYROLL_BHYT_ER','amount',v_totals.total_bhyt_er,
      'line_description','BHYT DN T'||v_period.period_month||'/'||v_period.period_year));
  END IF;
  IF v_totals.total_bhtn_er > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('rule_code','PAYROLL_BHTN_ER','amount',v_totals.total_bhtn_er,
      'line_description','BHTN DN T'||v_period.period_month||'/'||v_period.period_year));
  END IF;
  IF v_totals.total_pit > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('rule_code','PAYROLL_PIT','amount',v_totals.total_pit,
      'line_description','Thuế TNCN T'||v_period.period_month||'/'||v_period.period_year));
  END IF;
  IF v_totals.total_bhxh_ee > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('rule_code','PAYROLL_BHXH_EE','amount',v_totals.total_bhxh_ee,
      'line_description','BHXH NLĐ T'||v_period.period_month||'/'||v_period.period_year));
  END IF;
  IF v_totals.total_bhyt_ee > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('rule_code','PAYROLL_BHYT_EE','amount',v_totals.total_bhyt_ee,
      'line_description','BHYT NLĐ T'||v_period.period_month||'/'||v_period.period_year));
  END IF;
  IF v_totals.total_bhtn_ee > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('rule_code','PAYROLL_BHTN_EE','amount',v_totals.total_bhtn_ee,
      'line_description','BHTN NLĐ T'||v_period.period_month||'/'||v_period.period_year));
  END IF;

  v_desc := 'Lương tháng ' || v_period.period_month || '/' || v_period.period_year;
  v_journal_id := public.auto_post_journal(v_tenant, NULL, 'payroll', p_payroll_period_id, v_desc, v_lines,
    (make_date(v_period.period_year, v_period.period_month, 1) + INTERVAL '1 month' - INTERVAL '1 day')::TIMESTAMPTZ, v_uid);
  IF v_journal_id IS NOT NULL THEN
    UPDATE public.payroll_periods SET journal_entry_id = v_journal_id WHERE id = p_payroll_period_id;
  END IF;
  RETURN v_journal_id;
END;
$$;


ALTER FUNCTION "public"."post_payroll_journal"("p_payroll_period_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."print_jobs_attach_document_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.payload IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.job_type NOT IN (
    'receipt',
    'provisional_bill',
    'kitchen_ticket',
    'cancel_ticket',
    'shift_close_report'
  ) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.payload ? 'document' THEN
      NEW.payload := NEW.payload - 'document' - 'template_version';
      NEW.payload := NEW.payload || jsonb_build_object('document', OLD.payload->'document');
      IF OLD.payload ? 'template_version' THEN
        NEW.payload := NEW.payload || jsonb_build_object(
          'template_version',
          OLD.payload->'template_version'
        );
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.payload ? 'document' THEN
    RETURN NEW;
  END IF;

  BEGIN
    NEW.payload := public.attach_print_document_to_payload(
      NEW.tenant_id,
      NEW.branch_id,
      NEW.job_type,
      NEW.payload
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[print_jobs_attach_document_trigger] template apply failed for tenant=% branch=% job_type=%: %',
      NEW.tenant_id, NEW.branch_id, NEW.job_type, SQLERRM;
    RETURN NEW;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."print_jobs_attach_document_trigger"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."print_jobs_attach_document_trigger"() IS 'M5 observability (2026-05-07): template apply fail-soft now emits RAISE WARNING. Behavior unchanged — RETURN NEW preserves legacy payload for agent fallback.';



CREATE OR REPLACE FUNCTION "public"."print_template_block_visible"("p_block" "jsonb", "p_payload" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_field TEXT := p_block->>'when_field';
  v_value TEXT;
  v_other_field TEXT := p_block->>'when_not_equals_field';
  v_numeric NUMERIC;
BEGIN
  IF v_field IS NULL OR v_field = '' THEN
    RETURN true;
  END IF;

  v_value := public.print_template_payload_text(p_payload, v_field);

  IF COALESCE((p_block->>'when_not_empty')::BOOLEAN, false)
     AND COALESCE(NULLIF(btrim(v_value), ''), '') = '' THEN
    RETURN false;
  END IF;

  IF p_block ? 'when_equals'
     AND v_value <> COALESCE(p_block->>'when_equals', '') THEN
    RETURN false;
  END IF;

  IF p_block ? 'when_not_equals'
     AND v_value = COALESCE(p_block->>'when_not_equals', '') THEN
    RETURN false;
  END IF;

  IF v_other_field IS NOT NULL
     AND v_other_field <> ''
     AND v_value = public.print_template_payload_text(p_payload, v_other_field) THEN
    RETURN false;
  END IF;

  IF p_block ? 'when_min' THEN
    BEGIN
      v_numeric := NULLIF(v_value, '')::numeric;
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    IF v_numeric IS NULL OR v_numeric < (p_block->>'when_min')::numeric THEN
      RETURN false;
    END IF;
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."print_template_block_visible"("p_block" "jsonb", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."print_template_datetime"("p_iso" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(p_iso, '') = '' THEN
    RETURN '';
  END IF;

  IF p_iso ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}' THEN
    RETURN substring(p_iso FROM 12 FOR 5)
      || ' '
      || substring(p_iso FROM 9 FOR 2)
      || '/'
      || substring(p_iso FROM 6 FOR 2)
      || '/'
      || substring(p_iso FROM 1 FOR 4);
  END IF;

  RETURN p_iso;
END;
$$;


ALTER FUNCTION "public"."print_template_datetime"("p_iso" "text") OWNER TO "postgres";


