CREATE OR REPLACE FUNCTION "public"."print_template_payment_breakdown_blocks"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
