CREATE OR REPLACE FUNCTION "public"."print_template_text_block"("p_text" "text", "p_align" "text" DEFAULT NULL::"text", "p_bold" boolean DEFAULT false, "p_double" boolean DEFAULT false, "p_inverse" boolean DEFAULT false, "p_strikethrough" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'type', 'text',
    'text', COALESCE(p_text, ''),
    'align', p_align,
    'bold', COALESCE(p_bold, false),
    'double', COALESCE(p_double, false),
    'inverse', COALESCE(p_inverse, false),
    'strikethrough', COALESCE(p_strikethrough, false)
  );
$$;


