CREATE OR REPLACE FUNCTION "public"."register_branch_presence"("p_tenant_id" bigint, "p_branch_id" bigint, "p_agent_id" "text", "p_token_sha256" "text", "p_ip_address" "inet") RETURNS TABLE("ok" boolean, "status" "text", "ip" "text", "skipped" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now TIMESTAMPTZ := now();
  v_token_id BIGINT;
  v_token_revoked_at TIMESTAMPTZ;
  v_agent_branch_id BIGINT;
  v_existing RECORD;
  v_updated_id BIGINT;
BEGIN
  SELECT id, revoked_at
    INTO v_token_id, v_token_revoked_at
  FROM public.printer_agent_presence_tokens
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND agent_id = p_agent_id
    AND token_sha256 = lower(p_token_sha256)
  FOR UPDATE;

  IF v_token_id IS NULL OR v_token_revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT false, 'invalid_token', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  UPDATE public.printer_agent_presence_tokens
  SET last_attempt_at = v_now
  WHERE id = v_token_id
    AND (
      last_attempt_at IS NULL
      OR last_attempt_at <= v_now - INTERVAL '30 seconds'
    )
  RETURNING id INTO v_updated_id;

  IF v_updated_id IS NULL THEN
    RETURN QUERY SELECT false, 'rate_limited', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  SELECT branch_id
    INTO v_agent_branch_id
  FROM public.printer_agents
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND agent_id = p_agent_id;

  IF v_agent_branch_id IS NULL THEN
    RETURN QUERY SELECT false, 'agent_not_registered', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  SELECT id, last_seen_at, revoked_at
    INTO v_existing
  FROM public.branch_trusted_egress_ips
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND ip_address = p_ip_address
  FOR UPDATE;

  IF v_existing.id IS NOT NULL AND v_existing.revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT false, 'ip_revoked', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  IF v_existing.id IS NOT NULL
     AND v_existing.last_seen_at > v_now - INTERVAL '60 seconds' THEN
    UPDATE public.printer_agent_presence_tokens
    SET last_used_at = v_now
    WHERE id = v_token_id;

    RETURN QUERY SELECT true, 'skipped', p_ip_address::TEXT, true;
    RETURN;
  END IF;

  IF v_existing.id IS NOT NULL THEN
    v_updated_id := NULL;

    UPDATE public.branch_trusted_egress_ips
    SET
      registered_via = 'agent',
      registered_by_agent_id = p_agent_id,
      last_seen_at = v_now
    WHERE id = v_existing.id
      AND revoked_at IS NULL
    RETURNING id INTO v_updated_id;

    IF v_updated_id IS NULL THEN
      RETURN QUERY SELECT false, 'ip_revoked', p_ip_address::TEXT, false;
      RETURN;
    END IF;
  ELSE
    INSERT INTO public.branch_trusted_egress_ips (
      tenant_id,
      branch_id,
      ip_address,
      registered_via,
      registered_by_agent_id,
      last_seen_at
    )
    VALUES (
      p_tenant_id,
      p_branch_id,
      p_ip_address,
      'agent',
      p_agent_id,
      v_now
    );
  END IF;

  UPDATE public.printer_agent_presence_tokens
  SET last_used_at = v_now
  WHERE id = v_token_id;

  RETURN QUERY SELECT true, 'ok', p_ip_address::TEXT, false;
END;
$$;


ALTER FUNCTION "public"."register_branch_presence"("p_tenant_id" bigint, "p_branch_id" bigint, "p_agent_id" "text", "p_token_sha256" "text", "p_ip_address" "inet") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."register_branch_presence"("p_tenant_id" bigint, "p_branch_id" bigint, "p_agent_id" "text", "p_token_sha256" "text", "p_ip_address" "inet") IS 'Service-role-only atomic branch presence registration. Validates per-agent token hash, rate-limits 1/30s, and never clears revoked trusted IP rows.';



CREATE OR REPLACE FUNCTION "public"."reject_shift_request"("p_request_id" bigint, "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_user_id   UUID   := auth.uid();
  v_request   public.shift_requests%ROWTYPE;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'reject_shift_request: missing auth context' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_request FROM public.shift_requests
  WHERE id = p_request_id AND tenant_id = v_tenant_id FOR UPDATE;
  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'reject_shift_request: request not found' USING ERRCODE = 'no_data_found';
  END IF;
  IF NOT public.has_permission(v_request.branch_id, 'hr:approve_shift_request') THEN
    RAISE EXCEPTION 'reject_shift_request: missing permission for this branch' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'reject_shift_request: request is %, not pending', v_request.status USING ERRCODE = 'check_violation';
  END IF;
  UPDATE public.shift_requests
  SET status = 'rejected', reviewed_by = v_user_id, reviewed_at = now(), rejected_reason = p_reason
  WHERE id = p_request_id;
  PERFORM public.log_audit(
    'reject'::TEXT, 'shift_request'::TEXT, p_request_id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'rejected', 'reason', p_reason)
  );
END;
$$;


ALTER FUNCTION "public"."reject_shift_request"("p_request_id" bigint, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_table"("p_table_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.tables
  SET status = 'available'
  WHERE id = p_table_id
    AND branch_id = public.auth_branch_id()
    AND tenant_id = public.auth_tenant_id();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Table not found or not in your branch' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


ALTER FUNCTION "public"."release_table"("p_table_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_zone_lock"("p_session_id" bigint, "p_zone_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_count INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  DELETE FROM public.stocktake_zone_locks WHERE session_id = p_session_id AND zone_id = p_zone_id AND locked_by = v_uid;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count > 0;
END; $$;


