      'Kiểm tra số lượng, giá, ảnh chứng từ rồi chốt nhập kho',
      'grn',
      NEW.id,
      format('/inventory/grn/%s', NEW.id),
      jsonb_build_object('grn_number', NEW.grn_number, 'po_id', NEW.po_id)
    );
  END IF;
  RETURN NEW;
END;
$$;


