      format('Chuyển kho %s đang về', NEW.transfer_number),
      'Chuẩn bị nhận hàng từ chi nhánh đối ứng',
      'stock_transfer',
      NEW.id,
      format('/inventory/transfers/%s', NEW.id),
      jsonb_build_object(
        'transfer_number', NEW.transfer_number,
        'from_branch_id', NEW.from_branch_id
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


