CREATE OR REPLACE FUNCTION "public"."upsert_printer_with_routes"("p_printer_id" bigint DEFAULT NULL::bigint, "p_branch_id" bigint DEFAULT NULL::bigint, "p_role" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text", "p_lan_host" "text" DEFAULT NULL::"text", "p_lan_port" integer DEFAULT NULL::integer, "p_paper_width_mm" smallint DEFAULT 80, "p_code_page" "text" DEFAULT 'CP1258'::"text", "p_is_active" boolean DEFAULT true, "p_print_types" "text"[] DEFAULT ARRAY[]::"text"[], "p_category_ids" bigint[] DEFAULT ARRAY[]::bigint[]) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_tenant_id BIGINT;
  v_claim_branch_id BIGINT;
  v_existing RECORD;
  v_printer_id BIGINT;
  v_print_type TEXT;
  v_category_id BIGINT;
  v_allowed_print_types TEXT[] := ARRAY[
    'receipt',
    'provisional_bill',
    'shift_close_report',
    'kitchen_ticket',
    'cancel_ticket'
  ];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  v_tenant_id := public.auth_tenant_id();
  v_claim_branch_id := public.auth_branch_id();

  IF p_branch_id IS NULL OR p_role IS NULL OR p_name IS NULL THEN
    RAISE EXCEPTION 'invalid_printer_payload' USING ERRCODE = '22023';
  END IF;

  IF v_claim_branch_id IS NOT NULL AND v_claim_branch_id <> p_branch_id THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'printer:manage') THEN
    RAISE EXCEPTION 'permission denied: printer:manage' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.branches
  WHERE id = p_branch_id
    AND tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;

  IF p_role NOT IN ('receipt', 'kitchen_1', 'kitchen_2') THEN
    RAISE EXCEPTION 'invalid printer role' USING ERRCODE = '22023';
  END IF;

  IF NULLIF(trim(COALESCE(p_lan_host, '')), '') IS NULL THEN
    RAISE EXCEPTION 'lan host required' USING ERRCODE = '22023';
  END IF;

  IF p_paper_width_mm NOT IN (58, 80) THEN
    RAISE EXCEPTION 'invalid paper width' USING ERRCODE = '22023';
  END IF;

  FOREACH v_print_type IN ARRAY COALESCE(p_print_types, ARRAY[]::TEXT[])
  LOOP
    IF NOT v_print_type = ANY(v_allowed_print_types) THEN
      RAISE EXCEPTION 'invalid print type: %', v_print_type USING ERRCODE = '22023';
    END IF;
  END LOOP;

  FOREACH v_category_id IN ARRAY COALESCE(p_category_ids, ARRAY[]::BIGINT[])
  LOOP
    PERFORM 1
    FROM public.menu_categories
    WHERE id = v_category_id
      AND tenant_id = v_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'category not found: %', v_category_id USING ERRCODE = 'P0002';
    END IF;
  END LOOP;

  IF p_printer_id IS NOT NULL THEN
    SELECT id, branch_id, role
    INTO v_existing
    FROM public.printers
    WHERE id = p_printer_id
      AND tenant_id = v_tenant_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'printer not found' USING ERRCODE = 'P0002';
    END IF;

    IF v_existing.branch_id <> p_branch_id THEN
      RAISE EXCEPTION 'cannot move printer across branches' USING ERRCODE = '22023';
    END IF;

    UPDATE public.printers
       SET role = p_role,
           name = trim(p_name),
           connection_type = 'lan',
           lan_host = trim(p_lan_host),
           lan_port = COALESCE(p_lan_port, 9100),
           paper_width_mm = p_paper_width_mm,
           code_page = COALESCE(NULLIF(trim(p_code_page), ''), 'CP1258'),
           is_active = COALESCE(p_is_active, TRUE)
     WHERE id = p_printer_id
       AND tenant_id = v_tenant_id
     RETURNING id INTO v_printer_id;
  ELSE
    INSERT INTO public.printers (
      tenant_id,
      branch_id,
      role,
      name,
      connection_type,
      lan_host,
      lan_port,
      paper_width_mm,
      code_page,
      is_active
    ) VALUES (
      v_tenant_id,
      p_branch_id,
      p_role,
      trim(p_name),
      'lan',
      trim(p_lan_host),
      COALESCE(p_lan_port, 9100),
      p_paper_width_mm,
      COALESCE(NULLIF(trim(p_code_page), ''), 'CP1258'),
      COALESCE(p_is_active, TRUE)
    )
    RETURNING id INTO v_printer_id;
  END IF;

  DELETE FROM public.printer_print_types ppt
  WHERE ppt.tenant_id = v_tenant_id
    AND ppt.branch_id = p_branch_id
    AND ppt.printer_id <> v_printer_id
    AND ppt.print_type = ANY(COALESCE(p_print_types, ARRAY[]::TEXT[]))
    AND ppt.print_type IN ('receipt', 'provisional_bill', 'shift_close_report');

  DELETE FROM public.printer_print_types
  WHERE tenant_id = v_tenant_id
    AND branch_id = p_branch_id
    AND printer_id = v_printer_id;

  INSERT INTO public.printer_print_types (tenant_id, branch_id, printer_id, print_type)
  SELECT v_tenant_id, p_branch_id, v_printer_id, unnest(COALESCE(p_print_types, ARRAY[]::TEXT[]))
  ON CONFLICT (tenant_id, branch_id, printer_id, print_type) DO NOTHING;

  DELETE FROM public.printer_menu_categories
  WHERE tenant_id = v_tenant_id
    AND branch_id = p_branch_id
    AND printer_id = v_printer_id;

  IF COALESCE(array_length(p_category_ids, 1), 0) > 0 THEN
    DELETE FROM public.printer_menu_categories
    WHERE tenant_id = v_tenant_id
      AND branch_id = p_branch_id
      AND category_id = ANY(p_category_ids);

    INSERT INTO public.printer_menu_categories (
      tenant_id,
      branch_id,
      printer_id,
      category_id
    )
    SELECT DISTINCT v_tenant_id, p_branch_id, v_printer_id, x.category_id
    FROM unnest(p_category_ids) AS x(category_id)
    ON CONFLICT (tenant_id, branch_id, category_id) DO UPDATE
      SET printer_id = EXCLUDED.printer_id;
  END IF;

  RETURN v_printer_id;
END;
$$;


ALTER FUNCTION "public"."upsert_printer_with_routes"("p_printer_id" bigint, "p_branch_id" bigint, "p_role" "text", "p_name" "text", "p_lan_host" "text", "p_lan_port" integer, "p_paper_width_mm" smallint, "p_code_page" "text", "p_is_active" boolean, "p_print_types" "text"[], "p_category_ids" bigint[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_printer_with_routes"("p_printer_id" bigint, "p_branch_id" bigint, "p_role" "text", "p_name" "text", "p_lan_host" "text", "p_lan_port" integer, "p_paper_width_mm" smallint, "p_code_page" "text", "p_is_active" boolean, "p_print_types" "text"[], "p_category_ids" bigint[]) IS 'Upsert a branch printer (LAN-only) and its print-type/category routes. Printer role is a slot label only; routing choices are not role-restricted.';



CREATE OR REPLACE FUNCTION "public"."upsert_production_recipe_lines"("p_finished_good_id" bigint, "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid           UUID   := auth.uid();
  v_tenant        BIGINT := public.auth_tenant_id();
  v_kept          BIGINT[] := ARRAY[]::BIGINT[];
  v_line          JSONB;
  v_ingredient_id BIGINT;
  v_quantity      NUMERIC;
  v_yield_factor  NUMERIC;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.is_inventory_production_operator() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('menu:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.ingredients i
    WHERE i.id = p_finished_good_id AND i.tenant_id = v_tenant
      AND i.item_kind = 'finished_good' AND i.is_active = TRUE
  ) THEN
    RAISE EXCEPTION 'finished_good_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'lines_must_be_array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'lines_must_not_be_empty' USING ERRCODE = '22023';
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    IF (v_line->>'ingredient_id') IS NULL OR (v_line->>'quantity') IS NULL
       OR (v_line->>'unit') IS NULL OR btrim(v_line->>'unit') = '' THEN
      RAISE EXCEPTION 'invalid_line_shape' USING ERRCODE = '22023';
    END IF;

    v_ingredient_id := (v_line->>'ingredient_id')::BIGINT;
    v_quantity := (v_line->>'quantity')::NUMERIC;
    v_yield_factor := COALESCE(NULLIF(v_line->>'yield_factor', '')::NUMERIC, 1.000);

    IF v_quantity <= 0 OR v_yield_factor <= 0 THEN
      RAISE EXCEPTION 'invalid_line_quantity' USING ERRCODE = '22023';
    END IF;

    IF v_ingredient_id = ANY(v_kept) THEN
      RAISE EXCEPTION 'duplicate_ingredient' USING ERRCODE = '23505';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.ingredients i
      WHERE i.id = v_ingredient_id AND i.tenant_id = v_tenant
        AND i.item_kind = 'raw_material' AND i.is_active = TRUE
    ) THEN
      RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
    END IF;

    INSERT INTO public.production_recipes (
      tenant_id, finished_good_id, ingredient_id,
      quantity, unit, note, yield_factor
    )
    VALUES (
      v_tenant, p_finished_good_id, v_ingredient_id,
      v_quantity, btrim(v_line->>'unit'),
      NULLIF(v_line->>'note', ''), v_yield_factor
    )
    ON CONFLICT (finished_good_id, ingredient_id, tenant_id)
    DO UPDATE SET
      quantity = EXCLUDED.quantity, unit = EXCLUDED.unit,
      note = EXCLUDED.note, yield_factor = EXCLUDED.yield_factor;

    v_kept := v_kept || v_ingredient_id;
  END LOOP;

  DELETE FROM public.production_recipes pr
  WHERE pr.tenant_id = v_tenant
    AND pr.finished_good_id = p_finished_good_id
    AND NOT (pr.ingredient_id = ANY(v_kept));

  RETURN jsonb_build_object(
    'finished_good_id', p_finished_good_id,
    'kept_count', COALESCE(array_length(v_kept, 1), 0)
  );
END;
$$;


ALTER FUNCTION "public"."upsert_production_recipe_lines"("p_finished_good_id" bigint, "p_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_production_recipe_lines"("p_finished_good_id" bigint, "p_lines" "jsonb") IS 'Atomically replaces production BOM lines for one finished good.';



CREATE OR REPLACE FUNCTION "public"."upsert_recipe_lines"("p_menu_item_id" bigint, "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID   := auth.uid();
  v_tenant BIGINT := public.auth_tenant_id();
  v_kept   BIGINT[] := ARRAY[]::BIGINT[];
  v_line   JSONB;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission_any('menu:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.menu_items mi WHERE mi.id = p_menu_item_id AND mi.tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'menu_item_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF jsonb_typeof(p_lines) <> 'array' THEN RAISE EXCEPTION 'lines_must_be_array' USING ERRCODE = '22023'; END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    IF (v_line->>'ingredient_id') IS NULL OR (v_line->>'quantity') IS NULL OR (v_line->>'unit') IS NULL THEN
      RAISE EXCEPTION 'invalid_line_shape' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.recipes (tenant_id, menu_item_id, ingredient_id, quantity, unit, note, yield_factor)
    VALUES (v_tenant, p_menu_item_id, (v_line->>'ingredient_id')::BIGINT,
            (v_line->>'quantity')::NUMERIC, v_line->>'unit',
            NULLIF(v_line->>'note',''), COALESCE((v_line->>'yield_factor')::NUMERIC, 1.000))
    ON CONFLICT (menu_item_id, ingredient_id, tenant_id)
    DO UPDATE SET quantity = EXCLUDED.quantity, unit = EXCLUDED.unit,
                  note = EXCLUDED.note, yield_factor = EXCLUDED.yield_factor;
    v_kept := v_kept || (v_line->>'ingredient_id')::BIGINT;
  END LOOP;

  DELETE FROM public.recipes r
  WHERE r.tenant_id = v_tenant AND r.menu_item_id = p_menu_item_id
    AND NOT (r.ingredient_id = ANY(v_kept));

  RETURN jsonb_build_object('menu_item_id', p_menu_item_id, 'kept_count', COALESCE(array_length(v_kept, 1), 0));
END;
$$;


ALTER FUNCTION "public"."upsert_recipe_lines"("p_menu_item_id" bigint, "p_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_recipe_lines"("p_menu_item_id" bigint, "p_lines" "jsonb") IS 'Atomically replace the recipe lines of a menu item (finished product). Inserts/updates provided lines and deletes removed ones.';



CREATE OR REPLACE FUNCTION "public"."validate_journal_balance"("p_entry_id" bigint) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_debit  NUMERIC(15,2);
  v_credit NUMERIC(15,2);
BEGIN
  SELECT COALESCE(SUM(debit_amount), 0), COALESCE(SUM(credit_amount), 0)
  INTO v_debit, v_credit
  FROM public.journal_entry_lines
  WHERE journal_entry_id = p_entry_id;

  RETURN v_debit = v_credit AND v_debit > 0;
END;
$$;


ALTER FUNCTION "public"."validate_journal_balance"("p_entry_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_branch_override_code"("p_branch_id" bigint, "p_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_hash TEXT; v_recent_fail INT; v_ok BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT COUNT(*) INTO v_recent_fail FROM public.branch_override_attempts
   WHERE branch_id = p_branch_id AND user_id = v_uid AND success = false
     AND attempted_at > now() - INTERVAL '1 minute';
  IF v_recent_fail >= 3 THEN RAISE EXCEPTION 'override verify rate-limited' USING ERRCODE = '54000'; END IF;
  SELECT code_hash INTO v_hash FROM public.branch_override_codes WHERE branch_id = p_branch_id;
  v_ok := v_hash IS NOT NULL AND extensions.crypt(p_code, v_hash) = v_hash;
  INSERT INTO public.branch_override_attempts (branch_id, user_id, success) VALUES (p_branch_id, v_uid, v_ok);
  RETURN v_ok;
END;
$$;


ALTER FUNCTION "public"."verify_branch_override_code"("p_branch_id" bigint, "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_manual_journal_entry"("p_entry_id" bigint, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor                UUID := auth.uid();
  v_tenant               BIGINT := public.auth_tenant_id();
  v_entry                RECORD;
  v_reason               TEXT;
  v_reverse_id           BIGINT;
  v_reverse_entry_number TEXT;
  v_reverse_date         DATE := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::DATE;
  v_period_status        TEXT;
  v_period_year          INT;
  v_period_month         INT;
  v_line_count           INT;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant claim missing' USING ERRCODE = '28000';
  END IF;

  IF p_entry_id IS NULL THEN
    RAISE EXCEPTION 'entry id required' USING ERRCODE = '22023';
  END IF;

  v_reason := btrim(COALESCE(p_reason, ''));
  IF length(v_reason) < 20 OR length(v_reason) > 500 THEN
    RAISE EXCEPTION 'void reason invalid' USING ERRCODE = '22023';
  END IF;

  SELECT id, tenant_id, branch_id, entry_number, entry_date, description,
         reference_type, reference_id, status, void_journal_entry_id
  INTO v_entry
  FROM public.journal_entries
  WHERE id = p_entry_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'journal entry not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.ensure_journal_write_permission(v_entry.branch_id);

  IF v_entry.status = 'voided' THEN
    RETURN jsonb_build_object(
      'id', p_entry_id, 'status', 'already_voided',
      'void_journal_entry_id', v_entry.void_journal_entry_id
    );
  END IF;
  IF v_entry.status NOT IN ('draft', 'posted') THEN
    RAISE EXCEPTION 'journal entry cannot be voided from status %', v_entry.status
      USING ERRCODE = '22023';
  END IF;

  IF v_entry.status = 'draft' THEN
    UPDATE public.journal_entries
       SET status = 'voided',
           voided_reason = v_reason,
           voided_by = v_actor,
           voided_at = now()
     WHERE id = p_entry_id AND tenant_id = v_tenant;

    PERFORM public.log_audit(
      'journal.void', 'journal_entry', p_entry_id,
      jsonb_build_object('status', 'draft'),
      jsonb_build_object('status', 'voided', 'reason', v_reason)
    );

    RETURN jsonb_build_object(
      'id', p_entry_id, 'status', 'voided', 'void_journal_entry_id', NULL
    );
  END IF;

  v_period_year := EXTRACT(YEAR FROM v_reverse_date)::INT;
  v_period_month := EXTRACT(MONTH FROM v_reverse_date)::INT;

  SELECT fp.status INTO v_period_status
  FROM public.fiscal_periods fp
  WHERE fp.tenant_id = v_tenant
    AND fp.period_year = v_period_year
    AND fp.period_month = v_period_month
  FOR SHARE;

  IF v_period_status = 'closed' THEN
    RAISE EXCEPTION 'current_period_closed_cannot_reverse' USING ERRCODE = '23514';
  END IF;

  IF v_period_status IS NULL THEN
    INSERT INTO public.fiscal_periods (tenant_id, period_month, period_year, status)
    VALUES (v_tenant, v_period_month, v_period_year, 'open')
    ON CONFLICT (period_month, period_year, tenant_id) DO NOTHING;
  END IF;

  v_reverse_entry_number := public.next_manual_journal_entry_number(v_tenant, v_reverse_date);

  INSERT INTO public.journal_entries (
    tenant_id, branch_id, entry_number, entry_date, description,
    reference_type, reference_id, status,
    posted_by, posted_at, created_by
  ) VALUES (
    v_tenant, v_entry.branch_id, v_reverse_entry_number,
    v_reverse_date::TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh',
    'Đảo bút toán ' || v_entry.entry_number || ': ' || v_reason,
    'adjustment', p_entry_id, 'posted',
    v_actor, now(), v_actor
  )
  RETURNING id INTO v_reverse_id;

  PERFORM 1 FROM public.journal_entries
  WHERE id = v_reverse_id AND tenant_id = v_tenant FOR UPDATE;

  INSERT INTO public.journal_entry_lines (
    tenant_id, journal_entry_id, account_id,
    debit_amount, credit_amount, description
  )
  SELECT v_tenant, v_reverse_id,
    account_id, credit_amount, debit_amount,
    'Đảo dòng từ ' || v_entry.entry_number
  FROM public.journal_entry_lines
  WHERE journal_entry_id = p_entry_id AND tenant_id = v_tenant;

  GET DIAGNOSTICS v_line_count = ROW_COUNT;
  IF v_line_count = 0 THEN
    RAISE EXCEPTION 'posted journal entry has no lines' USING ERRCODE = '22023';
  END IF;

  UPDATE public.journal_entries
     SET status = 'voided',
         voided_reason = v_reason,
         voided_by = v_actor,
         voided_at = now(),
         void_journal_entry_id = v_reverse_id
   WHERE id = p_entry_id AND tenant_id = v_tenant;

  PERFORM public.log_audit(
    'journal.void', 'journal_entry', p_entry_id,
    jsonb_build_object('status', 'posted'),
    jsonb_build_object(
      'status', 'voided', 'reason', v_reason,
      'void_journal_entry_id', v_reverse_id
    )
  );

  RETURN jsonb_build_object(
    'id', p_entry_id, 'status', 'voided',
    'void_journal_entry_id', v_reverse_id,
    'void_journal_entry_number', v_reverse_entry_number
  );
END;
$$;


ALTER FUNCTION "public"."void_manual_journal_entry"("p_entry_id" bigint, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."void_manual_journal_entry"("p_entry_id" bigint, "p_reason" "text") IS 'Voids draft entries directly. For posted entries, creates a reversing posted entry in the current period, then marks the original voided.';



CREATE OR REPLACE FUNCTION "public"."void_order_item"("p_order_item_id" bigint, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_prof_tenant     BIGINT;
  v_prof_branch     BIGINT;
  v_prof_role       TEXT;
  v_item            RECORD;
  v_order           RECORD;
  v_subtotal        NUMERIC(15,2);
  v_discount_amount NUMERIC(15,2);
  v_all_cancelled   BOOLEAN;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(po.legacy_role_code, 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'waiter') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_item.order_id);

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_item.status IN ('served', 'cancelled') THEN
    RAISE EXCEPTION 'item not voidable' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
  SET status = 'cancelled',
      cancel_reason = p_reason,
      updated_at = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET status = 'cancelled', updated_at = now()
  WHERE order_item_id = p_order_item_id AND tenant_id = v_item.tenant_id;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal
  FROM public.order_items
  WHERE order_id = v_item.order_id AND status <> 'cancelled';

  SELECT NOT EXISTS (
    SELECT 1 FROM public.order_items WHERE order_id = v_item.order_id AND status <> 'cancelled'
  ) INTO v_all_cancelled;

  IF v_all_cancelled THEN
    UPDATE public.orders
    SET
      status          = 'cancelled',
      subtotal        = 0,
      discount_type   = NULL,
      discount_value  = NULL,
      discount_note   = NULL,
      discount_amount = 0,
      total_amount    = 0 + COALESCE(service_charge, 0),
      updated_at      = now()
    WHERE id = v_item.order_id;

    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    )
    VALUES (
      v_item.tenant_id, v_item.order_id, v_order.status, 'cancelled', v_uid,
      'auto_cancel_all_items_voided: ' || p_reason
    );
  ELSE
    v_discount_amount := public.compute_discount_amount(
      v_order.discount_type, v_order.discount_value, v_subtotal
    );

    UPDATE public.orders o
    SET
      subtotal        = v_subtotal,
      discount_type   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_type END,
      discount_value  = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_value END,
      discount_note   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_note END,
      discount_amount = v_discount_amount,
      total_amount    = v_subtotal + COALESCE(o.service_charge, 0) - v_discount_amount,
      updated_at      = now()
    WHERE o.id = v_item.order_id;

    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    )
    VALUES (
      v_item.tenant_id, v_item.order_id, v_order.status, v_order.status, v_uid,
      'void_item ' || p_order_item_id::text || ': ' || p_reason
    );
  END IF;

  RETURN jsonb_build_object(
    'order_id', v_item.order_id,
    'auto_cancelled_order', v_all_cancelled,
    'was_sent_to_kitchen', v_item.sent_to_kitchen_at IS NOT NULL
  );
END;
$$;


ALTER FUNCTION "public"."void_order_item"("p_order_item_id" bigint, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_grn_override_report"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_row RECORD; v_count INT := 0;
BEGIN
  FOR v_row IN
    SELECT ho.tenant_id, ho.branch_id, COUNT(*) AS override_count,
           COUNT(DISTINCT ho.overridden_by) AS distinct_users,
           SUM(ho.submitted_price - COALESCE(ho.baseline_avg_30d, 0)) AS total_markup_vnd
    FROM public.grn_hardblock_overrides ho
    WHERE ho.overridden_at > now() - INTERVAL '7 days'
    GROUP BY ho.tenant_id, ho.branch_id HAVING COUNT(*) >= 1
  LOOP
    INSERT INTO public.notifications (tenant_id, target_branch_id, target_roles, kind, severity, title, body, meta, dedup_key)
    VALUES (v_row.tenant_id, v_row.branch_id, ARRAY['owner','super_manager','quan_ly_vung']::TEXT[],
            'inventory.grn.weekly_override_report',
            CASE WHEN v_row.override_count >= 5 THEN 'warning' ELSE 'info' END,
            'GRN hardblock override — weekly report',
            format('Branch has %s hardblock overrides by %s user(s) in past 7 days. Total markup: %s VND',
                   v_row.override_count, v_row.distinct_users, v_row.total_markup_vnd),
            jsonb_build_object('override_count', v_row.override_count, 'distinct_users', v_row.distinct_users, 'total_markup_vnd', v_row.total_markup_vnd),
            format('grn_override_report:%s:%s', v_row.branch_id, to_char(now(), 'IYYY-IW')));
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END; $$;


ALTER FUNCTION "public"."weekly_grn_override_report"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_waste_report"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_row RECORD; v_count INT := 0;
BEGIN
  FOR v_row IN
    SELECT si.tenant_id, si.branch_id, COUNT(*) AS waste_count,
      COUNT(*) FILTER (WHERE si.approval_status = 'pending')  AS pending_count,
      COUNT(*) FILTER (WHERE si.approval_status = 'approved') AS approved_count,
      COUNT(*) FILTER (WHERE si.approval_status = 'rejected') AS rejected_count,
      COALESCE(SUM(sii.total_cost), 0) AS total_value
    FROM public.stock_issues si JOIN public.stock_issue_items sii ON sii.issue_id = si.id
    WHERE si.issue_type = 'writeoff' AND si.issued_at > now() - INTERVAL '7 days'
    GROUP BY si.tenant_id, si.branch_id
  LOOP
    INSERT INTO public.notifications (tenant_id, target_branch_id, target_roles, kind, severity, title, body, meta, dedup_key)
    VALUES (v_row.tenant_id, v_row.branch_id, ARRAY['owner','super_manager','quan_ly_vung','quan_ly_CN']::TEXT[],
      'inventory.waste.weekly_report',
      CASE WHEN v_row.pending_count >= 5 THEN 'warning' ELSE 'info' END,
      'Báo cáo waste — tuần vừa qua',
      format('Chi nhánh có %s phiếu waste tuần qua (pending: %s, approved: %s, rejected: %s). Tổng giá trị: %s VND',
             v_row.waste_count, v_row.pending_count, v_row.approved_count, v_row.rejected_count, v_row.total_value),
      jsonb_build_object('waste_count', v_row.waste_count, 'pending_count', v_row.pending_count,
        'approved_count', v_row.approved_count, 'rejected_count', v_row.rejected_count, 'total_value', v_row.total_value),
      format('waste_report:%s:%s', v_row.branch_id, to_char(now(), 'IYYY-IW')));
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END; $$;


ALTER FUNCTION "public"."weekly_waste_report"() OWNER TO "postgres";

