CREATE MATERIALIZED VIEW "public"."mv_top_items" AS
 SELECT ("date_trunc"('week'::"text", "o"."created_at"))::"date" AS "period_start",
    (("date_trunc"('week'::"text", "o"."created_at") + '6 days'::interval))::"date" AS "period_end",
    "o"."branch_id",
