  GROUP BY (("date_trunc"('week'::"text", "o"."created_at"))::"date"), ((("date_trunc"('week'::"text", "o"."created_at") + '6 days'::interval))::"date"), "o"."branch_id", "o"."tenant_id", "oi"."menu_item_id"
